((SELECT id FROM chapters WHERE code = 'CH0' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B0', 'CHƯƠNG I', 1, 1, $JSON$
{
  "content": [
    "# VẬT LÍ 10",
    "",
    "VŨ VĂN HÙNG (Tổng Chủ biên)",
    "BÙI GIA THỊNH (Chủ biên)",
    "PHẠM KIM CHUNG - TÔ GIANG",
    "NGUYỄN XUÂN QUANG - NGUYỄN VĂN THỤ",
    "",
    "KẾT NỐI TRI THỨC VỚI CUỘC SỐNG",
    "",
    "NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM",
    "VŨ VĂN HÙNG (Tổng Chủ biên)",
    "BÙI GIA THỊNH (Chủ biên)",
    "PHẠM KIM CHUNG - TÔ GIANG",
    "NGUYỄN XUÂN QUANG - NGUYỄN VĂN THỤ",
    "",
    "# VẬT LÍ 10",
    "(Bản in thử)",
    "",
    "KẾT NỐI TRI THỨC VỚI CUỘC SỐNG",
    "",
    "NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM",
    "# HƯỚNG DẪN SỬ DỤNG SÁCH",
    "",
    "Sách giáo khoa *Vật lí 10* gồm 7 chương. Mỗi chương gồm một số bài học. Mỗi bài học là một chuỗi các nội dung kiến thức và nhiệm vụ học tập, cụ thể như sau:",
    "",
    "**Khởi động**",
    "Tiếp cận bài mới bằng sự tò mò, hứng thú học tập.",
    "",
    "**Đọc hiểu**",
    "Cung cấp hiện tượng, dữ liệu ban đầu, thuật ngữ cần thiết để tiến hành hoạt động tìm tòi, khám phá kiến thức tiếp theo.",
    "",
    "**? Câu hỏi**",
    "Câu hỏi sẽ giúp học sinh:",
    "– Tìm tòi, khám phá kiến thức.",
    "– Vận dụng kiến thức để giải bài tập.",
    "",
    "**Hoạt động**",
    "Tiến hành các hoạt động giúp học sinh giải quyết các vấn đề học tập và đồng thời phát triển các năng lực cần thiết.",
    "",
    "**! Những điều cần lưu ý.**",
    "",
    "**EM ĐÃ HỌC**",
    "Tổng kết kiến thức và kĩ năng cơ bản của bài.",
    "",
    "**EM CÓ THỂ**",
    "Yêu cầu về năng lực vận dụng kiến thức vào học tập và thực tiễn cuộc sống.",
    "",
    "**EM CÓ BIẾT?**",
    "Mở rộng kiến thức của bài.",
    "",
    "Hoạt động trải nghiệm yêu cầu học sinh vận dụng kiến thức, kĩ năng đã học vào một số tình huống của thực tế cuộc sống.",
    "",
    "*Hãy bảo quản, giữ gìn sách giáo khoa để dành tặng các em học sinh lớp sau!*",
    "",
    "2",
    "# LỜI NÓI ĐẦU",
    "",
    "Sách giáo khoa *Vật lí 10* với thông điệp *Kết nối tri thức với cuộc sống* được biên soạn theo định hướng đổi mới giáo dục phổ thông nhằm phát triển phẩm chất, năng lực của người học. Tư tưởng chủ đạo trong việc biên soạn sách giáo khoa này là tổ chức các hoạt động học tập nhằm coi trọng việc phát triển phẩm chất, năng lực học sinh nhưng không coi nhẹ vai trò của kiến thức. Kiến thức trong sách giáo khoa *Vật lí 10* được coi là chất liệu làm cơ sở giúp học sinh hình thành và phát triển các phẩm chất và năng lực cần có trong cuộc sống hiện tại và tương lai.",
    "",
    "Sách giáo khoa *Vật lí 10* không phải là cuốn sách trình bày sẵn các nội dung kiến thức cần học mà là cuốn sách hướng dẫn học sinh hoạt động để tìm tòi, khám phá ra kiến thức mới, vận dụng chúng vào việc giải quyết các vấn đề trong học tập và cuộc sống. Thông qua các hoạt động học tập này, các em không những hình thành và phát triển các năng lực khoa học nói chung và vật lí nói riêng mà còn đồng thời hình thành và phát triển được các năng lực chung như năng lực tự chủ và tự học, giao tiếp và hợp tác, giải quyết vấn đề và sáng tạo,...",
    "",
    "Sách giáo khoa *Vật lí 10* coi trọng phương pháp thực nghiệm, phần lớn kiến thức cơ bản của cuốn sách được tổ chức và trình bày theo phương pháp thực nghiệm. Việc coi trọng phương pháp thực nghiệm còn được thể hiện ở hệ thống các bài thí nghiệm thực hành từ đơn giản đến phức tạp, từ cổ điển đến hiện đại, tạo điều kiện cho các em tìm hiểu các thuộc tính của các đối tượng vật lí dưới nhiều góc nhìn khác nhau. Sách giáo khoa *Vật lí 10* trình bày các bài tập đan xen vào các hoạt động tương ứng trong bài.",
    "",
    "Các tác giả mong muốn sách giáo khoa *Vật lí 10* sẽ mang đến cho các em niềm vui và sự đam mê trong học tập môn Vật lí để có kết quả học tập tốt môn học này, không những giúp các em hiểu rõ hơn về thế giới tự nhiên mà còn góp phần giúp các em thấy được năng lực và sở trường của bản thân để bắt đầu định hướng nghề nghiệp, có kế hoạch học tập nhằm đáp ứng các yêu cầu hướng nghiệp của mình.",
    "",
    "CÁC TÁC GIẢ",
    "",
    "3",
    "# MỤC LỤC",
    "",
    "| | Trang | | | Trang |",
    "|---|---|---|---|---|",
    "| Hướng dẫn sử dụng sách | 2 | | **Bài 20.** Một số ví dụ về cách giải các bài toán thuộc phần động lực học | 80 |",
    "| Lời nói đầu | 3 | | **Bài 21.** Moment lực. Cân bằng của vật rắn | 83 |",
    "| Bảng đơn vị đo lường hệ SI | 5 | | **Bài 22.** Thực hành: Tổng hợp lực | 86 |",
    "| **CHƯƠNG I. MỞ ĐẦU** | 6 | | **CHƯƠNG IV. NĂNG LƯỢNG, CÔNG, CÔNG SUẤT** | 90 |",
    "| **Bài 1.** Làm quen với Vật lí | 7 | | **Bài 23.** Năng lượng. Công cơ học | 91 |",
    "| **Bài 2.** Các quy tắc an toàn trong phòng thực hành Vật lí | 12 | | **Bài 24.** Công suất | 96 |",
    "| **Bài 3.** Thực hành tính sai số trong phép đo. Ghi kết quả đo | 17 | | **Bài 25.** Động năng, thế năng | 99 |",
    "| **CHƯƠNG II. ĐỘNG HỌC** | 20 | | **Bài 26.** Cơ năng và định luật bảo toàn cơ năng | 102 |",
    "| **Bài 4.** Độ dịch chuyển và quãng đường đi được | 21 | | **Bài 27.** Hiệu suất | 106 |",
    "| **Bài 5.** Tốc độ và vận tốc | 26 | | **CHƯƠNG V. ĐỘNG LƯỢNG** | 109 |",
    "| **Bài 6.** Thực hành: Đo tốc độ của vật chuyển động | 30 | | **Bài 28.** Động lượng | 110 |",
    "| **Bài 7.** Đồ thị độ dịch chuyển – thời gian | 34 | | **Bài 29.** Định luật bảo toàn động lượng | 113 |",
    "| **Bài 8.** Chuyển động biến đổi. Gia tốc | 37 | | **Bài 30.** Thực hành: Xác định động lượng của vật trước và sau va chạm | 116 |",
