INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B1', 'Bài 1 LÀM QUEN VỚI VẬT LÍ', 7, 2, $JSON$
{
  "content": [
    "# Bài 1 LÀM QUEN VỚI VẬT LÍ",
    "",
    "**Khởi động:** Hình bên là các nhà vật lí tiêu biểu cho mỗi giai đoạn phát triển khoa học và công nghệ của nhân loại. Em đã biết gì về các nhà khoa học này?",
    "[Hình ảnh 3 nhà khoa học: Galilei, Newton, Einstein]",
    "Galilei (Ga-li-lê) (1564 – 1642): Cha đẻ của phương pháp thực nghiệm.",
    "Newton (Niu-tơn) (1642 – 1727): Người tìm ra định luật vạn vật hấp dẫn.",
    "Einstein (Anh-xtanh) (1879 – 1955): Người tìm ra thuyết tương đối và công thức: E = mc$^2$.",
    "",
    "## I. ĐỐI TƯỢNG NGHIÊN CỨU CỦA VẬT LÍ VÀ MỤC TIÊU CỦA MÔN VẬT LÍ",
    "",
    "Thuật ngữ “vật lí” có nguồn gốc từ tiếng Hy Lạp “physiko” có nghĩa là “kiến thức về tự nhiên”. Vật lí là môn \"khoa học tự nhiên\" có đối tượng nghiên cứu tập trung vào các dạng vận động của vật chất (chất, trường), năng lượng.",
    "Các lĩnh vực nghiên cứu của Vật lí rất đa dạng, từ Cơ học, Điện học, Điện từ học, Quang học, Âm học, Nhiệt học, Nhiệt động lực học đến Vật lí nguyên tử và hạt nhân, Vật lí lượng tử, Thuyết tương đối.",
    "Việc học tập môn Vật lí giúp các em hình thành, phát triển năng lực vật lí với các biểu hiện chính sau đây:",
    "– Có được những kiến thức, kĩ năng cơ bản về vật lí.",
    "– Vận dụng được kiến thức, kĩ năng đã học để khám phá, giải quyết các vấn đề có liên quan trong học tập cũng như trong đời sống.",
    "– Nhận biết được năng lực, sở trường của bản thân, định hướng nghề nghiệp $^{(1)}$.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy kể tên các lĩnh vực vật lí mà em đã được học ở cấp Trung học cơ sở.",
    "2. Em thích nhất lĩnh vực nào của Vật lí? Tại sao?",
    "",
    "## II. QUÁ TRÌNH PHÁT TRIỂN CỦA VẬT LÍ",
    "",
    "Dưới đây là sơ đồ trình bày các giai đoạn chính trong quá trình phát triển của Vật lí. Mỗi giai đoạn có một tính chất, đặc điểm riêng.",
    "",
    "Các nhà triết học tìm hiểu thế giới tự nhiên dựa trên quan sát và suy luận chủ quan.",
    "*Từ năm 350 trước Công nguyên đến thế kỉ XVI (tiền Vật lí)*",
    "| 350 TCN: Aristotle (A-ri-xtốt) dựa vào quan sát cho rằng vật nặng rơi nhanh hơn vật nhẹ.",
    "",
    "Các nhà vật lí dùng phương pháp thực nghiệm để tìm hiểu thế giới tự nhiên.",
    "*Từ thế kỉ XVII đến cuối thế kỉ XIX (Vật lí cổ điển)*",
    "| 1600: Galilei làm thí nghiệm tại tháp nghiêng Pisa.",
    "| 1687: Newton công bố các nguyên lí Toán học của Triết học tự nhiên.",
    "| 1785: Joule (Jun) tìm ra các định luật nhiệt động lực học.",
    "| 1831: Faraday (Pha-ra-đây) tìm ra hiện tượng cảm ứng điện từ.",
    "",
    "Các nhà vật lí tập trung vào các mô hình lí thuyết tìm hiểu thế giới vi mô và sử dụng thí nghiệm để kiểm chứng.",
    "*Từ cuối thế kỉ XIX đến nay (Vật lí hiện đại)*",
    "| 1900: Planck (Plăng) xây dựng thuyết lượng tử.",
    "| 1905: Einstein xây dựng thuyết tương đối.",
    "| 1958: Ra đời lí thuyết và thực hành mạch IC.",
    "",
    "$^{(1)}$ *Theo Chương trình GDPT môn Vật lí – Bộ GD và ĐT (2018)*",
    "",
    "7",
    "CHƯƠNG I – MỞ ĐẦU",
    "",
    "## III. VAI TRÒ CỦA VẬT LÍ ĐỐI VỚI KHOA HỌC, KĨ THUẬT VÀ CÔNG NGHỆ",
    "",
    "a) Vật lí có quan hệ với mọi ngành khoa học và thường được coi là cơ sở của khoa học tự nhiên (KHTN). Các khái niệm, định luật, nguyên lí của Vật lí được sử dụng rộng rãi trong mọi lĩnh vực của KHTN, đặc biệt là trong việc giải thích cơ chế của các hiện tượng tự nhiên, từ các hiện tượng xảy ra trong thế giới sinh học, các phản ứng hoá học đến các hiện tượng xảy ra trong vũ trụ,...",
    "Không phải ngẫu nhiên mà càng ngày càng xuất hiện nhiều lĩnh vực liên môn như Vật lí sinh học, Vật lí địa lí, Vật lí thiên văn, Hoá lí, Sinh học lượng tử, Hoá học lượng tử,...",
    "",
    "b) Vật lí là cơ sở của công nghệ. Có thể khẳng định là không có các thành tựu nghiên cứu của Vật lí thì không có công nghệ.",
    "Máy hơi nước do James Watt (Giêm Oát) sáng chế năm 1765 dựa trên những kết quả nghiên cứu về Nhiệt của Vật lí đã tạo nên bước khởi đầu cho cuộc cách mạng công nghiệp lần thứ nhất với đặc trưng cơ bản là thay thế sức lực cơ bắp bằng sức lực máy móc (Hình 1.1).",
    "",
    "[Hình 1.1. Máy hơi nước của James Watt]",
    "",
    "**? Câu hỏi:**",
    "1. Hãy nêu tên một số thiết bị có ứng dụng các kiến thức về nhiệt.",
    "2. Theo em, việc sử dụng máy hơi nước nói riêng và động cơ nhiệt nói chung có những hạn chế nào?",
    "",
    "**? Câu hỏi:**",
    "1. Cơ chế của các phản ứng hoá học được giải thích dựa trên kiến thức thuộc lĩnh vực nào của Vật lí?",
    "2. Kiến thức về từ trường Trái Đất được dùng để giải thích đặc điểm nào của loài chim di trú?",
    "3. Sự tương tác giữa các thiên thể được giải thích dựa vào định luật vật lí nào của Newton?",
    "4. Hãy nêu thêm ví dụ về việc dùng kiến thức vật lí để giải thích hiện tượng tự nhiên mà các em đã học.",
    "",
    "Nhờ việc khám phá ra hiện tượng cảm ứng điện từ của nhà vật lí Faraday mà sau đó các máy phát điện ra đời, mở đầu cho kỉ nguyên sử dụng điện năng của nhân loại và là một trong những cơ sở cho sự ra đời của cuộc cách mạng công nghiệp lần thứ hai vào cuối thế kỉ XIX. Một trong những đặc trưng cơ bản của cuộc cách mạng công nghiệp này là sự xuất hiện các thiết bị dùng điện trong mọi lĩnh vực sản xuất và đời sống con người (Hình 1.2).",
    "",
    "[Hình 1.2. Nhà máy thuỷ điện Hoà Bình]",
    "",
    "**? Câu hỏi:**",
    "Theo em, sử dụng động cơ điện có những ưu điểm vượt trội nào so với sử dụng máy hơi nước?",
    "",
    "Cuộc cách mạng công nghiệp lần thứ ba bắt đầu vào những năm 70 của thế kỉ XX, với đặc trưng là tự động hoá các quá trình sản xuất (xây dựng các dây chuyền sản xuất tự động) cũng là nhờ có những thành tựu nghiên cứu về điện tử, chất bán dẫn và vi mạch,... của Vật lí học (Hình 1.3).",
    "",
    "[Hình 1.3. Dây chuyền sản xuất ô tô]",
    "",
    "8",
    "CHƯƠNG I – MỞ ĐẦU",
    "",
    "**? Câu hỏi:**",
    "Hãy kể tên một số nhà máy tự động hoá quá trình sản xuất ở nước ta.",
    "",
    "Cuộc cách mạng công nghiệp lần thứ tư được coi là bắt đầu vào đầu thế kỉ XXI với tốc độ phát triển và mức độ ảnh hưởng vượt xa các cuộc cách mạng công nghiệp trước đó. Đặc trưng của cuộc cách mạng công nghiệp này là sử dụng trí tuệ nhân tạo, robot, internet toàn cầu, công nghệ vật liệu siêu nhỏ (nano); là sự xuất hiện từ bóng đèn thông minh, điện thoại thông minh đến nhà ở thông minh, nhà máy thông minh. Tất cả đều dựa trên những thành tựu của các lĩnh vực nghiên cứu khác nhau của Vật lí hiện đại (Hình 1.4).",
    "",
    "[Hình 1.4. Robot và máy tính]",
    "",
    "**Hoạt động:**",
    "Hãy sưu tầm tài liệu trên internet và các phương tiện truyền thông khác về thành phố thông minh (thành phố số) để trình bày và thảo luận trên lớp về chủ đề \"Thế nào là thành phố thông minh?\"",
    "",
    "c) Vai trò của Vật lí trong sự phát triển các công nghệ nêu trên cho thấy sự ảnh hưởng to lớn của nó đối với cuộc sống con người. Mọi thiết bị mà con người sử dụng hằng ngày đều ít nhiều gắn với những thành tựu nghiên cứu của Vật lí.",
    "Tuy nhiên, việc ứng dụng các thành tựu của Vật lí vào công nghệ không chỉ mang lại lợi ích cho nhân loại mà còn có thể làm ô nhiễm môi trường sống, huỷ hoại hệ sinh thái,... nếu không được sử dụng đúng phương pháp, đúng mục đích (Hình 1.5, 1.6).",
    "",
    "[Hình 1.5. Khí thải từ nhà máy]",
    "[Hình 1.6. Vụ nổ bom nguyên tử]",
    "",
    "**? Câu hỏi:**",
    "1. Hãy nêu mối liên quan giữa các lĩnh vực của Vật lí đối với một số dụng cụ gia đình mà em thường sử dụng.",
    "2. Hãy nói về ảnh hưởng của Vật lí đối với một số lĩnh vực như: giao thông vận tải; thông tin liên lạc; năng lượng; du hành vũ trụ;... Sưu tầm hình ảnh để minh hoạ.",
    "3. Hãy nêu ví dụ về ô nhiễm môi trường và huỷ hoại hệ sinh thái mà em biết ở địa phương mình.",
    "",
    "## IV. PHƯƠNG PHÁP NGHIÊN CỨU VẬT LÍ",
    "",
    "**1. Phương pháp thực nghiệm**",
    "Phương pháp thực nghiệm là phương pháp quan trọng của Vật lí.",
    "Câu chuyện dưới đây về sự ra đời của phương pháp thực nghiệm sẽ giúp các em hiểu được đặc điểm của phương pháp này. Từ việc quan sát sự rơi của các vật nặng nhẹ khác nhau mà Aristotle, một nhà khoa học Hy Lạp sống vào những năm 300 trước Công nguyên cho rằng: “Vật nặng rơi nhanh hơn vật nhẹ, vật càng nặng rơi càng nhanh” (Hình 1.7a).",
    "",
    "9",
    "Quan điểm này thống trị trong Vật lí học ngót 2000 năm cho đến khi Galilei nghi ngờ nó. Ông suy luận rằng, nếu như vật nặng rơi nhanh hơn vật nhẹ thì khi buộc vật nặng vào vật nhẹ rồi cho chúng rơi, vật nhẹ sẽ kéo vật nặng lại, làm nó rơi chậm đi, còn vật nặng sẽ kéo vật nhẹ theo làm nó rơi nhanh lên. Như vậy, cả hai vật cùng rơi sẽ phải rơi nhanh hơn vật nhẹ và rơi chậm hơn vật nặng. Điều này thật vô lí. Ông dự đoán các vật nặng nhẹ rơi nhanh như nhau. Để kiểm tra dự đoán này, ông đã làm thí nghiệm thả những quả cầu có trọng lượng khác nhau rơi từ tháp nghiêng Pisa (Hình 1.7b). Kết quả là chúng đều rơi chạm đất cùng một lúc, đúng như dự đoán của ông.",
    "Nhờ thí nghiệm này, Galilei đã bác bỏ được quan điểm của Aristotle, đồng thời mở ra kỉ nguyên của phương pháp thực nghiệm trong Vật lí.",
    "Mô hình về phương pháp thực nghiệm gồm các bước như trong Hình 1.8.",
    "",
    "[Hình 1.7. Aristotle (a) và Galilei (b)]",
    "[Hình 1.8. Sơ đồ các bước của phương pháp thực nghiệm]",
    "Bước 1: Xác định vấn đề cần nghiên cứu",
    "Bước 2: Quan sát, thu thập thông tin",
    "Bước 3: Đưa ra dự đoán",
    "Bước 4: Tiến hành thí nghiệm kiểm tra dự đoán",
    "- Nếu kết quả thí nghiệm không phù hợp với dự đoán: Quay lại Bước 3 hoặc Bước 2.",
    "- Nếu kết quả thí nghiệm phù hợp với dự đoán: Kết luận.",
    "",
    "**? Câu hỏi:**",
    "Hãy phân tích sự tiến triển quá trình nghiên cứu của Galilei theo sơ đồ trên.",
    "",
    "**2. Phương pháp mô hình**",
    "Việc dùng các mô hình để nghiên cứu, giải thích các tính chất của vật thật, tìm ra cơ chế hoạt động của nó... được gọi là phương pháp mô hình.",
    "",
    "Các loại mô hình thường dùng ở trường phổ thông:",
    "- Mô hình vật chất: Đó là các vật thu nhỏ hoặc phóng to của vật thật, có một số đặc điểm giống vật thật. Quả địa cầu là mô hình thu nhỏ của Trái Đất (Hình 1.9a), hệ Mặt Trời là mô hình hệ hành tinh (Hình 1.9b)...",
    "- Mô hình lí thuyết: Khi nghiên cứu sự rơi của các vật, người ta phát hiện ra sự rơi nhanh hay chậm của các vật phụ thuộc vào sức cản của không khí. Nếu coi sức cản không khí là không đáng kể thì các vật rơi tự do là rơi như nhau. Coi sức cản không khí không đáng kể là mô hình lí thuyết. Ở chương trình Trung học cơ sở, các em đã dùng mô hình tia sáng (Hình 1.9c) để biểu diễn đường truyền của ánh sáng.",
    "",
    "10",
    "CHƯƠNG I – MỞ ĐẦU",
    "",
    "Aristotle dùng suy luận để bảo vệ ý kiến của mình. Ông đã lập luận như sau: “Bốn hòn đá buộc lại với nhau, rơi nhanh gấp 4 lần một hòn đá, cũng giống như xe kéo bằng bốn con ngựa chạy nhanh gấp 4 lần xe kéo bằng một con ngựa” (Hình 1.7c).",
    "Vào thời đại của Aristotle, khoa học chưa phát triển, Aristotle lại là một nhà bác học rất có uy tín, nên chẳng ai nghi ngờ ý kiến của ông, chẳng ai nghĩ đến việc kiểm tra xem có thật bốn hòn đá buộc lại với nhau rơi nhanh gấp 4 lần một hòn đá hay không.",
    "Phải mãi gần 20 thế kỉ sau, khi khoa học đã bắt đầu phát triển, mới có người nghĩ đến việc kiểm tra xem ý kiến của Aristotle có đúng hay không. Đó là Galilei, ở thành phố Pisa nước Italia. Galilei đã làm như sau:",
    "1. Xác định vấn đề cần tìm hiểu: Có đúng vật nặng rơi nhanh hơn vật nhẹ không?",
    "2. Bằng những quan sát hằng ngày, ông đã thấy khi trời mưa những giọt nước mưa dù to hay nhỏ đều rơi xuống như nhau, cũng giống như khi có tuyết rơi thì những hạt tuyết to hay nhỏ cũng rơi xuống như nhau.",
    "3. Từ những quan sát của mình, Galilei dự đoán: Sự rơi nhanh hay chậm không phụ thuộc vào vật nặng hay nhẹ (Hình 1.7b).",
    "4. Khác với Aristotle chỉ dừng lại ở suy luận, Galilei nghĩ ra cách làm thí nghiệm để kiểm tra dự đoán của mình. Ông cho rằng nếu dùng thí nghiệm chứng minh được hai vật nặng, nhẹ rất khác nhau đều rơi nhanh như nhau thì sẽ bác bỏ được ý kiến của Aristotle.",
    "Ông cùng các học trò của mình mang lên tháp nghiêng Pisa hai quả cầu bằng kim loại, quả to nặng gấp khoảng 10 lần quả nhỏ và thả hai quả cầu xuống cùng một lúc. Trước sự chứng kiến của hàng trăm người dân thành phố Pisa, cả hai quả cầu đều rơi nhanh như nhau, cùng chạm đất một lúc (Hình 1.7d).",
    "5. Thí nghiệm đã chứng tỏ ý kiến của Galilei là đúng: Sự rơi nhanh hay chậm không phụ thuộc vào vật nặng hay nhẹ.",
    "Phương pháp mà Galilei dùng ở trên sau này được gọi là phương pháp thực nghiệm và Galilei được coi là \"cha đẻ\" của phương pháp này. Sơ đồ của phương pháp thực nghiệm được mô tả trên Hình 1.8.",
    "Nếu thí nghiệm chứng tỏ dự đoán là sai thì người ta phải đưa ra dự đoán mới và làm thí nghiệm kiểm tra dự đoán này, hoặc xác định lại vấn đề cần nghiên cứu.",
    "",
    "[Bảng so sánh Quan niệm về sự rơi của các vật nặng nhẹ khác nhau: Aristotle (Phương pháp nghiên cứu: Quan sát và suy luận) vs Galilei (Phương pháp nghiên cứu: Thực nghiệm). Kèm theo hình ảnh minh họa 1.7c, 1.7d]",
    "*Hình 1.7. So sánh quan niệm, phương pháp nghiên cứu của Aristotle và Galilei*",
    "",
    "[Sơ đồ các bước của phương pháp thực nghiệm: 1. Xác định vấn đề cần nghiên cứu -> 2. Quan sát, thu thập thông tin -> 3. Đưa ra dự đoán -> 4. Thí nghiệm kiểm tra dự đoán -> 5. Kết luận]",
    "*Hình 1.8. Sơ đồ của phương pháp thực nghiệm*",
    "",
    "**? Câu hỏi:**",
    "Nêu một ví dụ về sử dụng phương pháp thực nghiệm mà em đã được học trong môn KHTN.",
    "",
    "10",
    "CHƯƠNG I – MỞ ĐẦU",
    "",
    "**2. Phương pháp mô hình**",
    "Đây là phương pháp dùng các mô hình để nghiên cứu, giải thích các tính chất của vật thật, tìm ra cơ chế hoạt động của nó,... Các loại mô hình sau đây là các mô hình thường dùng ở trường phổ thông:",
    "– Mô hình vật chất: Đó là các vật thu nhỏ hoặc phóng to của vật thật, có một số đặc điểm giống vật thật. Quả địa cầu trong phòng thí nghiệm là ví dụ về mô hình vật chất thu nhỏ của Trái Đất, hệ Mặt Trời có thể coi là mô hình vật chất phóng to của mẫu nguyên tử của Rutherford.",
    "– Mô hình lí thuyết: Khi nghiên cứu chuyển động của một ô tô đang chạy trên đường dài, người ta coi ô tô là một \"chất điểm\", khi nghiên cứu về ánh sáng người ta dùng mô hình tia sáng để biểu diễn đường truyền của ánh sáng.",
    "Chất điểm, tia sáng nêu trên là các ví dụ về mô hình lí thuyết.",
    "– Mô hình toán học: Đó là các công thức, phương trình, đồ thị, kí hiệu,... của Toán học dùng để mô tả các đặc điểm của các đối tượng nghiên cứu. Vectơ dùng để mô tả một đại lượng có hướng, ví dụ lực, độ dịch chuyển; phương trình $s = v.t$ là mô hình toán học của chuyển động thẳng đều,...",
    "Tuỳ theo từng loại mô hình cụ thể mà có thể có các quy trình xây dựng và sử dụng mô hình khác nhau. Tuy nhiên các bước sau đây được coi là các bước cần thiết cho việc xây dựng mọi loại mô hình:",
    "1. Xác định đối tượng cần được mô hình hoá.",
    "2. Đưa ra các mô hình khác nhau để thử nghiệm.",
    "3. Kiểm tra sự phù hợp của các mô hình với các kết quả cho bởi thí nghiệm, thực tế, lí thuyết.",
    "4. Kết luận về mô hình.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy kể tên một số mô hình vật chất mà em thấy trong phòng thí nghiệm.",
    "2. Hãy nêu tên một mô hình lí thuyết mà em đã học.",
    "3. Các mô hình toán học vẽ ở Hình 1.9 dùng để mô tả loại chuyển động nào?",
    "[Hình 1.9 a) Đồ thị s-t; b) Đồ thị v-t]",
    "",
    "[Sơ đồ của phương pháp mô hình: 1. Xác định đối tượng cần mô hình hoá -> 2. Xây dựng mô hình (giả thuyết) -> 3. Kiểm tra sự phù hợp của mô hình -> 4. Kết luận / Điều chỉnh mô hình nếu cần]",
    "*Hình 1.10. Sơ đồ của phương pháp mô hình*",
    "",
    "**EM ĐÃ HỌC**",
    "- Đối tượng nghiên cứu chủ yếu của Vật lí là các dạng của vật chất, năng lượng.",
    "- Phương pháp nghiên cứu thường sử dụng của Vật lí là phương pháp thực nghiệm và phương pháp mô hình.",
    "- Vật lí được coi là cơ sở của KHTN và công nghệ.",
    "",
    "**EM CÓ THỂ**",
    "Dự đoán về sự phụ thuộc tốc độ bay hơi của nước vào nhiệt độ nước và gió thổi trên mặt nước, rồi lập phương án thí nghiệm để kiểm tra dự đoán.",
    "",
    "11"
  ]
}
