INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B2', 'Bài 2 CÁC QUY TẮC AN TOÀN TRONG PHÒNG THỰC HÀNH VẬT LÍ', 13, 3, $JSON$
{
  "content": [
    "# Bài 2 CÁC QUY TẮC AN TOÀN TRONG PHÒNG THỰC HÀNH VẬT LÍ",
    "",
    "**Khởi động:** Khi làm thí nghiệm cần đảm bảo người làm thí nghiệm không gặp nguy hiểm, đồ dùng, thiết bị không bị hư hỏng, cháy nổ. Làm thế nào để đảm bảo an toàn trong khi tiến hành thí nghiệm?",
    "",
    "## I. AN TOÀN KHI SỬ DỤNG THIẾT BỊ THÍ NGHIỆM",
    "**1. Sử dụng các thiết bị điện**",
    "Trong số các thí nghiệm vật lí phổ thông thì các thiết bị sử dụng điện có nguy cơ mất an toàn cao nhất. Cần quan sát kĩ các kí hiệu và nhãn thông số trên thiết bị để sử dụng đúng chức năng, đúng yêu cầu kĩ thuật.",
    "",
    "[Hình 2.1a: Máy biến áp (máy biến thế) với các cổng AC, DC]",
    "[Hình 2.1b: Bộ chuyển đổi điện áp với các thông số input, output]",
    "*Hình 2.1. Hai loại thiết bị cung cấp nguồn điện*",
    "",
    "**Hoạt động:** Hãy quan sát hai thiết bị chuyển đổi điện áp, tham khảo kí hiệu ở Bảng 2.1 và thảo luận để trả lời các câu hỏi sau:",
