    "**Hoạt động:** Quan sát thiết bị thí nghiệm quang hình (Hình 2.3) và cho biết: đặc điểm của các dụng cụ thí nghiệm khi sử dụng và bảo quản thiết bị cần chú ý đến điều gì?",
