INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B3', 'Bài 3 THỰC HÀNH TÍNH SAI SỐ TRONG PHÉP ĐO. GHI KẾT QUẢ ĐO', 18, 4, $JSON$
{
  "content": [
    "# Bài 3 THỰC HÀNH TÍNH SAI SỐ TRONG PHÉP ĐO. GHI KẾT QUẢ ĐO",
    "",
    "**Khởi động:** Không một phép đo nào có thể cho ta giá trị đúng của đại lượng cần đo, mọi phép đo đều có sai số. Làm thế nào để xác định được các sai số này? Nguyên nhân gây ra các sai số là gì và cách khắc phục như thế nào?",
    "",
    "## I. PHÉP ĐO TRỰC TIẾP VÀ PHÉP ĐO GIÁN TIẾP",
    "– Đo trực tiếp một đại lượng bằng dụng cụ đo, kết quả được đọc trực tiếp trên dụng cụ đo được gọi là *phép đo trực tiếp*.",
    "– Đo một đại lượng không trực tiếp mà thông qua công thức liên hệ với các đại lượng có thể đo trực tiếp gọi là *phép đo gián tiếp*.",
    "",
    "**? Câu hỏi:**",
    "Em hãy lập phương án đo tốc độ chuyển động của chiếc xe ô tô đồ chơi chỉ dùng thước, đồng hồ bấm giây và trả lời các câu hỏi sau:",
    "a) Để đo tốc độ chuyển động của chiếc xe cần đo những đại lượng nào?",
    "b) Xác định tốc độ chuyển động của xe theo công thức nào?",
    "c) Phép đo nào là phép đo trực tiếp? Tại sao?",
    "d) Phép đo nào là phép đo gián tiếp? Tại sao?",
    "",
    "## II. SAI SỐ PHÉP ĐO",
    "**1. Phân loại sai số**",
    "**a) Sai số hệ thống**",
    "Khi sử dụng dụng cụ đo để đo các đại lượng vật lí luôn có sự sai lệch do đặc điểm và cấu tạo của dụng cụ gây ra.",
    "Sự sai lệch này gọi là sai số dụng cụ hoặc sai số hệ thống.",
    "Sai số hệ thống có nguyên nhân khách quan (do dụng cụ), nguyên nhân chủ quan do người đo (cần loại bỏ).",
    "",
    "**b) Sai số ngẫu nhiên**",
    "Khi lặp lại các phép đo, ta nhận được các giá trị khác nhau, sự sai lệch này không có nguyên nhân rõ ràng nên gọi là sai số ngẫu nhiên, có thể do thao tác đo không chuẩn, điều kiện làm thí nghiệm không ổn định hoặc hạn chế về giác quan,...",
    "Để khắc phục người ta thường tiến hành thí nghiệm nhiều lần và tính sai số.",
    "",
    "**! Chú ý:** Sai số gây bởi dụng cụ sử dụng đo thường lấy bằng một nửa độ chia nhỏ nhất trên dụng cụ (ví dụ thước đo chiều dài có độ chia nhỏ nhất là 1 mm thì sai số dụng cụ là 0,5 mm), hoặc được ghi trực tiếp trên dụng cụ do nhà sản xuất xác định.",
    "",
    "17",
    "CHƯƠNG I – MỞ ĐẦU",
    "",
    "**2. Cách xác định sai số phép đo**",
    "- *Sai số ngẫu nhiên tuyệt đối* của từng lần đo là trị tuyệt đối của hiệu số giữa giá trị trung bình các lần đo và giá trị của mỗi lần đo của phép đo trực tiếp.",
    "$\\Delta A_1 = |\\overline{A} - A_1|; \\Delta A_2 = |\\overline{A} - A_2|; ...; \\Delta A_n = |\\overline{A} - A_n|$ (3.1)",
    "Trong đó: $\\overline{A} = \\frac{A_1 + A_2 + ... + A_n}{n}$",
    "Sai số ngẫu nhiên tuyệt đối trung bình của n lần đo được tính theo công thức:",
    "$\\overline{\\Delta A} = \\frac{\\Delta A_1 + \\Delta A_2 + ... + \\Delta A_n}{n}$ (3.2)",
    "Sai số tuyệt đối của phép đo là tổng sai số ngẫu nhiên và sai số dụng cụ:",
    "$\\Delta A = \\overline{\\Delta A} + \\Delta A_{dc}$",
    "- *Sai số tỉ đối* của phép đo là tỉ lệ phần trăm giữa sai số tuyệt đối và giá trị trung bình của đại lượng đo, cho biết mức độ chính xác của phép đo.",
    "$\\delta A = \\frac{\\Delta A}{\\overline{A}} . 100\\%$ (3.3)",
    "",
    "**3. Cách xác định sai số phép đo gián tiếp**",
    "Để xác định sai số của phép đo gián tiếp, vận dụng quy tắc sau:",
    "- Sai số tuyệt đối của một tổng hay hiệu bằng tổng các sai số tuyệt đối của các số hạng.",
    "A = B + C",
    "$\\Delta A = \\Delta B + \\Delta C$",
    "- Sai số tỉ đối của một tích hay thương thì bằng tổng các sai số tỉ đối của các thừa số.",
    "A = B.C",
    "$\\delta A = \\delta B + \\delta C$",
    "- Từ sai số tỉ đối, có thể sử dụng công thức (3.3) để tính được sai số tuyệt đối.",
    "*Ví dụ 1:* Đo quãng đường s từ A đến C bằng tổng quãng đường $s_1$ từ A đến B và $s_2$ từ B đến C.",
    "Sai số tuyệt đối: $\\Delta s = \\Delta s_1 + \\Delta s_2$",
    "*Ví dụ 2:* Đo tốc độ theo công thức $v = \\frac{s}{t}$, sai số phép đo là:",
    "$\\delta v = \\frac{\\Delta s}{\\overline{s}} . 100\\% + \\frac{\\Delta t}{\\overline{t}} . 100\\%$",
    "$\\Delta v = \\delta v . \\overline{v}$",
    "",
    "**4. Cách ghi kết quả đo**",
    "- Kết quả đo đại lượng A được ghi dưới dạng một khoảng giá trị:",
    "$(\\overline{A} - \\Delta A) \\le A \\le (\\overline{A} + \\Delta A)$ hoặc $A = \\overline{A} \\pm \\Delta A$",
    "Trong đó:",
    "+ $\\Delta A$ là sai số tuyệt đối thường viết đến số chữ số có nghĩa tới đơn vị của độ chia nhỏ nhất (ĐCNN) trên dụng cụ đo.",
    "+ Giá trị trung bình $\\overline{A}$ được viết đến bậc thập phân tương ứng với $\\Delta A$.",
    "- Quy tắc làm tròn số:",
    "+ Nếu chữ số ở hàng bỏ đi nhỏ hơn 5 thì chữ số bên trái vẫn giữ nguyên.",
    "+ Nếu chữ số hàng bỏ đi lớn hơn hoặc bằng 5 thì chữ số bên trái tăng thêm một đơn vị.",
    "",
    "$^{(1), (2)}$ Kí hiệu $\\Delta, \\delta$ đều đọc là \"đen - ta\".",
    "",
    "**EM CÓ BIẾT?**",
    "Cách xác định sai số tỉ đối của một tích hay một thương khi các đại lượng có luỹ thừa",
    "Ví dụ: Nếu $A = B.\\sqrt{C}$ thì $\\delta A = \\delta B + \\frac{1}{2}.\\delta C$",
    "",
    "18",
    "CHƯƠNG I – MỞ ĐẦU",
    "",
    "**Hoạt động:** Dùng một thước có ĐCNN là 1 mm và một đồng hồ đo thời gian có ĐCNN 0,01 s để đo 5 lần thời gian chuyển động của chiếc xe đồ chơi chạy bằng pin từ điểm A ($v_A = 0$) đến điểm B (Hình 3.1). Ghi các giá trị vào Bảng 3.1 và trả lời các câu hỏi.",
    "",
    "**Bảng 3.1**",
    "| n | s (m) | $\\Delta s (m)$ | t (s) | $\\Delta t (s)$ |",
    "|---|---|---|---|---|",
    "| 1 | | | | |",
    "| 2 | | | | |",
    "| 3 | | | | |",
    "| 4 | | | | |",
    "| 5 | | | | |",
    "| Trung bình | $\\overline{s} = ...$ | $\\overline{\\Delta s} = ...$ | $\\overline{t} = ...$ | $\\overline{\\Delta t} = ...$ |",
    "",
    "[Hình 3.1. Thí nghiệm đo tốc độ. Hình ảnh có một chiếc xe đồ chơi vàng, điểm A và B, và một đồng hồ bấm giây]",
    "",
    "a) Nguyên nhân nào gây ra sự sai khác giữa các lần đo?",
    "b) Tính sai số tuyệt đối của phép đo s, t và điền vào Bảng 3.1.",
    "c) Viết kết quả đo:",
    "$s = .......... ; t = ..........$",
    "d) Tính sai số tỉ đối:",
    "$\\delta t = \\frac{\\Delta t}{\\overline{t}} . 100\\% = ...; \\delta s = \\frac{\\Delta s}{\\overline{s}} . 100\\% = ...$",
    "$\\delta v = ...; \\Delta v = ...$",
    "",
    "**EM ĐÃ HỌC**",
    "- Có hai loại phép đo là phép đo trực tiếp và phép đo gián tiếp.",
    "- Hai loại sai số gồm sai số dụng cụ và sai số ngẫu nhiên.",
    "- Cách ghi kết quả đo: $A = \\overline{A} \\pm \\Delta A$ với $\\Delta A = \\overline{\\Delta A} + \\Delta A_{dc}$.",
    "",
    "**EM CÓ THỂ**",
    "1. Giải thích được tại sao để đo một đại lượng chính xác người ta cần lặp lại phép đo nhiều lần và tính sai số.",
    "2. Tính được sai số tuyệt đối, sai số tỉ đối của phép đo trực tiếp và phép đo gián tiếp.",
    "",
    "**EM CÓ BIẾT?**",
    "Sai số và kết quả của phép đo có thể biểu diễn bằng đồ thị. Phương pháp đồ thị cho phép tìm quy luật sự phụ thuộc của đại lượng y vào đại lượng x.",
    "Khi sử dụng đồ thị cần chú ý cách biểu diễn các giá trị có sai số:",
    "Mỗi giá trị có được từ thực nghiệm đều có sai số: $\\pm \\Delta x$ và $\\pm \\Delta y$. Do đó trên đồ thị, mỗi giá trị sẽ được biểu diễn bằng một điểm nằm trong ô chữ nhật có cạnh là $2\\Delta x$ và $2\\Delta y$.",
    "",
    "[Hình 3.2. Biểu diễn sai số bằng đồ thị]",
    "",
    "19"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B4', 'Bài 4 ĐỘ DỊCH CHUYỂN VÀ QUÃNG ĐƯỜNG ĐI ĐƯỢC', 22, 1, $JSON$
{
  "content": [
    "# Bài 4 ĐỘ DỊCH CHUYỂN VÀ QUÃNG ĐƯỜNG ĐI ĐƯỢC",
    "",
    "**Khởi động:**",
    "Một ô tô đi tới điểm O của một ngã tư đường có 4 hướng: Đông, Tây, Nam, Bắc với tốc độ không đổi 36 km/h. Nếu ô tô đi tiếp thì sau 10 s:",
    "a) Quãng đường đi tiếp của ô tô là bao nhiêu mét?",
    "b) Vị trí của ô tô ở điểm nào trên hình vẽ?",
    "",
    "[Hình ảnh minh họa ngã tư với la bàn chỉ hướng Bắc, Nam, Đông, Tây. Có các điểm A, B, C, D, E, F trên đường đi lên (Bắc) và đi xuống (Nam); H, G trên đường sang Trái (Tây) và K, L, M trên đường sang Phải (Đông). Khoảng cách 1 đoạn nhỏ là 50m.]",
    "",
    "## I. VỊ TRÍ CỦA VẬT CHUYỂN ĐỘNG TẠI CÁC THỜI ĐIỂM",
    "Khi vật chuyển động thì vị trí của vật so với vật được chọn làm mốc thay đổi theo thời gian. Bài toán cơ bản của động học là xác định vị trí của vật tại các thời điểm khác nhau.",
    "- Để xác định vị trí của vật, người ta dùng hệ toạ độ vuông góc có gốc là vị trí của vật mốc, trục hoành Ox và trục tung Oy. Các giá trị trên các trục toạ độ được xác định theo một tỉ lệ xác định.",
    "Ví dụ: Nếu tỉ lệ là $\\frac{1}{1000}$ thì vị trí của điểm A trong Hình 4.1 được xác định trên hệ toạ độ là A (x = 10 m; y = 20 m) và của điểm B là B (x = - 10 m; y = 20 m).",
    "",
    "[Hình 4.1. Hệ toạ độ: Trục Ox nằm ngang, Oy thẳng đứng, gốc O. Điểm A(1, 2) và điểm B(-1, 2) trên đồ thị với chú thích \"Tỉ xích 1 cm ứng với 10 m\"]",
    "",
    "**EM CÓ BIẾT?**",
    "1. Động học là phần vật lí nghiên cứu chuyển động của vật mà không đề cập đến tác dụng của lực lên chuyển động.",
    "2. Khi kích thước của vật rất nhỏ so với độ dài của quãng đường đi được thì vật được coi là chất điểm. Trong chương này chúng ta chỉ tìm hiểu chuyển động của chất điểm.",
    "",
    "21",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "Trong thực tế, người ta thường chọn hệ toạ độ trùng với hệ toạ độ địa lí, có gốc là vị trí của vật mốc, trục hoành là đường nối hai hướng địa lí Tây – Đông, trục tung là đường nối hai hướng địa lí Bắc – Nam (Hình 4.2).",
    "Ví dụ: Nếu OA = 2 cm và tỉ lệ là $\\frac{1}{1000}$ thì vị trí của điểm A cách điểm gốc 20 m theo hướng 45° Đông – Bắc: A (d = 20 m; 45° Đông – Bắc).",
    "",
    "[Hình 4.2. Hệ toạ độ địa lí. Điểm O, trục Tây - Đông, trục Bắc - Nam. Điểm A có góc 45 độ so với trục Đông.]",
    "",
    "**? Câu hỏi:**",
    "Hãy dùng bản đồ Việt Nam và hệ toạ độ địa lí, xác định vị trí của thành phố Hải Phòng so với vị trí của Thủ đô Hà Nội.",
    "",
    "- Để xác định thời điểm, người ta phải chọn một mốc thời gian, đo khoảng thời gian từ thời điểm được chọn làm mốc đến thời điểm cần xác định.",
    "Ví dụ: Nếu chọn mốc thời gian là $t_0$ = 8 h và thời gian chuyển động là $\\Delta t$ = 2 h, thì thời điểm khi kết thúc chuyển động là $t_n = t_0 + \\Delta t$ = 10 h.",
    "Hệ toạ độ kết hợp với mốc thời gian và đồng hồ đo thời gian được gọi là *hệ quy chiếu*.",
    "",
    "**! Chú ý:** Khi vật chuyển động trên đường thẳng thì chỉ cần dùng hệ toạ độ có điểm gốc O (vị trí của vật mốc) và trục Ox trùng với quỹ đạo chuyển động của vật.",
    "",
    "**? Câu hỏi:**",
    "Xác định vị trí của vật A trên trục Ox vẽ ở Hình 4.3 tại thời điểm 11 h. Biết vật chuyển động thẳng, mỗi giờ đi được 40 km.",
    "[Hình 4.3. Xác định vị trí của vật theo hệ quy chiếu. Trục Ox, $t_0$ = 8 h tại O. Đoạn 20 km]",
    "",
    "## II. ĐỘ DỊCH CHUYỂN",
    "Trong bài toán ở phần mở bài, biết quãng đường đi được có thể xác định được khoảng cách giữa điểm đầu và điểm cuối của chuyển động, nhưng chưa đủ để xác định vị trí của vật.",
    "Muốn xác định được vị trí của vật phải biết thêm hướng của chuyển động. Ví dụ, nếu biết ô tô chuyển động theo hướng Bắc thì dễ dàng xác định được vị trí của ô tô là điểm B trên bản đồ.",
    "Đại lượng vừa cho biết độ dài vừa cho biết hướng của sự thay đổi vị trí của vật gọi là *độ dịch chuyển*.",
    "Độ dịch chuyển của ô tô trong bài toán trên là:",
    "$d_{OB}$ = 100 m (Bắc)",
    "Một đại lượng vừa cho biết độ lớn, vừa cho biết hướng như độ dịch chuyển gọi là *đại lượng vectơ*.",
    "Độ dịch chuyển được biểu diễn bằng một mũi tên nối vị trí đầu và vị trí cuối của chuyển động, có độ dài tỉ lệ với độ lớn của độ dịch chuyển. Kí hiệu là $\\vec{d}$.",
    "",
    "22",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "Hình 4.4 vẽ vectơ độ dịch chuyển của ô tô trong bài toán nêu ở đầu bài.",
    "",
    "**? Câu hỏi:**",
    "Hãy xác định các độ dịch chuyển mô tả ở Hình 4.5 trong toạ độ địa lí.",
    "",
    "[Hình 4.4. Vectơ độ dịch chuyển OB. Tỉ xích 1 cm ứng với 50 m]",
    "[Hình 4.5. Các vectơ độ dịch chuyển $d_1, d_2, d_3$ trên hệ trục toạ độ Đông Tây Nam Bắc. Tỉ xích 1 cm ứng với 100 m]",
    "",
    "## III. PHÂN BIỆT ĐỘ DỊCH CHUYỂN VÀ QUÃNG ĐƯỜNG ĐI ĐƯỢC",
    "Ví dụ dưới đây giúp chúng ta phân biệt độ dịch chuyển và quãng đường đi được.",
    "Trong Hình 4.6 người đi xe máy (1), người đi bộ (2), người đi ô tô (3) đều khởi hành từ siêu thị A để đi đến bưu điện B.",
    "",
    "[Hình 4.6. Sơ đồ mô tả quãng đường đi được của người đi xe máy, người đi bộ và người đi ô tô. Điểm A (Siêu thị) và điểm B (Bưu điện). 3 đường vẽ khác nhau. Tỉ xích 1 cm ứng với 100 m]",
    "",
    "**Hoạt động:**",
    "1. Hãy so sánh độ lớn của độ dịch chuyển và quãng đường đi được của ba chuyển động ở Hình 4.6.",
    "2. Theo em, khi nào độ lớn của độ dịch chuyển và quãng đường đi được của một chuyển động bằng nhau?",
    "",
    "23",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**? Câu hỏi:**",
    "Bạn A đi xe đạp từ nhà qua trạm xăng, tới siêu thị mua đồ rồi quay về nhà cất đồ, sau đó đi xe đến trường (Hình 4.7).",
    "[Hình 4.7. Trục tọa độ Ox với gốc tại N (Nhà), X (Trạm xăng) ở 400m, S (Siêu thị) ở 800m, T (Trường) ở 1200m]",
    "1. Chọn hệ toạ độ có gốc là vị trí nhà bạn A, trục Ox trùng với đường đi từ nhà bạn A tới trường.",
    "a) Tính quãng đường đi được và độ dịch chuyển của bạn A khi đi từ trạm xăng tới siêu thị.",
    "b) Tính quãng đường đi được và độ dịch chuyển của bạn A trong cả chuyến đi trên.",
    "2. Vẽ Bảng 4.1 vào vở và ghi kết quả tính được ở câu 1 vào các ô thích hợp.",
    "Bảng 4.1",
    "| Chuyển động | Quãng đường đi được s (m) | Độ dịch chuyển d (m) |",
    "|---|---|---|",
    "| Từ trạm xăng đến siêu thị | $s_{XS}$ = ...? | $d_{XS}$ = ...? |",
    "| Cả chuyến đi | $s$ = ...? | $d$ = ...? |",
    "3. Hãy dựa vào bảng kết quả trên để kiểm tra dự đoán của em trong câu hỏi 2 cuối trang 23 là đúng hay sai.",
    "",
    "## IV. TỔNG HỢP ĐỘ DỊCH CHUYỂN",
    "Có thể dùng phép cộng vectơ để tổng hợp độ dịch chuyển của vật.",
    "*Bài tập ví dụ:* Hai người đi xe đạp từ A đến C, người thứ nhất đi theo đường từ A đến B, rồi từ B đến C; người thứ hai đi thẳng từ A đến C (Hình 4.8). Cả hai đều về đích cùng một lúc.",
    "Hãy tính quãng đường đi được và độ dịch chuyển của người thứ nhất và người thứ hai. So sánh và nhận xét kết quả.",
    "",
    "*Giải*",
    "Quãng đường đi được của người thứ nhất:",
    "$s_1 = AB + BC = 4 + 4 = 8$ km",
    "Vì ABC là tam giác vuông nên độ lớn của độ dịch chuyển $\\vec{AC}$ của người thứ nhất được tính bằng công thức:",
    "$d_1 = \\sqrt{AB^2 + BC^2} = \\sqrt{4^2 + 4^2} \\approx 5,7$ km",
    "",
    "[Hình 4.8. Tam giác vuông ABC vuông tại B. AB = 4 km, BC = 4 km. Người thứ nhất đi A->B->C, người thứ hai đi thẳng A->C]",
    "",
    "24",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "Vì ABC là tam giác vuông cân nên $\\widehat{CAB} = 45^\\circ$. Hướng của độ dịch chuyển là hướng $45^\\circ$ Đông – Bắc. Độ dịch chuyển của người thứ nhất là: $d_1 \\approx 5,7$ km (hướng $45^\\circ$ Đông – Bắc).",
    "Quãng đường đi được của người thứ hai là:",
    "$s_2 = AC \\approx 5,7$ km",
    "Độ dịch chuyển của người thứ hai là:",
    "$d_2 \\approx 5,7$ km, hướng $45^\\circ$ Đông – Bắc",
    "",
    "**Bảng 4.2**",
    "| | Người thứ nhất | Người thứ hai |",
    "|---|---|---|",
    "| Quãng đường đi được | $s_1$ = 8 km | $s_2 \\approx 5,7$ km |",
    "| Độ dịch chuyển | $d_1 \\approx 5,7$ km | $d_2 \\approx 5,7$ km |",
    "",
    "Dựa vào kết quả ở Bảng 4.2, ta thấy:",
    "- Vì sự dịch chuyển vị trí của người thứ nhất và người thứ hai là như nhau đều từ A đến C, nên hai người có cùng độ dịch chuyển.",
    "- Tuy về đích cùng một lúc nhưng người thứ nhất đi nhanh hơn vì phải đi quãng đường dài hơn. Tuy nhiên nếu chỉ chú ý đến sự thay đổi vị trí thì phải coi cả hai đều thay đổi vị trí nhanh như nhau.",
    "",
    "**? Câu hỏi:**",
    "1. Một người lái ô tô đi thẳng 6 km theo hướng Tây, sau đó rẽ trái đi thẳng theo hướng Nam 4 km rồi quay sang hướng Đông đi 3 km. Xác định quãng đường đi được và độ dịch chuyển của ô tô.",
    "2. Một người bơi ngang từ bờ bên này sang bờ bên kia của một dòng sông rộng 50 m có dòng chảy theo hướng từ Bắc xuống Nam. Do nước sông chảy mạnh nên khi sang đến bờ bên kia thì người đó đã trôi xuôi theo dòng nước 50 m. Xác định độ dịch chuyển của người đó.",
    "",
    "**EM ĐÃ HỌC**",
    "- Độ dịch chuyển là một đại lượng vectơ, cho biết độ dài và hướng của sự thay đổi vị trí của vật.",
    "- Khi vật chuyển động thẳng, không đổi chiều thì độ lớn của độ dịch chuyển và quãng đường đi được bằng nhau. Khi vật chuyển động thẳng, có đổi chiều thì độ lớn của độ dịch chuyển và quãng đường đi được không bằng nhau.",
    "- Tổng hợp các độ dịch chuyển bằng cách tổng hợp vectơ.",
    "",
    "**EM CÓ THỂ**",
    "Xác định được vị trí của một địa điểm trên bản đồ.",
    "",
    "25"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B5', 'Bài 5 TỐC ĐỘ VÀ VẬN TỐC', 27, 2, $JSON$
{
  "content": [
    "# Bài 5 TỐC ĐỘ VÀ VẬN TỐC",
    "",
    "**Khởi động:**",
    "Trong đời sống, tốc độ và vận tốc là hai đại lượng đều dùng để mô tả sự nhanh chậm của chuyển động. Em đã từng sử dụng hai đại lượng này trong những trường hợp cụ thể nào?",
    "",
    "## I. TỐC ĐỘ",
    "**1. Tốc độ trung bình**",
    "Người ta dùng hai cách sau đây để xác định độ nhanh hay chậm của chuyển động:",
    "- So sánh quãng đường đi được trong cùng một thời gian.",
    "- So sánh thời gian để đi cùng một quãng đường.",
    "",
    "**Hoạt động:**",
    "Một vận động viên người Nam Phi đã lập kỉ lục thế giới về chạy ba cự li: 100 m, 200 m và 400 m (Bảng 5.1). Hãy dùng hai cách trên để xác định vận động viên này chạy nhanh nhất ở cự li nào.",
    "",
    "**Bảng 5.1.** Kỉ lục chạy ba cự li của một vận động viên người Nam Phi",
    "| Cự li chạy (m) | Thời gian chạy (s) |",
    "|---|---|",
    "| 100 | 9,98 |",
    "| 200 | 19,94 |",
    "| 400 | 43,45 |",
    "Chú ý: từ công thức (5.1a) suy ra công thức của:",
    "- Quãng đường đi được:",
    "$s = v.t$",
    "- Thời gian đi: $t = \\frac{s}{v}$.",
    "",
    "Người ta thường dùng quãng đường đi được trong cùng một đơn vị thời gian để xác định độ nhanh, chậm của chuyển động. Đại lượng này gọi là tốc độ trung bình của chuyển động (gọi tắt là tốc độ trung bình), kí hiệu là $v$:",
    "Tốc độ trung bình = $\\frac{\\text{Quãng đường đi được}}{\\text{Thời gian}}$",
    "$v = \\frac{s}{t}$ (5.1a)",
    "",
    "**! Chú ý:** Nếu gọi quãng đường đi được từ thời điểm ban đầu tới thời điểm $t_1$ là $s_1$, tới thời điểm $t_2$ là $s_2$ thì:",
    "- Thời gian đi là: $\\Delta t = t_2 - t_1$;",
    "- Quãng đường đi được trong thời gian $\\Delta t$ là $\\Delta s = s_2 - s_1$;",
    "- Tốc độ trung bình của chuyển động là: $v = \\frac{\\Delta s}{\\Delta t}$ (5.1b)",
    "",
    "**? Câu hỏi:**",
    "1. Tại sao tốc độ này được gọi là tốc độ trung bình?",
    "2. Hãy tính tốc độ trung bình ra đơn vị m/s và km/h của nữ vận động viên tại một số giải thi đấu dựa vào Bảng 5.2.",
    "",
    "**Bảng 5.2.** Thành tích của một nữ vận động viên Việt Nam",
    "| Giải thi đấu | Cự li chạy (m) | Thời gian chạy (s) |",
    "|---|---|---|",
    "| Điền kinh quốc gia 2016 | 100 | 11,64 |",
    "| SEA Games 29 (2017) | 100 | 11,56 |",
    "| SEA Games 30 (2019) | 100 | 11,54 |",
    "",
    "26",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**2. Tốc độ tức thời**",
    "Trên xe máy và ô tô, đồng hồ tốc độ (tốc kế) đặt trước mặt người lái xe, chỉ tốc độ mà xe đang chạy vào thời điểm người lái xe đọc số chỉ của tốc kế. Tốc độ này được gọi là *tốc độ tức thời*.",
    "",
    "**? Câu hỏi:**",
    "Bố bạn A đưa A đi học bằng xe máy vào lúc 7 giờ. Sau 5 phút xe đạt tốc độ 30 km/h. Sau 10 phút nữa, xe tăng tốc độ lên thêm 15 km/h. Đến gần trường, xe giảm dần tốc độ và dừng trước cổng trường lúc 7 giờ 30 phút.",
    "a) Tính tốc độ trung bình của xe máy chở A khi đi từ nhà đến trường. Biết quãng đường từ nhà đến trường dài 15 km.",
    "b) Tính tốc độ của xe vào lúc 7 giờ 15 phút và 7 giờ 30 phút. Tốc độ này là tốc độ gì?",
    "",
    "**EM CÓ BIẾT?**",
    "Khái niệm tốc độ tức thời liên quan đến phép tính đạo hàm của môn Toán sẽ được học ở lớp 11. Có thể coi tốc độ tức thời là tốc độ trung bình trong một khoảng thời gian rất ngắn.",
    "",
    "## II. VẬN TỐC",
    "**1. Vận tốc trung bình**",
    "Biết tốc độ và thời gian chuyển động nhưng chưa biết hướng chuyển động thì chưa thể xác định được vị trí của vật. Biết tốc độ, thời gian chuyển động và hướng chuyển động của vật thì có thể xác định được vị trí của vật.",
    "",
    "[Hình 5.1. Bản đồ khu vực quanh Sân vận động, Ngã tư có các điểm A, B, C, D, E, G, H, I. Trường học, Siêu thị]",
    "",
    "**? Câu hỏi:**",
    "Một người đi xe máy qua ngã tư (Hình 5.1) với tốc độ trung bình 30 km/h theo hướng Bắc. Sau 3 phút người đó đến vị trí nào trên hình?",
    "",
    "**? Câu hỏi:**",
    "Theo em biểu thức nào sau đây xác định giá trị vận tốc? Tại sao?",
    "a) $\\frac{s}{t}$",
    "b) $vt$",
    "c) $\\frac{d}{t}$",
    "d) $d.t$",
    "",
    "Trong Vật lí, người ta dùng thương số của độ dịch chuyển và thời gian dịch chuyển để xác định độ nhanh, chậm của chuyển động theo một hướng xác định. Đại lượng này được gọi là vận tốc trung bình, kí hiệu là $\\vec{v}$.",
    "$\\vec{v} = \\frac{\\vec{d}}{t}$ (5.2a)",
    "Tương tự như trường hợp (5.1b), ta có thể viết: $v = \\frac{\\Delta d}{\\Delta t}$. (5.2b)",
    "Trong đó $\\Delta d$ là độ dịch chuyển trong thời gian $\\Delta t$.",
    "",
    "27",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "Vì độ dịch chuyển là một đại lượng vectơ nên vận tốc cũng là một đại lượng vectơ. Vectơ vận tốc có:",
    "- Gốc nằm trên vật chuyển động;",
    "- Hướng là hướng của độ dịch chuyển;",
    "- Độ dài tỉ lệ với độ lớn của vận tốc.",
    "",
    "**2. Vận tốc tức thời**",
    "Vận tốc tức thời là vận tốc tại một thời điểm xác định, được kí hiệu là $\\vec{v}_t$:",
    "$\\vec{v}_t = \\frac{\\Delta \\vec{d}}{\\Delta t}$ với $\\Delta t$ rất nhỏ.",
    "",
    "**3. Tổng hợp vận tốc**",
    "**a) Tổng hợp hai vận tốc cùng phương**",
    "*Bài tập ví dụ:* Trên đoàn tàu đang chạy thẳng với vận tốc trung bình 36 km/h so với mặt đường, một hành khách đi về phía đầu tàu với vận tốc 1 m/s so với mặt sàn tàu (Hình 5.3).",
    "a) Hành khách này tham gia mấy chuyển động?",
    "b) Làm cách nào để xác định được vận tốc của hành khách đối với mặt đường?",
    "",
    "*Giải*",
    "a) Hành khách này tham gia 2 chuyển động: Chuyển động với vận tốc 1 m/s so với sàn tàu và chuyển động do tàu kéo đi (chuyển động kéo theo) với vận tốc bằng vận tốc của tàu so với mặt đường. Chuyển động của hành khách so với mặt đường là tổng hợp của hai chuyển động trên.",
    "b) Nếu gọi $\\vec{v}_{1,2}$ là vận tốc của hành khách so với tàu, $\\vec{v}_{2,3}$ là vận tốc của tàu so với mặt đường và $\\vec{v}_{1,3}$ là vận tốc của hành khách so với mặt đường thì: $\\vec{v}_{1,3} = \\vec{v}_{1,2} + \\vec{v}_{2,3}$",
    "Vì các chuyển động trên đều là chuyển động thẳng theo hướng chạy của đoàn tàu nên:",
    "$v_{1,3} = v_{1,2} + v_{2,3} = 1\\text{ m/s} + 10\\text{ m/s} = 11\\text{ m/s}$.",
    "Hướng của vận tốc là hướng đoàn tàu chạy.",
    "",
    "[Hình 5.2. Lộ trình ABC của bạn A. Từ nhà (A) đến B rồi từ B đến Trường (C).]",
    "[Hình 5.3. Hành khách đi trên tàu đang chạy. Hướng chuyển động của tàu là sang phải.]",
    "",
    "**? Câu hỏi:**",
    "Bạn A đi học từ nhà đến trường theo lộ trình ABC (Hình 5.2). Biết bạn A đi đoạn đường AB = 400 m hết 6 phút, đoạn đường BC = 300 m hết 4 phút. Xác định tốc độ trung bình và vận tốc trung bình của bạn A khi đi từ nhà đến trường.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy xác định vận tốc của hành khách đối với mặt đường nếu người này chuyển động về cuối đoàn tàu với vận tốc có cùng độ lớn 1 m/s.",
    "2. Một người bơi trong bể bơi yên lặng có thể đạt tới vận tốc 1 m/s. Nếu người này bơi xuôi dòng sông có dòng chảy với vận tốc 1 m/s thì có thể đạt vận tốc tối đa là bao nhiêu?",
    "3. Một ca nô chạy hết tốc lực trên mặt nước yên lặng có thể đạt 21,5 km/h. Ca nô này chạy xuôi dòng sông trong 1 giờ rồi quay lại thì phải mất 2 giờ nữa mới về tới vị trí ban đầu. Hãy tính vận tốc chảy của dòng sông.",
    "",
    "28",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**b) Tổng hợp hai vận tốc vuông góc với nhau**",
    "*Bài tập ví dụ:* Một ca nô chạy trong hồ nước yên lặng có vận tốc tối đa 18 km/h. Nếu ca nô chạy ngang một con sông có dòng chảy theo hướng Bắc – Nam với vận tốc lên tới 5 m/s thì vận tốc tối đa nó có thể đạt được so với bờ sông là bao nhiêu và theo hướng nào?",
    "",
    "*Giải*",
    "Gọi vận tốc của ca nô đối với mặt nước là $\\vec{v}_{1,2}$; vận tốc của nước chảy đối với bờ sông là $\\vec{v}_{2,3}$. Vận tốc của ca nô đối với bờ sông là:",
    "$\\vec{v}_{1,3} = \\vec{v}_{1,2} + \\vec{v}_{2,3}$. Suy ra: $v_{1,3} = \\sqrt{v_{1,2}^2 + v_{2,3}^2} = \\sqrt{5^2 + 5^2} = 7,07$ m/s.",
    "Vì AB = BC nên $\\Delta ABC$ là tam giác vuông cân và $\\widehat{BAC} = 45^\\circ$. Hướng của vận tốc nghiêng $45^\\circ$ theo hướng Đông – Nam (Hình 5.4).",
    "",
    "[Hình 5.4. Các vectơ vận tốc $\\vec{v}_{1,2}, \\vec{v}_{2,3}, \\vec{v}_{1,3}$ tạo thành tam giác vuông]",
    "",
    "**? Câu hỏi:**",
    "1. Một máy bay đang bay theo hướng Bắc với vận tốc 200 m/s thì bị gió từ hướng Tây thổi vào với vận tốc 20 m/s. Xác định vận tốc tổng hợp của máy bay lúc này.",
    "2. Một người lái máy bay thể thao đang tập bay ngang. Khi bay từ A đến B thì vận tốc tổng hợp của máy bay là 15 m/s theo hướng $60^\\circ$ Đông – Bắc và vận tốc của gió là 7,5 m/s theo hướng Bắc.",
    "Hãy chứng minh rằng khi bay từ A đến B thì người lái phải luôn hướng máy bay về hướng Đông.",
    "",
    "**EM ĐÃ HỌC**",
    "- Tốc độ trung bình trên một đoạn đường xác định (hoặc trong một khoảng thời gian xác định):",
    "$v = \\frac{s}{t}$ hoặc $v = \\frac{\\Delta s}{\\Delta t}$",
    "- Tốc độ tức thời là tốc độ tại một thời điểm xác định.",
    "- Vận tốc trung bình trên một độ dịch chuyển xác định (hoặc trong một khoảng thời gian xác định):",
    "$\\vec{v} = \\frac{\\vec{d}}{t}$ hoặc $\\vec{v} = \\frac{\\Delta \\vec{d}}{\\Delta t}$",
    "- Vận tốc tức thời là vận tốc tại một thời điểm xác định:",
    "$\\vec{v}_t = \\frac{\\Delta \\vec{d}}{\\Delta t}$ với $\\Delta t$ rất nhỏ.",
    "- Khi vật chuyển động thẳng theo một hướng thì tốc độ và vận tốc có độ lớn bằng nhau: $v = |\\vec{v}|$.",
    "- Công thức cộng vận tốc: $\\vec{v}_{1,3} = \\vec{v}_{1,2} + \\vec{v}_{2,3}$",
    "Trong đó $\\vec{v}_{1,2}$ là vận tốc của vật (1) đối với vật (2); $\\vec{v}_{2,3}$ là vận tốc của vật (2) so với vật (3) đứng yên; $\\vec{v}_{1,3}$ (vận tốc tổng hợp của vật) là vận tốc của vật (1) đối với vật (3).",
    "",
    "**EM CÓ THỂ**",
    "1. Tự xác định được tốc độ chuyển động của mình trong một số trường hợp đơn giản.",
    "2. Sử dụng đúng các thuật ngữ tốc độ và vận tốc trong các tình huống khác nhau.",
    "",
    "29"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B6', 'Bài 6 THỰC HÀNH: ĐO TỐC ĐỘ CỦA VẬT CHUYỂN ĐỘNG', 31, 3, $JSON$
{
  "content": [
    "# Bài 6 THỰC HÀNH: ĐO TỐC ĐỘ CỦA VẬT CHUYỂN ĐỘNG",
    "",
    "**Khởi động:**",
    "Làm thế nào đo được tốc độ chuyển động của vật bằng dụng cụ thí nghiệm thực hành?",
    "",
    "## I. CÁCH ĐO TỐC ĐỘ TRONG PHÒNG THÍ NGHIỆM",
    "Để đo tốc độ chuyển động của một vật có thể đo thời gian và quãng đường chuyển động của vật đó.",
    "",
    "**Hoạt động:** Hãy thảo luận nhóm và trả lời câu hỏi sau:",
    "1. Dùng dụng cụ gì để đo quãng đường và thời gian chuyển động của vật?",
    "2. Làm thế nào đo được quãng đường đi được của vật trong một khoảng thời gian hoặc ngược lại?",
    "3. Thiết kế các phương án đo tốc độ và so sánh ưu, nhược điểm của các phương án đó.",
    "",
    "## II. GIỚI THIỆU DỤNG CỤ ĐO THỜI GIAN",
    "Dụng cụ đo độ dài đã được học ở Trung học cơ sở, phần này chỉ giới thiệu các dụng cụ đo thời gian chưa được học một cách đầy đủ.",
    "",
    "**1. Đồng hồ đo thời gian hiện số và cổng quang điện**",
    "Đồng hồ đo thời gian hiện số (Hình 6.2) có thể đo thời gian chính xác đến phần nghìn giây, được điều khiển bằng cổng quang điện (Hình 6.1).",
    "",
    "[Hình 6.1. Cấu tạo cổng quang điện. Có Vật chuyển động và 2 đầu thu phát quang điện $D_1, D_2$]",
    "[Hình 6.2. Đồng hồ đo thời gian hiện số. a) Mặt trước đồng hồ MC964, b) Mặt sau đồng hồ MC964]",
    "",
    "**! Chú ý:** Sử dụng đồng hồ đo thời gian hiện số MC964 (Hình 6.2):",
    "- THANG ĐO: Chọn thang đo thời gian, với ĐCNN tương ứng là 0,001 s hoặc 0,01 s.",
    "- MODE: Chọn kiểu làm việc cho máy đo thời gian.",
    "(1) MODE A: Đo thời gian vật chắn cổng quang điện nối với ổ A (Hình 6.3).",
    "(2) MODE B: Đo thời gian vật chắn cổng quang điện nối với ổ B.",
    "(3) MODE A + B: Đo tổng của hai khoảng thời gian vật chắn cổng quang điện nối với ổ A và vật chắn cổng quang điện nối với ổ B.",
    "(4) MODE A $\\leftrightarrow$ B: Đo thời gian vật chuyển động từ cổng quang điện nối với ổ A tới cổng quang điện nối với ổ B.",
    "(5) MODE T: Đo khoảng thời gian T của từng chu kì dao động.",
    "- Nút RESET: Đặt lại chỉ số của đồng hồ về giá trị 0000.",
    "",
    "**? Câu hỏi:**",
