INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B7', 'Bài 7 ĐỒ THỊ ĐỘ DỊCH CHUYỂN – THỜI GIAN', 35, 4, $JSON$
{
  "content": [
    "# Bài 7 ĐỒ THỊ ĐỘ DỊCH CHUYỂN – THỜI GIAN",
    "",
    "**Khởi động:**",
    "Hãy nhớ lại kiến thức đã học về đồ thị của chuyển động trong môn Khoa học tự nhiên 7 để phát hiện ra tính chất của các chuyển động thẳng có đồ thị mô tả ở những hình sau.",
    "[Hình ảnh các đồ thị $s-t$ a, b, c, d. Trục tung là $s$, trục hoành là $t$.",
    "a) Đồ thị là đường thẳng đi lên từ gốc toạ độ.",
    "b) Đồ thị là đường thẳng song song với trục $t$.",
    "c) Đồ thị gồm hai đường (1) và (2) đi lên từ gốc toạ độ, (1) dốc hơn (2).",
    "d) Đồ thị gồm hai đường: (1) từ một điểm trên trục tung đi xuống, (2) từ một điểm thấp hơn trên trục tung đi lên cắt (1).]",
    "",
    "## I. CHUYỂN ĐỘNG THẲNG",
    "Chuyển động thẳng là chuyển động thường gặp trong đời sống, có quỹ đạo chuyển động là đường thẳng.",
    "Khi vật chuyển động thẳng theo một chiều không đổi thì độ dịch chuyển và quãng đường đi được có độ lớn như nhau $d = s$; vận tốc và tốc độ có độ lớn như nhau $v = v$.",
    "Khi vật đang chuyển động thẳng theo chiều dương, nếu đổi chiều chuyển động thì trong khoảng thời gian chuyển động ngược chiều đó quãng đường đi được vẫn có giá trị dương, còn độ dịch chuyển có giá trị âm; tốc độ vẫn có giá trị dương còn vận tốc có giá trị âm $v = -v$.",
    "Dựa vào các công thức (5.1) và (5.2) ta có thể xác định được quãng đường đi được, độ dịch chuyển, tốc độ và vận tốc của chuyển động.",
    "",
    "**? Câu hỏi:**",
    "Hãy tính quãng đường đi được, độ dịch chuyển, tốc độ, vận tốc của bạn A khi đi từ nhà đến trường và khi đi từ trường đến siêu thị (Hình 7.1). Coi chuyển động của bạn A là chuyển động đều và biết cứ 100 m bạn A đi hết 25 s.",
    "[Hình 7.1. Trục tọa độ Ox với gốc tại Nhà (0m), Siêu thị (800m) và Trường học (1000m)]",
    "",
    "34",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "## II. ĐỒ THỊ ĐỘ DỊCH CHUYỂN – THỜI GIAN TRONG CHUYỂN ĐỘNG THẲNG",
    "Đồ thị độ dịch chuyển – thời gian của một chuyển động không những cho phép mô tả được chuyển động, mà còn có thể cho biết nhiều thông tin khác nữa về chuyển động.",
    "",
    "**1. Cách vẽ đồ thị độ dịch chuyển – thời gian (d – t) trong chuyển động thẳng đều**",
    "Đồ thị đơn giản nhất là đồ thị độ dịch chuyển – thời gian của chuyển động thẳng đều. Trong chuyển động thẳng đều thì $d = v.t$ (với v là một hằng số). Biểu thức $d = v.t$ có dạng giống biểu thức của hàm số $y = a.x$ đã học trong môn Toán nên có đường biểu diễn là một đoạn thẳng.",
    "",
    "**Hoạt động:** Hãy vẽ đồ thị độ dịch chuyển – thời gian trong chuyển động của bạn A nêu ở trên theo trình tự sau đây:",
    "1. Vẽ bảng ghi số liệu vào vở.",
    "| Độ dịch chuyển (m) | 0 | 200 | 400 | 600 | 800 | 1000 | 800 |",
    "|---|---|---|---|---|---|---|---|",
    "| Thời gian (s) | 0 | 50 | 100 | 150 | 200 | 250 | 300 |",
    "2. Vẽ đồ thị: trên trục tung (trục độ dịch chuyển) 1 cm ứng với 200 m; trên trục hoành (trục thời gian) 1 cm ứng với 50 s.",
    "",
    "**2. Sử dụng đồ thị độ dịch chuyển – thời gian trong chuyển động thẳng**",
    "**Hoạt động:** Hình 7.2 là đồ thị độ dịch chuyển – thời gian của một người đang bơi trong một bể bơi dài 50 m. Đồ thị này cho biết những gì về chuyển động của người đó?",
    "1. Trong 25 giây đầu mỗi giây người đó bơi được bao nhiêu mét? Tính vận tốc của người đó ra m/s.",
    "2. Từ giây nào đến giây nào người đó không bơi?",
    "3. Từ giây 35 đến giây 60 người đó bơi theo chiều nào?",
    "4. Trong 20 giây cuối cùng, mỗi giây người đó bơi được bao nhiêu mét? Tính vận tốc của người đó ra m/s.",
    "5. Xác định độ dịch chuyển và vận tốc của người đó khi bơi từ B đến C.",
    "6. Xác định độ dịch chuyển và vận tốc của người đó trong cả quá trình bơi.",
    "",
    "[Hình 7.2. Đồ thị d-t của người bơi. Gốc O(0,0), lên A(25, 50), ngang đến B(35, 50), xuống C(60, 20)]",
    "",
    "**EM CÓ BIẾT?**",
    "1. Đồ thị của các hàm số đã học trong môn Toán:",
    "[Hình 7.3a: Đồ thị hàm số y = a.x (a > 0)]",
    "[Hình 7.3b: Đồ thị hàm số y = a.x + b (a < 0; b > 0)]",
    "2. Khi vật chuyển động thẳng với vận tốc không đổi $v > 0$ thì $d = v.t$. Phương trình này có dạng của hàm số $y = a.x$ nên có đồ thị ở Hình 7.3a.",
    "3. Khi vật đang chuyển động thẳng, theo chiều dương, nếu đổi chiều chuyển động thì trong khoảng thời gian chuyển động ngược chiều đó, quãng đường đi được vẫn có giá trị dương còn độ dịch chuyển có giá trị âm. Đồ thị độ dịch chuyển – thời gian có dạng như Hình 7.3b.",
    "",
    "**? Câu hỏi:**",
    "Hãy xác định vận tốc và tốc độ của người bơi từ giây 45 đến giây 60 bằng đồ thị ở Hình 7.2.",
    "",
    "35",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "## III. VẬN TỐC VÀ ĐỒ THỊ ĐỘ DỊCH CHUYỂN – THỜI GIAN TRONG CHUYỂN ĐỘNG THẲNG",
    "Từ đồ thị độ dịch chuyển – thời gian có thể dễ dàng tính được giá trị của vận tốc.",
    "Trong đồ thị vẽ ở Hình 7.2, hệ số góc (độ dốc) của đường biểu diễn OA là:",
    "$\\frac{\\Delta d}{\\Delta t} = \\frac{50 - 20}{25 - 10} = \\frac{30}{15} = 2$ m/s",
    "Đây chính là độ lớn vận tốc của người bơi trong 50 m đầu.",
    "Độ dốc của đồ thị độ dịch chuyển – thời gian trong chuyển động thẳng cho biết độ lớn vận tốc chuyển động.",
    "",
    "**Hoạt động: Vận dụng**",
    "1. Số liệu về độ dịch chuyển và thời gian của chuyển động thẳng của một xe ô tô đồ chơi chạy bằng pin được ghi trong bảng bên:",
    "| Độ dịch chuyển (m) | 1 | 3 | 5 | 7 | 7 | 7 |",
    "|---|---|---|---|---|---|---|",
    "| Thời gian (s) | 0 | 1 | 2 | 3 | 4 | 5 |",
    "Dựa vào bảng này để:",
    "a) Vẽ đồ thị độ dịch chuyển – thời gian của chuyển động.",
    "b) Mô tả chuyển động của xe.",
    "c) Tính vận tốc của xe trong 3 s đầu.",
    "2. Đồ thị độ dịch chuyển – thời gian trong chuyển động thẳng của một xe ô tô đồ chơi điều khiển từ xa được vẽ ở Hình 7.4.",
    "[Hình 7.4. Đồ thị d-t. Gốc(0,0), lên điểm(2, 4), ngang đến điểm(4, 4), xuống điểm(9, -1), ngang đến điểm(10, -1)]",
    "a) Mô tả chuyển động của xe.",
    "b) Xác định vị trí của xe so với điểm xuất phát của xe ở giây thứ 2, giây thứ 4, giây thứ 8 và giây thứ 10.",
    "c) Xác định tốc độ và vận tốc của xe trong 2 giây đầu, từ giây 2 đến giây 4 và từ giây 4 đến giây 8.",
    "d) Xác định quãng đường đi được và độ dịch chuyển của xe sau 10 giây chuyển động. Tại sao giá trị của chúng không giống nhau?",
    "",
    "**EM ĐÃ HỌC**",
    "- Dùng đồ thị độ dịch chuyển – thời gian của chuyển động thẳng có thể mô tả được chuyển động: biết khi nào vật chuyển động, khi nào vật dừng, khi nào vật chuyển động nhanh, khi nào vật chuyển động chậm, khi nào vật đổi chiều chuyển động,...",
    "- Vận tốc có giá trị bằng hệ số góc (độ dốc) của đường biểu diễn trong đồ thị độ dịch chuyển – thời gian của chuyển động thẳng.",
    "",
    "**EM CÓ THỂ**",
    "1. Vẽ được đồ thị độ dịch chuyển – thời gian của chuyển động thẳng.",
    "2. Dựa vào đồ thị độ dịch chuyển – thời gian, xác định được vị trí và vận tốc của vật ở bất kì thời điểm nào.",
    "",
    "36"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B8', 'Bài 8 CHUYỂN ĐỘNG BIẾN ĐỔI. GIA TỐC', 38, 5, $JSON$
{
  "content": [
    "# Bài 8 CHUYỂN ĐỘNG BIẾN ĐỔI. GIA TỐC",
    "",
    "**Khởi động:**",
    "Hình dưới là ảnh chụp hoạt nghiệm thí nghiệm về sự thay đổi vận tốc của một ô tô đồ chơi chạy bằng pin có gắn anten dùng để điều khiển từ xa, trong ba giai đoạn chuyển động. Vận tốc trong ba giai đoạn chuyển động này có gì giống nhau, khác nhau?",
    "[Hình ảnh 3 giai đoạn chuyển động a), b), c) của một chiếc ô tô đồ chơi. Mỗi ảnh có các vị trí của ô tô đồ chơi theo thời gian, cho thấy khoảng cách giữa các vị trí trong (a) xa dần, (b) đều nhau, (c) gần dần]",
    "",
    "## I. CHUYỂN ĐỘNG BIẾN ĐỔI",
    "Một ô tô đang đứng yên, bắt đầu chuyển động sẽ chuyển động nhanh dần (vận tốc tăng dần); khi đang chuyển động muốn dừng lại sẽ phải chuyển động chậm dần (vận tốc giảm dần).",
    "Chuyển động có vận tốc thay đổi được gọi là chuyển động biến đổi.",
    "",
    "**? Câu hỏi:**",
    "Hãy tìm thêm ví dụ về chuyển động biến đổi trong cuộc sống.",
    "",
    "## II. GIA TỐC CỦA CHUYỂN ĐỘNG BIẾN ĐỔI",
    "**1. Khái niệm gia tốc**",
    "Để xác định được sự thay đổi vận tốc theo thời gian, phải biết vận tốc tức thời của chuyển động tại các thời điểm khác nhau. Các phương tiện giao thông như xe máy, ô tô được trang bị tốc kế là thiết bị đo trực tiếp vận tốc tức thời. Do đó có thể dùng tốc kế trên xe máy hoặc ô tô để tìm hiểu sự thay đổi vận tốc của chuyển động biến đổi.",
    "Bảng dưới đây ghi vận tốc tức thời đo bởi tốc kế của một ô tô sau các khoảng thời gian 2 s kể từ khi bắt đầu chạy trên một đường thẳng.",
    "",
    "**Bảng 8.1.** Bảng ghi số liệu vận tốc tức thời của một chuyển động",
    "| Thời điểm t (s) | 0 | 2 | 4 | 6 | 8 |",
    "|---|---|---|---|---|---|",
    "| Vận tốc tức thời $v_t$ | (km/h) | 0 | 9 | 19 | 30 | 45 |",
    "| | (m/s) | 0 | 2,50 | 5,28 | 8,33 | 12,50 |",
    "Bảng trên cho thấy vận tốc của ô tô tăng dần theo thời gian: Ô tô chuyển động nhanh dần.",
    "",
    "**EM CÓ BIẾT?**",
    "1. Thuật ngữ “gia tốc” có nghĩa là tăng thêm tốc độ. Tuy nhiên trong vật lí, gia tốc không chỉ được dùng để mô tả sự tăng vận tốc mà còn dùng để mô tả sự giảm vận tốc.",
    "2. Trong các bài sau, chúng ta sẽ thấy gia tốc không những dùng để mô tả sự thay đổi về độ lớn của vận tốc mà còn dùng để mô tả cả sự thay đổi hướng của vận tốc.",
    "3. Gia tốc xác định bằng công thức $a = \\frac{\\Delta v}{\\Delta t}$ được gọi là gia tốc trung bình.",
    "Nếu $\\Delta t$ rất nhỏ thì có thể coi gia tốc này là gia tốc tức thời.",
    "",
    "37",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**? Câu hỏi:**",
    "1. Xác định độ biến thiên vận tốc sau 8 s của chuyển động trên.",
    "2. Xác định độ biến thiên vận tốc sau mỗi giây của chuyển động trên trong 4 s đầu và trong 4 s cuối.",
    "3. Các đại lượng xác định được ở câu 2 cho ta biết điều gì về sự thay đổi vận tốc của chuyển động trên?",
    "",
    "Nếu trong thời gian $\\Delta t$, độ biến thiên vận tốc là $\\Delta v$ thì độ biến thiên của vận tốc trong một đơn vị thời gian là:",
    "$a = \\frac{\\Delta v}{\\Delta t} = \\frac{v_t - v_0}{t - t_0}$ (1)",
    "Đại lượng a cho biết sự thay đổi nhanh hay chậm của vận tốc được gọi là gia tốc của chuyển động (gọi tắt là gia tốc).",
    "Nếu $\\Delta v$ có đơn vị là m/s (m.s$^{-1}$), $\\Delta t$ có đơn vị là giây (s), thì gia tốc có đơn vị là m/s$^2$ (m.s$^{-2}$).",
    "Vì $\\Delta\\vec{v}$ là đại lượng vectơ, nên gia tốc $\\vec{a}$ cũng là đại lượng vectơ:",
    "$\\vec{a} = \\frac{\\Delta\\vec{v}}{\\Delta t}$ (2)",
    "",
    "**? Câu hỏi:**",
    "Hãy chứng tỏ khi $\\vec{a}$ cùng chiều với $\\vec{v}$ (a.v > 0) thì chuyển động là nhanh dần, khi $\\vec{a}$ ngược chiều với $\\vec{v}$ (a.v < 0) thì chuyển động là chậm dần.",
    "",
    "**2. Bài tập ví dụ**",
    "Một xe máy đang chuyển động thẳng với vận tốc 10 m/s thì tăng tốc. Biết rằng sau 5 s kể từ khi tăng tốc, xe đạt vận tốc 12 m/s.",
    "a) Tính gia tốc của xe.",
    "b) Nếu sau khi đạt vận tốc 12 m/s, xe chuyển động chậm dần với gia tốc có độ lớn bằng gia tốc trên thì sau bao lâu xe sẽ dừng lại?",
    "",
    "*Giải*",
    "a) $v_0$ = 10 m/s",
    "$v$ = 12 m/s",
    "$\\Delta t$ = 5 s",
    "---",
    "a?",
    "$a = \\frac{\\Delta v}{\\Delta t} = \\frac{12 - 10}{5} = 0,4$ m/s$^2$",
    "Gia tốc của xe a = 0,4 m/s$^2$",
    "",
    "b) $v_0'$ = 12 m/s",
    "$v'$ = 0",
    "$a$ = - 0,4 m/s$^2$",
    "---",
    "$\\Delta t$?",
    "$\\Delta t' = \\frac{\\Delta v'}{a} = \\frac{0 - 12}{-0,4} = 30$ s",
    "Xe dừng lại sau 30 s.",
    "",
    "38",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**? Câu hỏi:**",
    "1. a) Tính gia tốc của ô tô trên 4 đoạn đường trong Hình 8.1.",
    "b) Gia tốc của ô tô trên đoạn đường 4 có gì đặc biệt so với sự thay đổi vận tốc trên các đoạn đường khác?",
    "[Hình 8.1. Các ô tô trên 4 đoạn đường. $t_0 = 0$, $t_1 = 1s$ (v = 5 km/h), $t_2 = 4s$ (v = 29 km/h), $t_3 = 6s$ (v = 49 km/h), $t_4 = 7s$ (v = 30 km/h)]",
    "2. Một con báo đang chạy với vận tốc 30 m/s thì chuyển động chậm dần khi tới gần một con suối. Trong 3 giây, vận tốc của nó giảm còn 9 m/s. Tính gia tốc của con báo.",
    "3. Đồ thị ở Hình 8.2 mô tả sự thay đổi vận tốc theo thời gian trong chuyển động của một ô tô thể thao đang chạy thử về phía Bắc.",
    "Tính gia tốc của ô tô:",
    "a) Trong 4 s đầu.",
    "b) Từ giây thứ 4 đến giây thứ 12.",
    "c) Từ giây thứ 12 đến giây thứ 20.",
    "d) Từ giây thứ 20 đến giây thứ 28.",
    "[Hình 8.2. Đồ thị v-t. Gốc (0,0), lên điểm(4, 20), ngang đến điểm(12, 20), xuống điểm(20, 0), xuống điểm(28, -20)]",
    "",
    "**EM ĐÃ HỌC**",
    "- Gia tốc là đại lượng cho biết sự thay đổi nhanh chậm của sự thay đổi vận tốc: $\\vec{a} = \\frac{\\Delta \\vec{v}}{\\Delta t}$.",
    "- Khi $\\vec{a}$ cùng chiều với $\\vec{v}$ (a.v > 0): chuyển động nhanh dần; khi $\\vec{a}$ ngược chiều với $\\vec{v}$ (a.v < 0): chuyển động chậm dần.",
    "- Đơn vị của gia tốc trong hệ SI là m/s$^2$ (m.s$^{-2}$).",
    "",
    "**EM CÓ THỂ**",
    "Dùng khái niệm gia tốc để giải thích một số hiện tượng về chuyển động dưới tác dụng của lực. Ví dụ như chuyển động rơi của một vật là chuyển động có gia tốc vì vật rơi chịu tác dụng của lực hút của Trái Đất.",
    "",
    "39"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B9', 'Bài 9 CHUYỂN ĐỘNG THẲNG BIẾN ĐỔI ĐỀU', 41, 6, $JSON$
{
  "content": [
    "# Bài 9 CHUYỂN ĐỘNG THẲNG BIẾN ĐỔI ĐỀU",
    "",
    "**Khởi động:**",
    "[Hình ảnh mô tả sự thay đổi vị trí và vận tốc của ô tô và người.",
    "a) Ô tô: t=0s, v=0km/h; t=1s, v=10km/h; t=2s, v=20km/h; t=3s, v=30km/h",
    "b) Người: t=0s, v=6m/s; t=1s, v=4m/s; t=2s, v=2m/s; t=3s, v=0m/s]",
    "Hình trên mô tả sự thay đổi vị trí và vận tốc của ô tô, người sau những khoảng thời gian bằng nhau. Hai chuyển động này có gì giống nhau, khác nhau?",
    "",
    "## I. GIA TỐC CỦA CHUYỂN ĐỘNG THẲNG BIẾN ĐỔI ĐỀU",
    "Chuyển động thẳng biến đổi đều là chuyển động thẳng mà vận tốc có độ lớn tăng hoặc giảm đều theo thời gian.",
    "Chuyển động thẳng có độ lớn vận tốc tăng đều theo thời gian gọi là chuyển động thẳng nhanh dần đều; chuyển động thẳng có độ lớn vận tốc giảm đều theo thời gian gọi là chuyển động thẳng chậm dần đều.",
    "Vì chuyển động thẳng biến đổi đều có vận tốc thay đổi đều theo thời gian nên gia tốc của chuyển động này không đổi theo thời gian:",
    "$a = \\frac{\\Delta v}{\\Delta t} = \\text{hằng số}$ (9.1)",
    "",
    "**? Câu hỏi:**",
    "1. Tính gia tốc của các chuyển động trong hình vẽ ở đầu bài.",
    "2. Các chuyển động trong hình vẽ ở đầu bài có phải là chuyển động thẳng biến đổi đều không?",
    "",
    "## II. VẬN TỐC TỨC THỜI CỦA CHUYỂN ĐỘNG THẲNG BIẾN ĐỔI ĐỀU",
    "Gọi $v_0$ là vận tốc tại thời điểm ban đầu $t_0$, $v_t$ là vận tốc tại thời điểm t.",
    "Vì $a = \\frac{\\Delta v}{\\Delta t} = \\frac{v_t - v_0}{t - t_0} = \\frac{v_t - v_0}{\\Delta t}$ nên $v_t = v_0 + a.\\Delta t$.",
    "Nếu ở thời điểm ban đầu $t_0 = 0$ thì:",
    "$v_t = v_0 + a.t$ (9.2)",
    "Nếu ở thời điểm ban đầu $t_0 = 0$ vật mới bắt đầu chuyển động thì:",
    "$v_0 = 0$ và $v_t = a.t$ (9.3)",
    "",
    "40",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "## III. ĐỒ THỊ VẬN TỐC – THỜI GIAN CỦA CHUYỂN ĐỘNG THẲNG BIẾN ĐỔI ĐỀU",
    "Các công thức (9.2) và (9.3) cho thấy vận tốc tức thời v trong chuyển động thẳng biến đổi đều là hàm bậc nhất của thời gian t, nên đồ thị vận tốc – thời gian của chuyển động này có các dạng như Hình 9.1.",
    "[Hình 9.1. Các dạng đồ thị vận tốc - thời gian.",
    "a) Đồ thị đi qua gốc toạ độ, đi lên.",
    "b) Đồ thị cắt trục tung tại $v_0 > 0$, đi lên.",
    "c) Đồ thị cắt trục tung tại $v_0 > 0$, đi xuống.]",
    "*Hình 9.1. Các dạng đồ thị vận tốc - thời gian trong chuyển động thẳng biến đổi đều*",
    "",
    "**? Câu hỏi:**",
    "1. Từ các đồ thị trong Hình 9.1:",
    "a) Hãy viết công thức về mối liên hệ giữa v với a và t của từng chuyển động ứng với từng đồ thị trong Hình 9.1.",
    "b) Chuyển động nào là chuyển động nhanh dần đều, chậm dần đều?",
    "2. Hình 9.2 là đồ thị vận tốc – thời gian trong chuyển động của một bạn đang đi trong siêu thị. Hãy dựa vào đồ thị để mô tả bằng lời chuyển động của bạn đó (khi nào đi đều, đi nhanh lên, đi chậm lại, nghỉ).",
    "[Hình 9.2. Đồ thị v-t. Đi ngang từ t=0 đến t=4 (v=1), từ t=4 đến t=6 tốc độ giảm xuống v=0, từ t=6 đến t=8 vận tốc v=0, từ t=8 đến t=10 vận tốc giảm xuống v=-0,5]",
    "",
    "## IV. ĐỘ DỊCH CHUYỂN CỦA CHUYỂN ĐỘNG THẲNG BIẾN ĐỔI ĐỀU",
    "**1. Tính độ dịch chuyển bằng đồ thị vận tốc – thời gian (v – t)**",
    "- Trong khoảng thời gian t, nếu vật chuyển động thẳng đều với vận tốc v, thì đồ thị (v – t) có dạng như Hình 9.3a và độ dịch chuyển trong thời gian này có độ lớn là: $d = v.t$.",
    "Độ lớn này bằng diện tích của hình chữ nhật, các cạnh có độ dài là v và t. Diện tích này gọi là diện tích giới hạn của đồ thị (v – t) đối với trục hoành.",
    "[Hình 9.3a. Đồ thị v-t của chuyển động thẳng đều, v=3, t từ 0 đến 5. Diện tích hình chữ nhật là 3x5=15]",
    "a) Đồ thị (v – t) của chuyển động thẳng đều:",
    "Diện tích đồ thị: S = 3.5 = 15",
    "Độ dịch chuyển d = 15 m",
    "",
    "- Trong thời gian t, nếu vật chuyển động thẳng biến đổi đều với vận tốc ban đầu $v_0$, thì công thức tính vận tốc là $v_t = v_0 + a.t$, đồ thị (v – t) có dạng như Hình 9.3b. Có thể dựa vào đồ thị này để tính độ dịch chuyển.",
    "Kẻ các đường song song với trục tung Ov, cách nhau một khoảng $\\Delta t$ rất nhỏ để chia đồ thị thành các hình thang nhỏ có đường cao $\\Delta t$.",
    "Chọn một hình thang nhỏ bất kì trong hình. Vì vật chuyển động thẳng biến đổi đều nên trong khoảng thời gian nhỏ từ $t_A$ đến $t_B$, có thể coi chuyển động của vật là thẳng đều với vận tốc $v_C = \\frac{v_A + v_B}{2}$ (C nằm giữa A và B).",
    "Độ dịch chuyển của vật trong thời gian $\\Delta t$ có độ lớn bằng diện tích hình chữ nhật có cạnh là $v_C$ và $\\Delta t$.",
    "[Hình 9.3b. Đồ thị v-t của chuyển động thẳng biến đổi đều. Hàm bậc nhất v(t). Có chia thành nhiều dải nhỏ, xét dải từ $t_A$ đến $t_B$]",
    "b) Đồ thị (v – t) của chuyển động thẳng biến đổi đều.",
    "*Hình 9.3*",
    "",
    "41",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "Hình vẽ cho thấy diện tích của hình này bằng diện tích của hình thang nhỏ gạch chéo trong hình có đường cao $\\Delta t$ và các đáy có độ dài $v_A, v_B$. Độ dịch chuyển trong thời gian t, bằng tổng các độ dịch chuyển trong các khoảng thời gian $\\Delta t$, nên có độ lớn bằng diện tích của hình thang vuông có đường cao là t và các đáy có độ lớn $v_0, v$.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy tính độ dịch chuyển của chuyển động có đồ thị (v – t) vẽ ở Hình 9.3b. Biết mỗi cạnh của ô vuông nhỏ trên trục tung ứng với 2 m/s, trên trục hoành ứng với 1 s.",
    "2. Chứng tỏ rằng có thể xác định được giá trị của gia tốc dựa trên đồ thị (v – t).",
    "",
    "**2. Tính độ dịch chuyển bằng công thức**",
    "**? Câu hỏi:**",
    "1. Biết độ dịch chuyển trong chuyển động thẳng biến đổi đều có độ lớn bằng diện tích giới hạn đồ thị (v – t) trong thời gian t của chuyển động. Hãy chứng minh rằng công thức tính độ lớn của độ dịch chuyển trong chuyển động thẳng biến đổi đều là:",
    "$d = v_0.t + \\frac{1}{2}.a.t^2$ (9.4)",
    "2. Từ công thức (9.2) và (9.4) chứng minh rằng:",
    "$v_t^2 - v_0^2 = 2.a.d$ (9.5)",
    "",
    "**? Câu hỏi:**",
    "Hãy dùng đồ thị (v – t) vẽ ở Hình 9.4 để:",
    "a) Mô tả chuyển động;",
    "b) Tính độ dịch chuyển trong 4 giây đầu, 2 giây tiếp theo và 3 giây cuối;",
    "c) Tính gia tốc của chuyển động trong 4 giây đầu;",
    "d) Tính gia tốc của chuyển động từ giây thứ 4 đến giây thứ 6.",
    "Kiểm tra kết quả của câu b và câu c bằng cách dùng công thức.",
    "[Hình 9.4. Đồ thị v-t. Trục v(m/s) từ 0 đến 8, trục t(s) từ 0 đến 9. Đồ thị đi từ (0, 9) xuống (4, 1), sau đó đi ngang đến (6, 1) (điểm này thực chất là (5, 0) nếu dóng kỹ, à không, nó cắt trục hoành ở 4.5s? Không, đồ thị đi từ v=9 lúc t=0 xuống v=1 lúc t=4? Nhìn kĩ thì nó đi từ (0, 9) xuống đến điểm v=0 tại t=4.5 hoặc t=5. Nhưng điểm gãy là ở t=4, v=1? Không, nó đi thẳng từ (0,9) qua các ô đến khi cắt trục hoành. Chờ, 4 giây đầu, 2 giây tiếp, 3 giây cuối. Tổng là 4+2+3 = 9s. Nó cắt ở t=4 thì sao? À, nó đi từ v=9, qua (4,1)... Thật ra đồ thị vẽ từ v=9, xuống điểm (5, -1)? Nó cắt trục hoành ở t=4.5]",
    "",
    "42",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "*Bài tập vận dụng*",
    "1. Đồ thị vận tốc – thời gian ở Hình 9.5 mô tả chuyển động của một chú chó con đang chạy trong một ngõ thẳng và hẹp.",
    "a) Hãy mô tả chuyển động của chú chó.",
    "b) Tính quãng đường đi được và độ dịch chuyển của chú chó sau: 2 s; 4 s; 7 s và 10 s bằng đồ thị và bằng công thức.",
    "[Hình 9.5. Đồ thị v-t. Đi ngang ở v=1 từ t=0 đến t=2. Đi lên đạt v=3 ở t=5. Đi xuống đạt v=0 ở t=7. Xuống tiếp đạt v=-1 ở t=8. Đi ngang ở v=-1 từ t=8 đến t=10]",
    "*Hình 9.5*",
    "",
    "2. Một vận động viên đua xe đạp đường dài vượt qua vạch đích với tốc độ 10 m/s. Sau đó vận động viên này đi chậm dần đều thêm 20 m mới dừng lại. Coi chuyển động của vận động viên là thẳng.",
    "a) Tính gia tốc của vận động viên trong đoạn đường sau khi qua vạch đích.",
    "b) Tính thời gian vận động viên đó cần để dừng lại kể từ khi cán đích.",
    "c) Tính vận tốc trung bình của người đó trên quãng đường dừng xe.",
    "",
    "**EM ĐÃ HỌC**",
    "- Chuyển động thẳng biến đổi đều là chuyển động thẳng có gia tốc không đổi theo thời gian.",
    "- Chuyển động thẳng nhanh dần đều có (a.v) > 0, chuyển động thẳng chậm dần đều có (a.v) < 0.",
    "- Hệ số góc của đồ thị vận tốc – thời gian của chuyển động thẳng biến đổi đều cho biết giá trị của gia tốc.",
    "- Các công thức của chuyển động thẳng biến đổi đều:",
    "1. $v_t = v_0 + a.t$",
    "2. $d = v_0.t + \\frac{1}{2}.a.t^2$",
    "3. $v_t^2 - v_0^2 = 2.a.d$",
    "",
    "**EM CÓ THỂ**",
    "Từ đồ thị vận tốc – thời gian của chuyển động thẳng biến đổi đều mô tả được chuyển động này.",
    "",
    "43"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B10', 'Bài 10 SỰ RƠI TỰ DO', 45, 7, $JSON$
{
  "content": [
    "# Bài 10 SỰ RƠI TỰ DO",
    "",
    "**Khởi động:**",
    "*Năm 1971, nhà du hành vũ trụ người Mỹ David Scott đã đồng thời thả rơi trên Mặt Trăng một chiếc lông chim và một chiếc búa ở cùng một độ cao và nhận thấy cả hai đều rơi xuống như nhau. Em có suy nghĩ gì về hiện tượng này?*",
    "[Hình ảnh phi hành gia đang thả búa và lông chim trên Mặt Trăng]",
    "",
    "## I. SỰ RƠI TRONG KHÔNG KHÍ",
    "Sự rơi của các vật trong không khí là chuyển động thường gặp. Ai cũng thấy hòn đá rơi nhanh hơn viên phấn, viên phấn rơi nhanh hơn chiếc lông chim. Nhiều người dự đoán rằng, rơi nhanh hay chậm là do vật nặng hay nhẹ. Em có đồng ý với dự đoán đó không? Em có dự đoán nào về nguyên nhân làm cho các vật rơi nhanh chậm khác nhau không?",
    "",
    "**Hoạt động:** Các thí nghiệm (TN) sau đây sẽ giúp chúng ta kiểm tra dự đoán của mình về sự rơi của các vật từ cùng độ cao trong không khí.",
    "TN 1: Thả rơi một viên bi và một chiếc lá.",
    "TN 2: Thả hai tờ giấy giống nhau, nhưng một tờ được vo tròn, một tờ để nguyên.",
    "TN 3: Thả rơi hai viên bi có cùng kích thước, một bằng sắt và một bằng thuỷ tinh.",
    "Từ những thí nghiệm trên, rút ra nhận xét về sự rơi trong không khí.",
    "",
    "**? Câu hỏi:**",
    "1. Trong TN 1, tại sao quả bóng rơi nhanh hơn chiếc lá?",
    "2. Trong TN 2, hai tờ giấy giống nhau, nặng như nhau, tại sao tờ giấy vo tròn lại rơi nhanh hơn?",
    "3. Trong TN 3, trọng lượng bi sắt lớn hơn bi thuỷ tinh, tại sao hai viên bi rơi nhanh như nhau?",
    "",
    "Các thí nghiệm trên cho thấy sự rơi nhanh hay chậm của vật phụ thuộc vào độ lớn của lực cản không khí tác dụng lên vật. Lực cản càng nhỏ so với trọng lực tác dụng lên vật thì vật sẽ rơi càng nhanh và ngược lại.",
    "",
    "**? Câu hỏi:**",
    "Theo em nếu loại bỏ được sức cản của không khí, các vật sẽ rơi như thế nào?",
    "",
    "Câu hỏi này đã được nhà bác học Newton trả lời bằng kết quả thí nghiệm với các ống hút chân không (Hình 10.1): Hai vật rơi là viên bi chì và chiếc lông chim. Kết quả cho thấy trong chân không mọi vật rơi nhanh như nhau.",
    "[Hình 10.1. Thí nghiệm về sự rơi tự do. a) Trong ống có không khí: bi chì rơi nhanh hơn. b) Trong ống không có không khí: bi chì và lông chim rơi như nhau]",
    "",
    "44",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "## II. SỰ RƠI TỰ DO",
    "**1. Sự rơi tự do**",
    "Sự rơi tự do là sự rơi chỉ dưới tác dụng của trọng lực.",
    "Nếu vật rơi trong không khí mà độ lớn của lực cản không khí không đáng kể so với trọng lượng của vật thì cũng coi là rơi tự do.",
    "",
    "**2. Đặc điểm của chuyển động rơi tự do**",
    "**a) Phương và chiều của chuyển động rơi tự do**",
    "Vì trọng lực có phương thẳng đứng, chiều từ trên xuống nên có thể dự đoán sự rơi chỉ dưới tác dụng của trọng lực cũng có phương thẳng đứng, chiều từ trên xuống.",
    "",
    "**Hoạt động:**",
    "1. Hãy thực hiện thí nghiệm (Hình 10.2) để kiểm tra dự đoán về phương và chiều của sự rơi tự do.",
    "2. Dựa vào đặc điểm về phương của sự rơi tự do, hãy tìm cách kiểm tra bề mặt của bức tường trong lớp học có phải là mặt phẳng thẳng đứng không.",
    "3. Hãy nghĩ cách dùng êke tam giác vuông cân và dây dọi để kiểm tra xem sàn lớp mình có phẳng hay không.",
    "[Hình 10.3. Êke tam giác vuông cân]",
    "[Hình 10.2. Thí nghiệm kiểm tra phương thẳng đứng bằng dây dọi và quả nặng thả rơi tự do]",
    "",
    "**b) Tính chất của chuyển động rơi tự do**",
    "Quan sát sự rơi tự do ta thấy đó là chuyển động thẳng nhanh dần. Tuy nhiên, để biết sự rơi tự do có phải là chuyển động thẳng nhanh dần đều hay không thì phải dựa vào thí nghiệm. Vì vật rơi tự do rất nhanh nên người ta thường dùng phương pháp chụp ảnh hoạt nghiệm (dùng máy ảnh đặc biệt chụp liên tiếp vật chuyển động sau những khoảng thời gian bằng nhau) để có thể đo quãng đường rơi được sau những khoảng thời gian bằng nhau.",
    "Bảng 10.1 ghi kết quả chụp ảnh hoạt nghiệm trong phòng thí nghiệm của một trường phổ thông về sự rơi của một hòn bi thép sau những khoảng thời gian 0,1 s.",
    "",
    "**? Câu hỏi:**",
    "Hãy căn cứ vào số liệu trong Bảng 10.1 để:",
    "1. Chứng tỏ chuyển động rơi tự do là nhanh dần đều.",
    "2. Tính gia tốc của chuyển động rơi tự do.",
    "",
    "**? Câu hỏi:**",
    "Trong các chuyển động sau, chuyển động nào được coi là rơi tự do? Tại sao?",
    "A. Chiếc lá đang rơi.",
    "B. Hạt bụi chuyển động trong không khí.",
    "C. Quả tạ rơi trong không khí.",
    "D. Vận động viên đang nhảy dù.",
    "",
    "Trong bài chuyển động biến đổi đều ta đã biết:",
    "Một vật chuyển động thẳng nhanh dần đều không vận tốc ban đầu thì quãng đường đi được s tỉ lệ với bình phương thời gian t:",
    "$s = \\frac{1}{2}.a.t^2$",
    "",
    "**Bảng 10.1.** Quãng đường vật rơi tự do theo thời gian từ kết quả chụp ảnh hoạt nghiệm",
    "| Thời gian rơi (s) | Quãng đường rơi (m) |",
    "|---|---|",
    "| 0,1 | 0,049 |",
    "| 0,2 | 0,197 |",
    "| 0,3 | 0,441 |",
    "| 0,4 | 0,785 |",
    "| 0,5 | 1,227 |",
    "",
    "45",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**c) Gia tốc rơi tự do**",
    "Ở cùng một nơi trên Trái Đất, mọi vật rơi tự do với cùng một gia tốc.",
    "Gia tốc rơi tự do kí hiệu là g, giá trị của g phụ thuộc vào vĩ độ địa lí và độ cao. Ở gần bề mặt Trái Đất người ta thường lấy giá trị của g bằng 9,8 m/s$^2$.",
    "",
    "**3. Công thức rơi tự do**",
    "Rơi tự do có các công thức của chuyển động nhanh dần đều không vận tốc ban đầu. Chọn thời điểm ban đầu $t_0 = 0$.",
    "Độ dịch chuyển, quãng đường đi được tại thời điểm t:",
    "$d = s = \\frac{1}{2}.g.t^2$",
    "Vận tốc tức thời tại thời điểm t: $v_t = g.t$.",
    "Liên hệ giữa vận tốc và quãng đường đi được với gia tốc: $v_t^2 = 2.g.s$.",
    "",
    "*Bài tập vận dụng:* Một người thả một hòn bi từ trên cao xuống đất và đo được thời gian rơi là 3,1 s. Bỏ qua sức cản không khí. Lấy g = 9,8 m/s$^2$.",
    "a) Tính độ cao của nơi thả hòn bi so với mặt đất và vận tốc lúc chạm đất.",
    "b) Tính quãng đường rơi được trong 0,5 s cuối trước khi chạm đất.",
    "",
    "**? Câu hỏi:**",
    "1. Tại sao độ dịch chuyển và quãng đường đi được trong sự rơi tự do có cùng độ lớn?",
    "2. Hãy nêu cách đo gần đúng độ sâu của một cái giếng mỏ cạn. Coi vận tốc truyền âm trong không khí là không đổi và đã biết.",
    "",
    "**EM ĐÃ HỌC**",
    "- Chuyển động rơi chỉ chịu tác dụng của trọng lực gọi là rơi tự do.",
    "- Chuyển động rơi tự do là chuyển động thẳng nhanh dần đều theo phương thẳng đứng, chiều từ trên xuống.",
    "- Tại một nơi nhất định trên Trái Đất và ở gần mặt đất, mọi vật đều rơi tự do với cùng gia tốc g. Gia tốc rơi tự do ở các nơi khác nhau trên Trái Đất thì khác nhau.",
    "- Các công thức của sự rơi tự do:",
    "Gia tốc a = g = hằng số.",
    "Vận tốc tức thời: $v_t = g.t$.",
    "Độ lớn của độ dịch chuyển = Quãng đường đi được: $d = s = \\frac{1}{2}.g.t^2 = \\frac{v_t^2}{2.g}$.",
    "",
    "**EM CÓ THỂ**",
    "- Vận dụng được những kiến thức về sự rơi tự do vào một số tình huống thực tế đơn giản.",
    "- Biết cách xác định phương thẳng đứng và phương nằm ngang.",
    "",
    "46"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B11', 'Bài 11 THỰC HÀNH: ĐO GIA TỐC RƠI TỰ DO', 48, 8, $JSON$
{
  "content": [
    "# Bài 11 THỰC HÀNH: ĐO GIA TỐC RƠI TỰ DO",
    "",
    "**Khởi động:**",
    "*Các vật rơi tự do chuyển động rất nhanh, làm thế nào đo được gia tốc rơi tự do của vật?*",
    "",
    "## I. DỤNG CỤ THÍ NGHIỆM",
    "- Máng đứng, có gắn dây dọi (1).",
    "- Vật bằng thép hình trụ (2).",
    "- Nam châm điện N, dùng giữ và thả trụ thép (3).",
    "- Cổng quang điện E (4).",
    "- Giá đỡ có để ba chân, có vít chỉnh cân bằng và trụ thép (5).",
    "- Đồng hồ đo thời gian hiện số (6).",
    "- Công tắc kép (7).",
    "",
    "[Hình 11.1. Bộ dụng cụ thí nghiệm đo gia tốc rơi tự do, đánh số từ 1 đến 7 các bộ phận tương ứng]",
    "",
    "## II. THIẾT KẾ PHƯƠNG ÁN THÍ NGHIỆM",
    "**Hoạt động:** Thảo luận về phương án thí nghiệm dựa trên hoạt động sau: Thả trụ thép rơi qua cổng quang điện trên máng đứng và trả lời câu hỏi.",
    "1. Xác định gia tốc rơi tự do của trụ thép theo công thức nào?",
    "2. Để xác định gia tốc rơi tự do của trụ thép cần đo các đại lượng nào?",
    "3. Làm thế nào để trụ thép rơi qua cổng quang điện?",
    "4. Cần đặt chế độ đo của đồng hồ ở vị trí nào để đo được đại lượng cần đo?",
    "",
    "## III. TIẾN HÀNH THÍ NGHIỆM",
    "1. Cắm nam châm điện vào ổ A và cổng quang vào ổ B ở mặt sau của đồng hồ đo thời gian hiện số. (xem Hình 6.2)",
    "2. Đặt MODE đồng hồ đo thời gian hiện số ở chế độ thích hợp.",
    "3. Đặt trụ thép tại vị trí tiếp xúc với nam châm điện N và bị giữ lại ở đó.",
    "4. Nhấn nút RESET của đồng hồ MC964 để chuyển các số hiển thị về giá trị ban đầu 0.000.",
    "5. Nhấn nút của hộp công tắc kép để ngắt điện vào nam châm điện: Trụ thép rơi xuống và chuyển động đi qua cổng quang điện.",
    "6. Ghi lại các giá trị thời gian hiển thị trên đồng hồ vào Bảng 11.1.",
    "7. Dịch chuyển cổng quang điện ra xa dần nam châm điện, thực hiện lại các thao tác 3, 4, 5, 6 bốn lần nữa. Ghi các giá trị thời gian t tương ứng với quãng đường s vào Bảng 11.1 trong báo cáo thực hành.",
    "",
    "**! Chú ý:** Để thả rơi trụ thép theo máng đứng có thể thực hiện như sau:",
    "- Đặt máng đứng lên giá đỡ. Vặn chặt vít hãm.",
    "- Nối công tắc điện với nam châm điện và nối công tắc vào ổ cắm A, nối cổng quang điện ổ cắm B ở mặt sau của đồng hồ đo thời gian.",
    "- Cắm nguồn điện của đồng hồ và bật công tắc nguồn. Đặt trụ thép tại vị trí tiếp xúc với nam châm điện N và bị giữ lại ở đó.",
    "- Nhấn nút của hộp công tắc kép để ngắt điện vào nam châm điện.",
    "",
    "47",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "## IV. KẾT QUẢ THÍ NGHIỆM",
    "**Bảng 11.1**",
    "| Quãng đường | Lần đo thời gian |",
    "|---|---|---|---|---|---|",
    "| | Lần 1 | Lần 2 | Lần 3 | Lần 4 | Lần 5 |",
    "| $s_1$ | | | | | |",
    "| $s_2$ | | | | | |",
    "| $s_3$ | | | | | |",
    "| $s_4$ | | | | | |",
    "| $s_5$ | | | | | |",
    "$\\overline{g} = ...$; $\\Delta g = ...$; $g = ...$",
    "",
    "**Hoạt động:** Nhận xét và đánh giá kết quả thí nghiệm",
    "1. Hãy tính giá trị trung bình và sai số tuyệt đối của phép đo gia tốc rơi tự do.",
    "2. Tại sao lại dùng trụ thép làm vật rơi trong thí nghiệm? Có thể dùng viên bi thép được không? Giải thích tại sao.",
    "3. Vẽ đồ thị mô tả mối quan hệ s và $t^2$ trên hệ toạ độ (s – $t^2$).",
    "4. Nhận xét chung về dạng của đồ thị mô tả mối quan hệ s và $t^2$ rồi rút ra kết luận về tính chất của chuyển động rơi tự do.",
    "5. Hãy đề xuất một phương án thí nghiệm khác để đo gia tốc rơi tự do của trụ thép.",
    "",
    "**EM ĐÃ HỌC**",
    "- Rơi tự do là chuyển động thẳng nhanh dần đều nên có thể xác định gia tốc rơi tự do theo công thức xác định gia tốc của chuyển động nhanh dần đều.",
    "- Sử dụng đồng hồ đo thời gian hiện số và cổng quang đo gia tốc rơi tự do của viên bi thép hoặc trụ thép.",
    "",
    "**EM CÓ THỂ**",
    "Sử dụng camera của điện thoại thông minh và phần mềm phân tích video để xác định được gia tốc rơi tự do của vật (Hình 11.2).",
    "[Hình 11.2. Bố trí đo gia tốc rơi tự do bằng camera của điện thoại thông minh. Có thước đo, vật màu đỏ đang rơi, điện thoại ghi hình, đồ thị phân tích]",
    "",
    "**EM CÓ BIẾT?**",
    "Vào năm 1602, Galilei phát hiện ra chuyển động của con lắc và khoảng thời gian một chu kì tỉ lệ với căn bậc hai chiều dài con lắc. Nhờ phát hiện này có thể đo gia tốc rơi tự do bằng con lắc đơn.",
    "",
    "48"
  ]
}
