INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B12', 'Bài 12 CHUYỂN ĐỘNG NÉM', 50, 9, $JSON$
{
  "content": [
    "# Bài 12 CHUYỂN ĐỘNG NÉM",
    "",
    "**Khởi động:**",
    "*Nhảy xa là một ví dụ về chuyển động ném. Theo em, trong việc nhảy xa thì những yếu tố nào có tính quyết định đến thành tích nhảy của vận động viên?*",
    "[Hình ảnh mô phỏng các tư thế của một vận động viên nhảy xa từ lúc giậm nhảy đến lúc tiếp đất, tạo thành một quỹ đạo hình parabol]",
    "",
    "## I. CHUYỂN ĐỘNG NÉM NGANG",
    "**1. Khái niệm chuyển động ném ngang**",
    "Chuyển động ném ngang là chuyển động có vận tốc ban đầu theo phương nằm ngang và chuyển động dưới tác dụng của trọng lực.",
    "",
    "**2. Thí nghiệm**",
    "Thí nghiệm mô tả ở Hình 12.1 dùng để tìm hiểu chuyển động của vật bị ném theo phương nằm ngang.",
    "Dùng búa đập nhẹ vào thanh thép giữ bi B, thanh thép chuyển động thả bi B rơi tự do đồng thời đẩy bi A theo phương nằm ngang khỏi giá đỡ với vận tốc $v_0$.",
    "[Hình 12.1. Thí nghiệm về chuyển động ném ngang. Vật A ném ngang, vật B rơi tự do, búa đập nhả 2 viên bi]",
    "",
    "**? Câu hỏi:**",
    "Hai viên bi có chạm đất cùng một lúc không?",
    "",
    "Việc phân tích ảnh chụp hoạt nghiệm thí nghiệm trên (Hình 12.2) giúp ta so sánh chuyển động rơi tự do của bi B (sự thay đổi vị trí của bi B theo phương thẳng đứng) với vận tốc ban đầu $v_{0y} = 0$ với sự thay đổi vị trí theo phương thẳng đứng của viên bi A bị ném ngang với vận tốc ban đầu theo phương nằm ngang $v_{0x} = v_0$.",
    "[Hình 12.2. Ảnh chụp hoạt nghiệm chuyển động của hai viên bi A và B. Cho thấy vị trí theo phương thẳng đứng của cả 2 viên luôn ngang nhau tại cùng một thời điểm]",
    "",
    "**? Câu hỏi:**",
    "Hãy nhận xét về sự thay đổi vị trí theo phương thẳng đứng của hai viên bi sau những khoảng thời gian bằng nhau.",
    "",
    "49",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**3. Phân tích kết quả thí nghiệm**",
    "Đối với chuyển động ném ngang, người ta quan tâm tới thời gian từ khi vật được ném tới khi vật rơi chạm đất và tầm bay xa của vật theo phương nằm ngang. Để xác định các đại lượng này người ta phân tích chuyển động của vật bị ném ngang thành hai chuyển động thành phần: chuyển động thành phần theo phương thẳng đứng và chuyển động thành phần theo phương nằm ngang.",
    "Thí nghiệm trên cho thấy thành phần chuyển động theo phương thẳng đứng của viên bi A giống chuyển động rơi của viên bi B. Điều đó chứng tỏ thành phần chuyển động theo phương nằm ngang của viên bi A không ảnh hưởng đến thành phần chuyển động theo phương thẳng đứng của nó: Hai chuyển động thành phần này độc lập với nhau.",
    "",
    "**a) Thành phần chuyển động theo phương thẳng đứng**",
    "Nếu bỏ qua sức cản của không khí thì chuyển động thành phần theo phương thẳng đứng của vật là chuyển động rơi tự do với vận tốc ban đầu bằng 0.",
    "Nếu chọn chiều dương là chiều từ trên xuống và gọi H là độ cao của vật khi bị ném ngang thì:",
    "$H = \\frac{1}{2}.g.t^2 \\Rightarrow t = \\sqrt{\\frac{2.H}{g}}$ (12.1)",
    "Công thức (12.1) cho thấy:",
    "- Thời gian rơi của vật bị ném ngang chỉ phụ thuộc độ cao H của vật khi bị ném, không phụ thuộc vận tốc ném.",
    "- Nếu từ cùng một độ cao, đồng thời ném ngang các vật khác nhau với các vận tốc khác nhau thì chúng đều rơi xuống đất cùng một lúc.",
    "",
    "**b) Thành phần chuyển động theo phương nằm ngang**",
    "Nếu chọn chiều dương là chiều ném viên bi thì độ dịch chuyển trong chuyển động thành phần nằm ngang là:",
    "$d_x = v_x.t = v_0.t$.",
    "Giá trị cực đại của độ dịch chuyển trong chuyển động thành phần nằm ngang được gọi là tầm xa L của chuyển động ném ngang (Hình 12.4):",
    "$L = d_{x\\text{ max}} = v_0.t_{\\text{max}}$, với $t_{\\text{max}}$ là thời gian rơi của vật.",
    "Do đó: $L = v_0.\\sqrt{\\frac{2.H}{g}}$ (12.2)",
    "Công thức (12.2) cho thấy:",
    "1. Tầm xa của vật bị ném ngang phụ thuộc vào độ cao H của vật khi bị ném và vận tốc ném. Nếu từ cùng một độ cao đồng thời ném các vật khác nhau với vận tốc khác nhau thì vật nào có vận tốc ném lớn hơn sẽ có tầm xa lớn hơn.",
    "2. Nếu từ các độ cao khác nhau ném ngang các vật với cùng vận tốc thì vật nào được ném ở độ cao lớn hơn sẽ có tầm xa lớn hơn.",
    "",
    "[Hình 12.3. Phân tích chuyển động ném ngang. Quỹ đạo của vật M từ O, phân tích thành d_x theo trục Ox, d_y theo trục Oy]",
    "[Hình 12.4. Đồ thị chuyển động ném ngang. Quỹ đạo parabol từ (0,H) trên Oy xuống L trên Ox]",
    "",
    "**? Câu hỏi:**",
    "Hãy quan sát ảnh hoạt nghiệm ở Hình 12.2 để chứng tỏ chuyển động thành phần theo phương nằm ngang là chuyển động thẳng đều với vận tốc $v_x = v_0$.",
    "",
    "50",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**Hoạt động:**",
    "1. Hãy đề xuất phương án thí nghiệm để kiểm tra những kết luận 2 và 3.",
    "2. Dùng thước kẻ giữ ba viên bi (sắt, thuỷ tinh và gỗ) có cùng kích thước, trên một tấm thuỷ tinh đặt nghiêng trên mặt bàn rồi nâng thước lên (Hình 12.5). Hãy dự đoán tầm xa của ba viên bi và làm thí nghiệm kiểm tra.",
    "[Hình 12.5. Thí nghiệm về tầm xa]",
    "",
    "*Bài tập ví dụ:* Một người đứng từ một đài quan sát ven biển, ném một hòn đá theo phương nằm ngang hướng ra biển với vận tốc 12 m/s. Biết độ cao từ vị trí ném so với mặt biển là 40 m. Bỏ qua sức cản của không khí.",
    "a) Sau bao lâu thì hòn đá chạm mặt biển?",
    "b) Tầm xa L của hòn đá là bao nhiêu mét?",
    "*Giải*",
    "$v_{0y} = 0$",
    "$v_{0x} = v = 12$ m/s",
    "H = 40 m",
    "g = 9,8 m/s$^2$",
    "a) t = ?",
    "b) L = ?",
    "",
    "a) $H = d_y = \\frac{1}{2}.g.t^2$",
    "Do đó: $t = \\sqrt{\\frac{2.H}{g}} = 2,86$ s.",
    "b) $L = d_{x\\text{ max}} = v.t = 34,3$ m.",
    "",
    "**? Câu hỏi:**",
    "1. Nếu đồng thời ném hai quả bóng giống nhau với những vận tốc bằng nhau theo phương nằm ngang từ hai độ cao $h_1, h_2$ khác nhau ($h_1 < h_2$) thì:",
    "a) Quả bóng ném ở độ cao nào chạm đất trước?",
    "b) Quả bóng ném ở độ cao nào có tầm xa lớn hơn?",
    "2. Một máy bay chở hàng đang bay ngang ở độ cao 490 m với vận tốc 100 m/s thì thả một gói hàng cứu trợ xuống một làng đang bị lũ lụt. Lấy g = 9,8 m/s$^2$ và bỏ qua sức cản của không khí.",
    "a) Sau bao lâu thì gói hàng chạm đất?",
    "b) Tầm xa của gói hàng là bao nhiêu?",
    "c) Xác định vận tốc của gói hàng khi chạm đất.",
    "",
    "## II. CHUYỂN ĐỘNG NÉM XIÊN",
    "Khi đánh một quả bóng tennis lên cao theo phương xiên góc với phương nằm ngang, người ta thấy quả bóng bay lên rồi rơi xuống theo một quỹ đạo có dạng hình parabol (Hình 12.6). Chuyển động của quả bóng trong trường hợp này gọi là chuyển động của vật bị ném xiên, gọi tắt là chuyển động ném xiên.",
    "[Hình 12.6. Ảnh chụp hoạt nghiệm chuyển động ném xiên. Quỹ đạo parabol của quả bóng ném xiên lên rồi rơi xuống]",
    "",
    "**? Câu hỏi:**",
    "Hãy tìm thêm ví dụ về chuyển động ném xiên trong đời sống.",
    "",
    "51",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**1. Phân tích chuyển động ném xiên**",
    "Đối với chuyển động ném xiên, người ta cũng quan tâm đến thời gian từ khi vật được ném lên tới khi vật rơi chạm đất và tầm xa của vật theo phương nằm ngang. Để xác định các đại lượng này người ta cũng thực hiện như đã làm với chuyển động ném ngang, phân tích chuyển động ném xiên thành hai chuyển động thành phần: chuyển động thành phần theo phương thẳng đứng và chuyển động thành phần theo phương nằm ngang (Hình 12.7).",
    "[Hình 12.7. Phân tích chuyển động ném xiên. Hệ toạ độ Oxy, vận tốc $\\vec{v}_0$ hợp với Ox góc $\\alpha$, phân tích thành $\\vec{v}_{0x}$ và $\\vec{v}_{0y}$]",
    "",
    "**2. Công thức xác định tầm cao và tầm xa của chuyển động ném xiên**",
    "Bằng cách làm tương tự như cách làm đối với chuyển động ném ngang. Bỏ qua sức cản của không khí, có thể thiết lập được công thức xác định tầm cao và tầm xa của chuyển động ném xiên:",
    "Tầm cao: $H = d_{y\\text{ max}} = \\frac{v_0^2.\\sin^2\\alpha}{2.g}$",
    "Tầm xa: $L = d_{x\\text{ max}} = \\frac{v_0^2.\\sin 2\\alpha}{g}$",
    "",
    "*Bài tập ví dụ:* Một người nhảy xa với vận tốc ban đầu 7,5 m/s theo phương xiên $30^\\circ$ với phương nằm ngang. Biết vị trí dậm nhảy ngang với hố nhảy. Bỏ qua sức cản của không khí và lấy g = 9,8 m/s$^2$. Tính:",
    "a) Vận tốc ban đầu của người nhảy theo phương thẳng đứng và theo phương nằm ngang.",
    "b) Tầm cao H.",
    "c) Thời gian từ khi bắt đầu nhảy tới khi đạt tầm cao.",
    "d) Thời gian từ lúc bắt đầu nhảy lên tới lúc rơi xuống hố nhảy.",
    "e) Tầm xa L.",
    "[Hình 12.8. Hệ toạ độ Oxy cho bài tập vận dụng. O là vị trí trên mặt đất người đó đặt chân]",
    "*Giải*",
    "Chọn hệ toạ độ Oxy với O là vị trí trên mặt đất mà người đó đặt chân vào để nhảy lên, chiều dương là chiều từ dưới lên (Oy) và chiều từ trái sang phải (Ox), gốc thời gian là thời điểm nhảy (Hình 12.8).",
    "a) Vận tốc ban đầu:",
    "$v_{0y} = v_0.\\sin 30^\\circ = 3,75$ m/s (từ dưới lên)",
    "$v_{0x} = v_0.\\cos 30^\\circ = 6,50$ m/s (trái sang phải)",
    "b) Khi đạt tầm cao H thì vận tốc của người nhảy theo phương thẳng đứng bằng 0:",
    "$v_y = 0$",
    "$v_{0y} = 3,75$ m/s",
    "$a = - g$",
    "H = ?",
    "$v_y^2 - v_{0y}^2 = 2.a.H = -2.g.H$",
    "$H = \\frac{v_{0y}^2}{2.g} = 0,717$ m",
    "c) Thời gian từ lúc bắt đầu nhảy tới khi đạt tầm cao:",
    "$v_y = v_{0y} - g.t \\Rightarrow t = \\frac{3,75}{9,8} = 0,383$ s",
    "",
    "52",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "d) Thời gian từ lúc bắt đầu nhảy lên tới lúc rơi xuống hố nhảy:",
    "$t' = 2.t = 2.0,383 = 0,766$ s",
    "e) Tầm xa:",
    "$v_{0x} = 6,5$ m/s",
    "$t' = 0,766$ s",
    "L = ?",
    "$L = d_{x\\text{ max}} = v_{0x}.t' = 4,98$ m.",
    "",
    "**? Câu hỏi:**",
    "Người ta bắn một viên bi với vận tốc ban đầu 4 m/s hướng lên theo phương xiên $45^\\circ$ so với phương nằm ngang. Coi sức cản của không khí là không đáng kể.",
    "1. Tính vận tốc của viên bi theo phương nằm ngang và phương thẳng đứng tại các thời điểm: bắt đầu bắn, sau 0,1 s và sau 0,2 s.",
    "2. a) Viên bi đạt tầm cao H vào lúc nào?",
    "b) Tính tầm cao H.",
    "c) Gia tốc của viên bi ở tầm cao H có giá trị bằng bao nhiêu?",
    "3. a) Vận tốc của viên bi có độ lớn cực tiểu ở vị trí nào?",
    "b) Viên bi có vận tốc cực tiểu vào thời điểm nào?",
    "4. a) Khi nào viên bi chạm sàn?",
    "b) Xác định vận tốc của viên bi khi chạm sàn.",
    "c) Xác định tầm xa L của viên bi.",
    "",
    "**EM ĐÃ HỌC**",
    "- Chuyển động ném có thể phân tích thành hai chuyển động thành phần vuông góc với nhau: chuyển động với gia tốc theo phương thẳng đứng, chuyển động thẳng đều theo phương nằm ngang.",
    "- Các công thức của chuyển động ném:",
    "+ Ném ngang:",
    "Tầm xa: $L = v_0.t = v_0.\\sqrt{\\frac{2.H}{g}}$",
    "+ Ném xiên:",
    "Tầm cao: $H = \\frac{v_0^2.\\sin^2\\alpha}{2.g}$",
    "Tầm xa: $L = \\frac{v_0^2.\\sin 2\\alpha}{g}$",
    "Chú ý: Các công thức trên chỉ đúng khi lực cản của không khí không đáng kể.",
    "",
    "53",
    "CHƯƠNG II – ĐỘNG HỌC",
    "",
    "**EM CÓ THỂ**",
    "1. Sử dụng được các công thức của chuyển động ném ngang để giải thích cách thả hàng cứu trợ bằng máy bay.",
    "2. Vận dụng được kiến thức về chuyển động ném xiên để giải thích một số tình huống đơn giản trong cuộc sống. Ví dụ: thành tích nhảy xa của vận động viên phụ thuộc vào góc nhảy, việc điều chỉnh góc bắn để có tầm đạn bay xa nhất của các pháo thủ.",
    "",
    "## HOẠT ĐỘNG TRẢI NGHIỆM",
    "**I. Mục đích**",
    "Nghiên cứu tìm hiểu điều kiện để ném một vật đạt tầm bay xa lớn nhất.",
    "**II. Chuẩn bị**",
    "- Dụng cụ có thể dùng để bắn các viên bi nhỏ với những lực có độ lớn khác nhau, theo các phương khác nhau.",
    "- Thước đo độ dài, thước đo góc.",
    "- Địa điểm làm thí nghiệm có các độ cao khác nhau, đảm bảo an toàn tuyệt đối khi tiến hành thí nghiệm.",
    "**III. Các bước tiến hành**",
    "1. Tìm hiểu bằng lí thuyết",
    "Vận dụng những kiến thức đã học về chuyển động ném để dự đoán về:",
    "– Để ném ngang một vật đạt tầm bay xa lớn nhất thì phải chọn độ cao như thế nào?",
    "– Để ném xiên một vật đạt tầm bay xa lớn nhất thì phải chọn góc ném như thế nào?",
    "2. Lập phương án làm thí nghiệm kiểm tra dự đoán.",
    "3. Thực hiện thí nghiệm, rút ra kết luận.",
    "4. Viết báo cáo về kết quả tìm được.",
    "5. Trình bày báo cáo trước lớp.",
    "",
    "54"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B13', 'Bài 13 TỔNG HỢP VÀ PHÂN TÍCH LỰC. CÂN BẰNG LỰC', 57, 1, $JSON$
{
  "content": [
    "# Bài 13 TỔNG HỢP VÀ PHÂN TÍCH LỰC. CÂN BẰNG LỰC",
    "",
    "**Khởi động:**",
    "*Hai tàu kéo giống nhau dùng dây cáp để kéo một tàu chở hàng bị chết máy vào cảng bằng hai lực $\\vec{F}_1$ và $\\vec{F}_2$ như hình dưới đây.*",
    "*– Tàu chở hàng sẽ chuyển động theo hướng nào?*",
    "*– Làm thế nào để tính được độ lớn của lực kéo tác dụng lên tàu chở hàng?*",
    "[Hình ảnh 2 chiếc tàu kéo nhỏ kéo 1 chiếc tàu chở hàng lớn, tàu kéo 1 có lực $\\vec{F}_1$, tàu kéo 2 có lực $\\vec{F}_2$]",
    "",
    "## I. TỔNG HỢP LỰC – HỢP LỰC TÁC DỤNG",
    "*Tổng hợp lực* là phép thay thế các lực tác dụng đồng thời vào cùng một vật bằng một lực có tác dụng giống hệt như các lực ấy.",
    "Lực thay thế này gọi là *hợp lực*.",
    "Về mặt toán học, ta có thể tìm hợp lực bằng phép cộng vectơ:",
    "$\\vec{F} = \\vec{F}_1 + \\vec{F}_2 + \\vec{F}_3 + \\dots$ (13.1)",
    "",
    "**? Câu hỏi:**",
    "Tại sao lực đẩy của người bố trong Hình 13.1b có tác dụng như lực đẩy của hai anh em?",
    "a) Hai anh em đẩy thùng hàng, lực $\\vec{F}_1, \\vec{F}_2$, xe nhích lên với vận tốc $\\vec{v}$.",
    "b) Bố đẩy thùng hàng với lực $\\vec{F}$ lớn, xe nhích lên với vận tốc $\\vec{v}$. \"Thôi, hai con để bố đẩy tiếp cho!\"",
    "[Hình 13.1. Ví dụ về tổng hợp lực]",
    "",
    "56",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**1. Tổng hợp hai lực cùng phương**",
    "**? Câu hỏi:**",
    "1. Dựa vào Hình 13.2, hãy nêu cách xác định độ lớn và chiều của hợp lực trong hai trường hợp:",
    "a) Vật chịu tác dụng của hai lực cùng phương, cùng chiều (Hình 13.2a).",
    "b) Vật chịu tác dụng của hai lực cùng phương, ngược chiều (Hình 13.2b).",
    "2. Nêu quy tắc tổng hợp hai lực cùng phương.",
    "[Hình 13.2. Tổng hợp hai lực cùng phương.",
    "a) Hai lực $\\vec{F}_1$ (3N) và $\\vec{F}_2$ (2N) cùng chiều. Hợp lực $\\vec{F}$ (5N) bằng tổng hai lực.",
    "b) Hai lực $\\vec{F}_1$ (5N) và $\\vec{F}_2$ (3N) ngược chiều. Hợp lực $\\vec{F}$ (2N) cùng chiều với lực lớn hơn]",
    "",
    "**2. Tổng hợp hai lực đồng quy – Quy tắc hình bình hành**",
    "Từ các thí nghiệm và thực tế, người ta thấy rằng phép tổng hợp hai lực đồng quy tuân theo quy tắc hình bình hành sau đây (Hình 13.3):",
    "- Bước 1: Vẽ hai vectơ $\\vec{F}_1$ và $\\vec{F}_2$ đồng quy tại O.",
    "- Bước 2: Vẽ một hình bình hành có hai cạnh liền kề trùng với hai vectơ $\\vec{F}_1$ và $\\vec{F}_2$.",
    "- Bước 3: Vẽ đường chéo hình bình hành có cùng gốc O. Vectơ hợp lực $\\vec{F}$ trùng với đường chéo này.",
    "[Hình 13.3. Tổng hợp lực theo quy tắc hình bình hành. Hai vectơ $\\vec{F}_1$ và $\\vec{F}_2$ tạo thành hình bình hành, đường chéo là $\\vec{F} = \\vec{F}_1 + \\vec{F}_2$]",
    "",
    "**? Câu hỏi:**",
    "1. Cho hai lực đồng quy có độ lớn $F_1 = 6$ N và $F_2 = 8$ N.",
    "Nếu hợp lực có độ lớn F = 10 N thì góc giữa hai lực $\\vec{F}_1$ và $\\vec{F}_2$ bằng bao nhiêu? Vẽ hình minh hoạ.",
    "2. Giả sử lực kéo của mỗi tàu kéo ở đầu bài đều có độ lớn bằng 8000 N và góc giữa hai dây cáp bằng $30^\\circ$.",
    "a) Biểu diễn các lực kéo của mỗi tàu và hợp lực tác dụng vào tàu chở hàng.",
    "b) Tính độ lớn của hợp lực của hai lực kéo.",
    "c) Xác định phương và chiều của hợp lực.",
    "d) Nếu góc giữa hai dây cáp bằng $90^\\circ$ thì hợp lực của hai lực kéo có phương, chiều và độ lớn như thế nào?",
    "",
    "57",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "## II. CÁC LỰC CÂN BẰNG VÀ KHÔNG CÂN BẰNG",
    "**1. Các lực cân bằng**",
    "Xét trường hợp vật đứng yên dưới tác dụng của nhiều lực. Khi đó tổng hợp các lực tác dụng lên vật bằng 0. Ta nói các lực tác dụng lên vật là *các lực cân bằng* và vật ở trạng thái *cân bằng*.",
    "$\\vec{F} = \\vec{F}_1 + \\vec{F}_2 + \\vec{F}_3 + \\dots = \\vec{0}$ (13.2)",
    "[Hình 13.4. Hai lực $\\vec{F}_1$ và $\\vec{F}_2$ cân bằng nhau. $\\vec{F}_1$ và $\\vec{F}_2$ cùng độ lớn 3N, ngược chiều. $F = F_1 - F_2 = 0$]",
    "",
    "**? Câu hỏi:**",
    "Quan sát quyển sách đang nằm yên trên mặt bàn (Hình 13.5).",
    "a) Có những lực nào tác dụng lên quyển sách?",
    "b) Các lực này có cân bằng không? Vì sao?",
    "[Hình 13.5. Quyển sách nằm yên trên mặt bàn]",
    "",
    "**2. Các lực không cân bằng**",
    "Khi hợp lực của các lực khác 0 thì các lực này không cân bằng. Hợp lực hay lực không cân bằng này tác dụng vào một vật có thể làm thay đổi vận tốc của vật.",
    "",
    "**? Câu hỏi:**",
    "1. Một ô tô chịu một lực $F_1 = 400$ N hướng về phía trước và một lực $F_2 = 300$ N hướng về phía sau (Hình 13.6). Hỏi hợp lực tác dụng lên ô tô có độ lớn bằng bao nhiêu và hướng về phía nào?",
    "[Hình 13.6. Chiếc ô tô với $\\vec{F}_1$ hướng tới và $\\vec{F}_2$ hướng lui]",
    "2. Quan sát mỗi cặp tình huống ở Hình 13.7.",
    "a) Tình huống nào có hợp lực khác 0?",
    "b) Mô tả sự thay đổi vận tốc (độ lớn, hướng) của mỗi vật trong hình, nếu có.",
    "[Hình 13.7. Các tình huống:",
    "a) Bút chì nằm yên trên mặt bàn.",
    "b) Dùng tay đẩy để bút chì chuyển động nhanh dần.",
    "c) Quả bóng đang nằm yên ở gần mép bàn.",
    "d) Quả bóng vừa rơi khỏi mép bàn.]",
    "",
    "58",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "## III. PHÂN TÍCH LỰC",
    "Phân tích lực là phép thay thế một lực thành hai lực thành phần có tác dụng giống hệt như lực ấy.",
    "",
    "**1. Quy tắc**",
    "a) Thường người ta phân tích lực thành hai lực vuông góc với nhau để lực thành phần này không có tác dụng nào theo phương của lực thành phần kia.",
    "b) Phân tích lực là phép làm ngược lại với tổng hợp lực nhưng chỉ được áp dụng vào trường hợp riêng nêu ở trên. Hình 13.8 cho biết cách phân tích một lực $\\vec{F}$ theo hai trục.",
    "[Hình 13.8. Phân tích lực $\\vec{F}$ trên hệ trục Oxy thành $\\vec{F}_x$ và $\\vec{F}_y$ vuông góc]",
    "",
    "**2. Chú ý**",
    "Chỉ khi xác định được một lực có tác dụng theo hai phương vuông góc góc nào thì mới phân tích lực theo hai phương vuông góc đó.",
    "",
    "**3. Ví dụ**",
    "Xét một vật đang trượt trên một mặt phẳng nghiêng nhẵn (Hình 13.9). Trọng lực $\\vec{P}$ có tác dụng: một mặt nó ép vật vào mặt phẳng nghiêng, mặt khác nó kéo vật trượt theo mặt phẳng nghiêng xuống dưới. Vì thế ta phân tích trọng lực $\\vec{P}$ theo hai phương vuông góc như Hình 13.9.",
    "[Hình 13.9. Phân tích trọng lực $\\vec{P}$ trên mặt phẳng nghiêng thành $\\vec{P}_1$ (song song mặt phẳng) và $\\vec{P}_2$ (vuông góc mặt phẳng)]",
    "",
    "**? Câu hỏi:**",
    "Một vật được giữ yên trên một mặt phẳng nghiêng nhẵn bởi một lò xo (Hình 13.10).",
    "1. Có những lực nào tác dụng lên vật?",
    "2. Phân tích trọng lực tác dụng lên vật thành hai lực thành phần và nêu rõ tác dụng của hai lực này.",
    "[Hình 13.10. Vật được giữ trên mặt phẳng nghiêng góc $\\alpha$ bởi một lò xo]",
    "",
    "**EM ĐÃ HỌC**",
    "- Tổng hợp lực là phép thay thế các lực tác dụng đồng thời vào cùng một vật bằng một lực có tác dụng giống hệt như các lực ấy. Lực thay thế này gọi là hợp lực.",
    "- Tổng hợp hai lực cùng phương và đồng quy đều tuân theo quy tắc cộng véctơ.",
    "- Nếu các lực tác dụng lên một vật cân bằng nhau thì hợp lực tác dụng lên vật bằng 0.",
    "- Nếu các lực tác dụng lên một vật không cân bằng thì hợp lực tác dụng lên vật đó khác 0. Khi đó, vận tốc của vật thay đổi (độ lớn, hướng).",
    "- Phân tích lực là phép thay thế một lực bằng hai lực thành phần có tác dụng giống hệt lực đó.",
    "",
    "**EM CÓ THỂ**",
    "1. Vận dụng quy tắc hình bình hành để tìm hợp lực của hai lực đồng quy.",
    "2. Phân tích được một lực thành hai lực thành phần vuông góc.",
    "",
    "59"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B14', 'Bài 14 ĐỊNH LUẬT 1 NEWTON', 61, 2, $JSON$
{
  "content": [
    "# Bài 14 ĐỊNH LUẬT 1 NEWTON",
    "",
    "**Khởi động:**",
    "*Hình bên cho thấy một trong hai con tàu vũ trụ Voyager đang làm nhiệm vụ thăm dò các hành tinh nằm xa Trái Đất trong hệ Mặt Trời. Chúng được phóng lên từ Mũi Canaveral, Florida (Hoa Kì) vào năm 1977 và hiện nay cả hai con tàu đã ra khỏi hệ Mặt Trời, đang tiếp tục hoạt động và gửi thông tin về Trái Đất.",
    "Điều gì đã giúp cho tàu Voyager tiếp tục chuyển động rời xa Trái Đất, mặc dù thực tế không còn lực nào tác dụng lên chúng nữa?*",
    "[Hình ảnh con tàu vũ trụ Voyager trong không gian. Nguồn ảnh: NASA Voyager]",
    "",
    "## I. LỰC VÀ CHUYỂN ĐỘNG",
    "Lực có phải là nguyên nhân làm cho một vật chuyển động và duy trì chuyển động đó hay không?",
    "",
    "**? Câu hỏi:**",
    "Một quyển sách đang nằm yên trên mặt bàn. Ta phải đẩy nó thì nó mới dịch chuyển và khi ngừng đẩy thì nó dừng lại. Nếu em đặt mình vào thời của nhà khoa học Hy Lạp Aristotle (384 – 322 TCN), khi mà mọi người còn chưa biết đến ma sát, thì em sẽ trả lời câu hỏi nêu ra như thế nào?",
    "",
    "Galilei bố trí thí nghiệm như Hình 14.1, rồi thả hòn bi cho lăn xuống theo máng nghiêng 1. Ông nhận thấy hòn bi lăn ngược lên máng 2 đến một độ cao thấp hơn độ cao ban đầu.",
    "Khi hạ thấp độ nghiêng của máng 2, ông thấy hòn bi lăn trên máng 2 được một đoạn dài hơn. Ông cho rằng hòn bi không lăn được đến độ cao ban đầu là vì có ma sát. Ông tiên đoán rằng nếu không có ma sát và nếu máng nghiêng 2 nằm ngang thì hòn bi sẽ lăn mãi mãi với vận tốc không đổi.",
    "[Hình 14.1. Minh hoạ thí nghiệm của Galilei.",
    "a) Máng 2 nghiêng nhiều, bi lăn lên gần tới độ cao h.",
    "b) Máng 2 nghiêng ít, bi lăn lên xa hơn nhưng vẫn chưa tới h.",
    "c) Máng 2 nằm ngang, bi lăn mãi mãi trên máng ngang]",
    "",
    "60",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "## II. ĐỊNH LUẬT 1 NEWTON",
    "Năm 1687, nhà vật lí người Anh Newton đã khái quát kết quả nghiên cứu của mình, đồng thời phát triển các ý tưởng của Galilei thành một định luật chuyển động, sau này được gọi là định luật 1 Newton:",
    "*Nếu một vật không chịu tác dụng của lực nào hoặc chịu tác dụng của các lực có hợp lực bằng không, thì vật đang đứng yên sẽ tiếp tục đứng yên, đang chuyển động sẽ tiếp tục chuyển động thẳng đều.*",
    "",
    "**? Câu hỏi:**",
    "Quan sát các vật trong Hình 14.2.",
    "1. Giải thích tại sao quả cầu đứng yên.",
    "2. Tại sao người trượt ván có thể giữ nguyên vận tốc của mình?",
    "[Hình 14.2.",
    "a) Quả cầu đứng yên khi được treo vào một sợi dây.",
    "b) Người trượt ván chuyển động với vận tốc không đổi]",
    "",
    "## III. QUÁN TÍNH",
    "**1. Quán tính**",
    "Tính chất bảo toàn trạng thái đứng yên hay chuyển động của vật, gọi là *quán tính* của vật.",
    "- Do có quán tính mà mọi vật có xu hướng bảo toàn vận tốc cả về hướng và độ lớn.",
    "- Định luật 1 Newton còn được gọi là định luật quán tính.",
    "",
    "**Hoạt động:**",
    "Thí nghiệm Hình 14.3 giúp minh hoạ quán tính của vật.",
    "- *Chuẩn bị:* Một tấm ván dài khoảng 1 m làm mặt phẳng nghiêng, xe lăn, vật nhỏ đặt trên xe lăn, vật chắn (có thể dùng quyển sách dày) (Hình 14.3).",
    "[Hình 14.3. Xe lăn có chở vật màu xanh đang lăn xuống dốc, đụng sách dày chắn ngang]",
    "- *Tiến hành:*",
    "- Đặt các vật nhỏ lên xe lăn. Giữ các vật và xe đứng yên trên đỉnh mặt phẳng nghiêng.",
    "- Thả cho xe trượt xuống dốc, dọc theo mặt phẳng nghiêng.",
    "- Quan sát hiện tượng xảy ra đối với xe và các vật trên xe.",
    "- *Thảo luận:*",
    "1. Giải thích tại sao khi xe trượt xuống dốc và bị cản lại ở cuối dốc thì vật nhỏ bị văng về phía trước.",
    "2. Làm thế nào để giữ cho vật trên xe không bị văng đi?",
    "",
    "**? Câu hỏi:**",
    "1. Mô tả và giải thích điều gì xảy ra đối với một hành khách ngồi trong ô tô ở các tình huống sau:",
    "a) Xe đột ngột tăng tốc.",
    "b) Xe phanh gấp.",
    "c) Xe rẽ nhanh sang trái.",
    "2. Một vật đang chuyển động với vận tốc 3 m/s dưới tác dụng của các lực. Nếu bỗng nhiên các lực này mất đi thì:",
    "A. Vật dừng lại ngay.",
    "B. Vật đổi hướng chuyển động.",
    "C. Vật chuyển động chậm dần rồi dừng lại.",
    "D. Vật tiếp tục chuyển động theo hướng cũ với vận tốc 3 m/s.",
    "3. Một vật đang nằm yên trên mặt bàn nằm ngang. Tại sao ta có thể khẳng định rằng bàn đã tác dụng một lực lên nó?",
    "",
    "61",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**2. Ứng dụng của quán tính trong đời sống**",
    "**? Câu hỏi:**",
    "1. Khi ngồi trên ô tô, tàu lượn cao tốc hoặc máy bay, hành khách luôn được nhắc thắt dây an toàn. Giải thích điều này.",
    "2. Để tra đầu búa vào cán, nên chọn cách nào dưới đây? Giải thích tại sao.",
    "a) Đập mạnh cán búa xuống đất như Hình 14.4a.",
    "b) Đập mạnh đầu búa xuống đất như Hình 14.4b.",
    "[Hình 14.4. Hai cách tra đầu búa vào cán. a) Đập đuôi cán xuống. b) Đập đầu búa xuống]",
    "",
    "**EM ĐÃ HỌC**",
    "- Định luật 1 Newton: Nếu một vật không chịu tác dụng của lực nào hoặc chịu tác dụng của các lực có hợp lực bằng 0, thì vật đang đứng yên sẽ tiếp tục đứng yên, đang chuyển động sẽ tiếp tục chuyển động thẳng đều.",
    "- Quán tính của vật là tính chất bảo toàn trạng thái đứng yên hay chuyển động.",
    "",
    "**EM CÓ THỂ**",
    "1. Dùng khái niệm quán tính để giải thích hiện tượng trong Hình 14.5: Khi dùng tay kéo từ từ tờ giấy và khi giật mạnh tờ giấy.",
    "[Hình 14.5. Một cốc nước đặt trên tờ giấy trên mặt bàn]",
    "2. Giải thích được nguyên nhân của nhiều vụ tai nạn giao thông liên quan đến quán tính. Chuẩn bị một bài thuyết trình (dài khoảng 15 phút) về đề tài sau đây: Rất nhiều vụ tai nạn giao thông có nguyên nhân từ quán tính. Em hãy nêu một số ví dụ về điều đó và cách phòng tránh những tai nạn này.",
    "",
    "62"
  ]
}
