INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B15', 'Bài 15 ĐỊNH LUẬT 2 NEWTON', 64, 3, $JSON$
{
  "content": [
    "# Bài 15 ĐỊNH LUẬT 2 NEWTON",
    "",
    "**Khởi động:**",
    "*Đẩy một xe chở hàng cho nó chuyển động và nhận xét xem gia tốc của xe tăng hay giảm, nếu:*",
    "*a) Giữ nguyên lực đẩy nhưng khối lượng xe tăng lên (Hình a và b).*",
    "*b) Giữ nguyên khối lượng nhưng lực đẩy tăng lên (Hình b và c).*",
    "[Hình ảnh người đẩy xe.",
    "a) Đẩy xe trống.",
    "b) Đẩy xe có chất hàng.",
    "c) 2 người đẩy xe có chất hàng]",
    "",
    "## I. ĐỊNH LUẬT 2 NEWTON",
    "Từ những quan sát và thí nghiệm cho thấy gia tốc của một vật không chỉ phụ thuộc vào lực tác dụng mà còn phụ thuộc vào khối lượng của vật.",
    "Mối liên hệ giữa ba đại lượng: *gia tốc, lực và khối lượng* đã được Newton khái quát trong một phương trình véctơ đơn giản gọi là định luật 2 Newton:",
    "*Gia tốc của một vật cùng hướng với lực tác dụng lên vật. Độ lớn của gia tốc tỉ lệ thuận với độ lớn của lực và tỉ lệ nghịch với khối lượng của vật.*",
    "$\\vec{a} = \\frac{\\vec{F}}{m}$ (15.1)",
    "Xét về mặt Toán học, định luật 2 Newton có thể viết là:",
    "$\\vec{F} = m.\\vec{a}$",
    "Trong trường hợp vật chịu nhiều lực tác dụng $\\vec{F}_1, \\vec{F}_2, \\vec{F}_3, \\dots$ thì $\\vec{F}$ là hợp lực của các lực đó:",
    "$\\vec{F} = \\vec{F}_1 + \\vec{F}_2 + \\vec{F}_3 + \\dots$",
    "",
    "**EM CÓ BIẾT?**",
    "Dựa vào biểu thức $\\vec{F} = m.\\vec{a}$, ta có mối liên hệ:",
    "1 N = 1kg . 1m/s$^2$",
    "1 N là độ lớn của lực gây ra gia tốc 1 m/s$^2$ cho vật khối lượng 1 kg, theo hướng của lực.",
    "| Đại lượng | Kí hiệu | Đơn vị |",
    "|---|---|---|",
    "| Gia tốc | a | m/s$^2$ |",
    "| Khối lượng | m | kg |",
    "| Lực | F | N |",
    "",
    "## II. KHỐI LƯỢNG VÀ QUÁN TÍNH",
    "Lúc đầu, khối lượng chỉ được hiểu là một đại lượng dùng để chỉ lượng của chất chứa trong vật. Nhưng định luật 2 Newton còn cho ta một cách hiểu mới về khối lượng.",
    "Thật vậy, theo định luật 2 Newton, nếu có nhiều vật khác nhau lần lượt chịu tác dụng của cùng một lực không đổi, thì vật nào có khối lượng lớn hơn sẽ có gia tốc nhỏ hơn. Vậy, vật nào có khối lượng càng lớn thì càng khó thay đổi vận tốc, tức là càng có *mức quán tính lớn hơn*. Từ đó ta có thể nói: *Khối lượng của vật là đại lượng đặc trưng cho mức quán tính của vật.*",
    "",
    "**! Chú ý:**",
    "- Khối lượng trong định luật 2 Newton còn được gọi là khối lượng quán tính.",
    "- Khối lượng là đại lượng vô hướng, dương, không đổi với mỗi vật và có tính chất cộng được.",
    "",
    "63",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "Điều đó cho phép ta so sánh được khối lượng của những vật làm bằng các chất khác nhau. Một xe chở cát và một xe chở gạo được coi là có khối lượng bằng nhau nếu dưới tác dụng của hợp lực như nhau, chúng có gia tốc như nhau.",
    "",
    "## III. THÍ NGHIỆM MINH HOẠ ĐỊNH LUẬT 2 NEWTON",
    "",
    "**Hoạt động:** Thí nghiệm được thiết lập như Hình 15.2.",
    "*Dụng cụ:*",
    "- Một xe trượt có khối lượng M = 200 g được buộc vào một sợi dây vắt qua rãnh của ròng rọc. Coi dây không dãn và có khối lượng không đáng kể.",
    "- Một hộp đựng 10 quả nặng giống nhau, có cùng khối lượng m = 50 g.",
    "- Một máng trượt đệm khí với các lỗ nhỏ thổi không khí (nhằm giảm tối đa ma sát khi xe di chuyển trên máng trượt).",
    "- Bộ đếm thời gian gồm: một đồng hồ điện tử, hai cổng quang (đặt cách nhau 0,5 m) và tấm chắn sáng dài 10 cm.",
    "- Vật ở thí nghiệm này phải được hiểu là hệ vật gồm xe trượt và các quả nặng. Như vậy khối lượng của vật có thể là (M + m), (M + 2.m),... còn lực kéo F là trọng lượng của các quả nặng, cụ thể là $F_1 = m.g, F_2 = 2.m.g,...$",
    "",
    "**? Câu hỏi:**",
    "1. Nêu một số ví dụ cho thấy khối lượng của vật càng lớn thì mức quán tính của vật càng lớn. Điều này có ý nghĩa gì trong thực tiễn?",
    "2. Cho đồ thị biểu diễn mối liên hệ giữa các lực tác dụng lên một vật và gia tốc gây ra tương ứng (Hình 15.1). Khối lượng của vật là",
    "A. 1,0 kg. B. 2,0 kg.",
    "C. 0,5 kg. D. 1,5 kg.",
    "[Hình 15.1. Đồ thị F-a. Trục tung F(N) từ 0 đến 2.0. Trục hoành a(m/s^2) từ 0 đến 4.0. Đường thẳng đi qua (2.0, 1.0) và (4.0, 2.0). Độ dốc m = F/a = 1.0/2.0 = 0.5 kg]",
    "",
    "[Hình 15.2. Thí nghiệm minh hoạ định luật 2 Newton. Gồm Máng trượt đệm khí (2), tấm chắn sáng (1), 2 cổng quang điện (3,4), ròng rọc (5), các quả nặng (6), đồng hồ đo thời gian hiện số (7), cân điện tử (8), bơm khí (9)]",
    "*Hình 15.2. Thí nghiệm minh hoạ định luật 2 Newton*",
    "(1) Tấm chắn sáng;",
    "(2) Máng trượt đệm khí;",
    "(3) Cổng quang điện 1;",
    "(4) Cổng quang điện 2;",
    "(5) Ròng rọc;",
    "(6) Các quả nặng;",
    "(7) Đồng hồ đo thời gian hiện số;",
    "(8) Cân điện tử;",
    "(9) Bơm khí.",
    "",
    "64",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "*Tiến hành:*",
    "Bước 1: Lực kéo F có độ lớn tăng dần 1 N, 2 N và 3 N (bằng cách móc thêm các quả nặng vào đầu dây vắt qua ròng rọc).",
    "Bước 2: Ghi vào Bảng 15.1 độ lớn lực kéo F và tổng khối lượng của hệ (gồm xe trượt và các quả nặng đặt vào xe), ứng với mỗi lần thí nghiệm.",
    "Bước 3: Đo thời gian chuyển động t của xe; đồng hồ bắt đầu đếm từ lúc tấm chắn sáng đi qua cổng quang điện 1 và kết thúc đếm khi tấm chắn vượt qua cổng quang điện 2.",
    "Bước 4: Gia tốc a được tính từ công thức: $s = v_0.t + \\frac{1}{2}.a.t^2$ (đặt xe trượt có gắn tấm chắn sáng sao cho tấm chắn này sát với cổng quang điện 1 để $v_0 = 0$; s = 0,5 m là khoảng cách giữa hai cổng quang điện trong thí nghiệm). Đo thời gian t ứng với mỗi lần thí nghiệm, ta tính được:",
    "$a = \\frac{2.s}{t^2} = \\frac{2.0,5}{t^2} = \\frac{1}{t^2}$ (m/s$^2$). Ghi giá trị của gia tốc a vào Bảng 15.1.",
    "",
    "Kết quả thí nghiệm ghi trong Bảng 15.1.",
    "**Bảng 15.1.** Bảng ghi kết quả thí nghiệm",
    "| Lực kéo F (N) | 1 | 1 | 1 | 2 | 3 |",
    "|---|---|---|---|---|---|",
    "| Khối lượng (M + m) (kg) | 0,3 | 0,4 | 0,5 | 0,5 | 0,5 |",
    "| Thời gian t (s) | 0,55 | 0,64 | 0,71 | 0,50 | 0,42 |",
    "| Gia tốc $a = \\frac{2.s}{t^2}$ (m/s$^2$) | 3,31 | 2,44 | 1,99 | 4,03 | 5,67 |",
    "",
    "*Thảo luận:*",
    "a) Dựa vào số liệu trong Bảng 15.1, hãy vẽ đồ thị chỉ sự phụ thuộc của gia tốc a:",
    "– Vào F (ứng với m + M = 0,5 kg), (Hình 15.3a). Đồ thị có phải là đường thẳng không? Tại sao?",
    "– Vào $\\frac{1}{m + M}$ (ứng với F = 1 N), (Hình 15.3b). Đồ thị có phải là đường thẳng không? Tại sao?",
    "b) Nêu kết luận về sự phụ thuộc của gia tốc vào độ lớn của lực tác dụng và khối lượng của vật.",
    "",
    "[Hình 15.3.",
    "a) Hệ trục a(m/s^2) theo F(N) với m+M = 0,5kg",
    "b) Hệ trục a(m/s^2) theo 1/(m+M) (1/kg) với F = 1N]",
    "",
    "65",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**! Chú ý:**",
    "– Khi thực hiện đo gia tốc theo phương án thí nghiệm trên cần lưu ý: Để đồng hồ bắt đầu đếm thời gian khi xe có vận tốc ban đầu bằng 0, cần đặt tấm chắn sáng sát cổng quang điện 1.",
    "– Có thể xác định gia tốc theo công thức $a = \\frac{v_2^2 - v_1^2}{2.s}$, trong đó $v_1, v_2$ lần lượt là vận tốc tức thời qua hai cổng quang điện; $v_1, v_2$ được đo bằng cách thay tấm chắn sáng có chiều dài $\\ell = 1$ cm và đặt đồng hồ đo thời gian ở chế độ đo thời gian chắn cổng quang điện.",
    "",
    "**? Câu hỏi:**",
    "1. Trong các cách viết hệ thức của định luật 2 Newton sau đây, cách viết nào đúng?",
    "A. $\\vec{F} = m.a$",
    "B. $\\vec{F} = -m.\\vec{a}$",
    "C. $F = m.\\vec{a}$",
    "D. $-\\vec{F} = m.\\vec{a}$",
    "2. Một quả bóng khối lượng 0,50 kg đang nằm yên trên mặt đất. Một cầu thủ đá bóng với một lực 250 N. Thời gian chân tác dụng vào bóng là 0,02 s. Quả bóng bay đi với tốc độ:",
    "A. 0,01 m/s.",
    "B. 0,10 m/s.",
    "C. 2,50 m/s.",
    "D. 10,00 m/s.",
    "3. Dưới tác dụng của hợp lực 20 N, một chiếc xe đồ chơi chuyển động với gia tốc 0,4 m/s$^2$. Dưới tác dụng của hợp lực 50 N, chiếc xe sẽ chuyển động với gia tốc bao nhiêu?",
    "4. Tại sao máy bay khối lượng càng lớn thì đường băng phải càng dài?",
    "",
    "**EM ĐÃ HỌC**",
    "- Định luật 2 Newton: Gia tốc của một vật cùng hướng với lực tác dụng lên vật. Độ lớn của gia tốc tỉ lệ thuận với độ lớn của lực và tỉ lệ nghịch với khối lượng của vật.",
    "$\\vec{a} = \\frac{\\vec{F}}{m}$",
    "Xét về mặt Toán học, định luật 2 Newton có thể viết là $\\vec{F} = m.\\vec{a}$.",
    "- Khối lượng là đại lượng đặc trưng cho mức quán tính của vật.",
    "",
    "**EM CÓ THỂ**",
    "1. Đề xuất được một thí nghiệm chứng tỏ gia tốc mà vật thu được phụ thuộc vào:",
    "a) Độ lớn của lực tác dụng vào vật.",
    "b) Khối lượng của vật.",
    "2. Giải thích được khối lượng của vật càng lớn thì quán tính của vật càng lớn.",
    "3. Giải thích tại sao trong tham gia giao thông, khi ô tô chở hàng nặng khó hãm phanh hơn khi ô tô không chở hàng.",
    "",
    "66"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B16', 'Bài 16 ĐỊNH LUẬT 3 NEWTON', 68, 4, $JSON$
{
  "content": [
    "# Bài 16 ĐỊNH LUẬT 3 NEWTON",
    "",
    "**Khởi động:**",
    "*Móc hai lực kế vào nhau rồi kéo một trong hai lực kế như hình sau.*",
    "*a) Dự đoán xem số chỉ của hai lực kế giống nhau hay khác nhau.*",
    "*b) Hãy kiểm tra kết quả và nêu kết luận.*",
    "*c) Nếu cả hai tiếp tục kéo về hai phía ngược nhau với độ lớn lực tăng lên thì số chỉ của hai lực kế sẽ thay đổi thế nào?*",
    "[Hình ảnh 2 lực kế móc vào nhau và kéo về 2 phía]",
    "",
    "## I. ĐỊNH LUẬT 3 NEWTON",
    "**1. Lực tương tác giữa hai vật**",
    "**Hoạt động:** Quan sát thí nghiệm được mô tả trong Hình 16.1.",
    "1. Một thanh sắt và một thanh nam châm được treo như Hình 16.1a. Trong thí nghiệm này, lực nào làm cho thanh nam châm dịch chuyển lại gần thanh sắt?",
    "2. Xe lăn 1 có khối lượng $m_1$ và có gắn một lò xo nhẹ. Xe lăn 2 có khối lượng $m_2$. Ta cho hai xe áp lại gần nhau bằng cách buộc dây để nén lò xo (Hình 16.1b). Quan sát hiện tượng xảy ra khi đốt sợi dây buộc. Thảo luận để làm sáng tỏ ý kiến sau: *Lực không tồn tại riêng lẻ. Các lực hút hoặc đẩy luôn xuất hiện thành từng cặp giữa hai vật.*",
    "[Hình 16.1. Thí nghiệm về sự tương tác giữa các vật.",
    "a) Thanh sắt và thanh nam châm treo trên 2 sợi dây hút nhau.",
    "b) Xe lăn 1 có lò xo bị nén áp vào xe lăn 2 bằng sợi dây. Khi đốt dây, 2 xe đẩy nhau ra]",
    "",
    "**2. Định luật 3 Newton**",
    "Trong mọi trường hợp, khi vật A tác dụng lên vật B một lực thì vật B cũng tác dụng trở lại vật A một lực. Hai lực này là hai lực trực đối (Hình 16.2).",
    "$\\vec{F}_{AB} = -\\vec{F}_{BA}$",
    "Hai lực trực đối là hai lực tác dụng theo cùng một đường thẳng, ngược chiều nhau, có độ lớn bằng nhau và điểm đặt lên hai vật khác nhau.",
    "[Hình 16.2. Cặp lực và phản lực.",
    "a) 2 vật A, B hút nhau: $\\vec{F}_{BA}$ đặt trên A hướng về B, $\\vec{F}_{AB}$ đặt trên B hướng về A.",
    "b) 2 vật A, B đẩy nhau: $\\vec{F}_{BA}$ đặt trên A hướng ra xa B, $\\vec{F}_{AB}$ đặt trên B hướng ra xa A]",
    "",
    "## II. CÁC ĐẶC ĐIỂM CỦA LỰC VÀ PHẢN LỰC",
    "Theo định luật 3 Newton, trong tương tác giữa hai vật, một lực gọi là lực tác dụng còn lực kia gọi là phản lực.",
    "",
    "**? Câu hỏi:**",
    "1. Cặp lực và phản lực có những đặc điểm gì?",
    "2. Cặp lực và phản lực có phải là hai lực cân bằng hay không? Tại sao?",
    "",
    "**? Câu hỏi:**",
    "Hãy chỉ rõ điểm đặt của mỗi lực trong mỗi cặp lực ở Hình 16.2 a, b.",
    "",
    "67",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**? Câu hỏi:**",
    "1. Hãy chỉ ra các cặp lực và phản lực trong hai trường hợp sau:",
    "a) Quyển sách nằm yên trên mặt bàn (Hình 16.3a).",
    "b) Dùng búa đóng đinh vào gỗ (Hình 16.3b).",
    "2. Quyển sách nằm yên có phải là kết quả của sự cân bằng giữa lực và phản lực hay không?",
    "3. Lực do búa tác dụng vào đinh và phản lực của đinh lên búa có các đặc điểm gì?",
    "[Hình 16.3.",
    "a) Quyển sách trên bàn.",
    "b) Búa đóng đinh vào miếng gỗ]",
    "",
    "**Hoạt động:**",
    "1. Trong thí nghiệm ở phần mở đầu bài học, nếu cả hai người cùng kéo nhưng để lực kế di chuyển về phía một người (ví dụ cùng di chuyển hai lực kế sang phải) thì số chỉ của hai lực kế sẽ giống nhau hay khác nhau? Làm thí nghiệm kiểm tra dự đoán.",
    "2. Nêu thêm một số ví dụ trong thực tế và thảo luận để làm sáng tỏ các đặc điểm sau đây của lực và phản lực:",
    "- Lực và phản lực luôn xuất hiện thành từng cặp (xuất hiện hoặc mất đi đồng thời).",
    "- Lực và phản lực cùng tác dụng theo một đường thẳng, cùng độ lớn nhưng ngược chiều (hai lực như vậy là hai lực trực đối).",
    "- Lực và phản lực không cân bằng nhau (vì chúng đặt vào hai vật khác nhau).",
    "- Cặp lực và phản lực là hai lực cùng loại.",
    "",
    "**? Câu hỏi:**",
    "Một ô tô chuyển động trên mặt đường (Hình 16.4), nếu lực do ô tô tác dụng lên mặt đường có độ lớn bằng lực mà mặt đường đẩy ô tô thì tại sao chúng không “khử nhau”?",
    "[Hình 16.4. Xe ô tô màu xanh chạy trên đường, có $\\vec{F}$ hướng ra sau là lực do bánh xe đẩy đường và $\\vec{F}'$ hướng tới trước là lực đường đẩy bánh xe]",
    "",
    "**EM ĐÃ HỌC**",
    "Định luật 3 Newton: Trong mọi trường hợp, khi vật A tác dụng lên vật B một lực, thì vật B cũng tác dụng trở lại vật A một lực. Hai lực này tác dụng theo cùng một phương, cùng độ lớn, nhưng ngược chiều, điểm đặt lên hai vật khác nhau: $\\vec{F}_{AB} = -\\vec{F}_{BA}$.",
    "",
    "**EM CÓ THỂ**",
    "Giải thích tại sao các vận động viên khi bơi tới mép hồ bơi và quay lại thì dùng chân đẩy mạnh vào vách hồ bơi để di chuyển nhanh hơn.",
    "",
    "68"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B17', 'Bài 17 TRỌNG LỰC VÀ LỰC CĂNG', 70, 5, $JSON$
{
  "content": [
    "# Bài 17 TRỌNG LỰC VÀ LỰC CĂNG",
    "",
    "**Khởi động:**",
    "*Các tình huống ở hình dưới đây liên quan đến những loại lực nào?*",
    "[Hình ảnh các tình huống:",
    "a) Em bé thả diều.",
    "b) Em bé kéo hộp đồ chơi bằng dây.",
    "c) Hai người chèo thuyền trên mặt nước.",
    "d) Người chơi cầu lông đập quả cầu]",
    "",
    "## I. TRỌNG LỰC",
    "**Hoạt động:**",
    "Thảo luận tình huống được đề cập trong Hình 17.1: Tại sao khi được buông ra, các vật quanh ta đều rơi xuống đất?",
    "[Hình 17.1. Em bé buông quả bóng rơi xuống đất]",
    "",
    "**1. Trọng lực**",
    "Trọng lực là lực hấp dẫn do Trái Đất tác dụng lên vật gây ra cho vật gia tốc rơi tự do. Trọng lực được kí hiệu là vectơ $\\vec{P}$.",
    "– Ở gần Trái Đất trọng lực có:",
    "+ Phương thẳng đứng.",
    "+ Chiều từ trên xuống.",
    "+ Điểm đặt gọi là trọng tâm của vật.",
    "– Công thức của trọng lực",
    "Áp dụng định luật 2 Newton vào trường hợp vật rơi tự do, ta tìm được công thức của trọng lực: $\\vec{P} = m.\\vec{g}$",
    "",
    "**2. Trọng lượng**",
    "– Độ lớn của trọng lực tác dụng lên một vật gọi là trọng lượng của vật.",
    "– Công thức tính trọng lượng: $P = m.g$",
    "– Trọng lượng của một vật có thể đo bằng lực kế hoặc cân lò xo Hình 17.2.",
    "[Hình 17.2. Đo trọng lượng của vật bằng lực kế]",
    "",
    "**? Câu hỏi:**",
    "Lực kế trong Hình 17.2 đang chỉ ở vạch 1 N.",
    "a) Tính trọng lượng và khối lượng của vật bằng lực kế. Lấy g $\\approx$ 9,8 m/s$^2$.",
    "b) Biểu diễn các lực tác dụng lên vật (xem vật là chất điểm).",
    "",
    "69",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**3. Phân biệt trọng lượng và khối lượng**",
    "Trọng lượng của một vật thay đổi khi đem đến một nơi khác có gia tốc rơi tự do thay đổi.",
    "Khối lượng là số đo lượng chất của vật. Vì vậy, khối lượng của một vật không thay đổi khi ta chuyển nó từ nơi này đến nơi khác.",
    "",
    "**? Câu hỏi:**",
    "Đo trọng lượng của một vật ở một địa điểm trên Trái Đất có gia tốc rơi tự do là 9,80 m/s$^2$, ta được P = 9,80 N. Nếu đem vật này tới một địa điểm khác có gia tốc rơi tự do 9,78 m/s$^2$ thì khối lượng và trọng lượng của nó đo được là bao nhiêu?",
    "",
    "**Hoạt động:**",
    "Xác định trọng tâm của một vật phẳng, mỏng",
    "- *Chuẩn bị:* một số tấm bìa các-tông phẳng, mỏng; dây treo; thước thẳng; bút chì; kéo.",
    "- *Tiến hành:*",
    "*Thí nghiệm 1:* Hãy xác định trọng tâm của tấm bìa các-tông ở Hình 17.3 và giải thích rõ cách làm của em.",
    "*Thí nghiệm 2:* Cắt một số tấm bìa các-tông thành hình tròn, hình vuông, hình tam giác đều. Hãy tiến hành thí nghiệm để kiểm chứng kết luận sau:",
    "*\"Trọng tâm của các vật phẳng, mỏng và có dạng hình học đối xứng nằm ở tâm đối xứng của vật\"*.",
    "[Hình 17.3. Tấm bìa các tông treo bằng sợi dây]",
    "",
    "## II. LỰC CĂNG",
    "Khi dùng hai tay kéo dãn một sợi dây cao su, ta thấy dây cao su cũng kéo trở lại hai tay. Khi một sợi dây bị kéo thì ở tại mọi điểm trên dây, kể cả hai đầu dây xuất hiện lực để chống lại sự kéo (Hình 17.4), lực này gọi là *lực căng*, kí hiệu là $\\vec{T}$.",
    "[Hình 17.4. Lực căng dây xuất hiện khi tay kéo dây cao su hoặc treo vật nặng]",
    "",
    "**Hoạt động:**",
    "1. Dựa vào Hình 17.4, hãy thảo luận và phân tích để làm sáng tỏ các ý sau đây:",
    "- Những vật nào chịu lực căng của dây?",
    "- Lực căng có phương, chiều thế nào?",
    "Từ đó, nêu những đặc điểm (về phương, chiều, điểm đặt) của lực căng.",
    "2. Hãy chỉ ra điểm đặt, phương, chiều của lực căng trong Hình 17.5a và 17.5b.",
    "[Hình 17.5.",
    "a) Hai người kéo co bằng sợi dây thừng.",
    "b) Em bé dùng dây kéo đồ chơi trên xe trượt]",
    "",
    "70",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**? Câu hỏi:**",
    "1. Một bóng đèn có khối lượng 500 g được treo thẳng đứng vào trần nhà bằng một sợi dây và đang ở trạng thái cân bằng.",
    "a) Biểu diễn các lực tác dụng lên bóng đèn.",
    "b) Tính độ lớn của lực căng.",
    "c) Nếu dây treo chỉ chịu được một lực căng giới hạn 5,5 N thì nó có bị đứt không?",
    "2. Một con khỉ biểu diễn xiếc. Nó dùng tay nắm vào dây để đứng yên treo mình như Hình 17.7. Hãy cho biết trong hai lực căng xuất hiện trên dây ($\\vec{T}_1$ và $\\vec{T}_2$), lực nào có độ lớn lớn hơn. Tại sao?",
    "[Hình 17.7. Con khỉ đu dây. Dây bên trái tạo góc $14^\\circ$ với phương ngang, dây bên phải $20^\\circ$]",
    "",
    "**EM CÓ BIẾT?**",
    "- Mỗi sợi dây chỉ chịu được một lực căng giới hạn. Khi lực tác dụng lên dây vượt quá giá trị giới hạn này thì dây sẽ đứt.",
    "- Trong Hình 17.6, nếu khối lượng của ròng rọc và của dây đều rất nhỏ so với khối gỗ (có thể bỏ qua) thì lực căng ở các điểm trên dây có độ lớn bằng nhau.",
    "$T_1 = T_1' = T_2 = T_2'$",
    "[Hình 17.6. Hệ thống ròng rọc. Vật nặng trên bàn, ròng rọc ở mép bàn, lực kế kéo thẳng đứng xuống. $\\vec{T}_1, \\vec{T}_1'$ nằm ngang. $\\vec{T}_2, \\vec{T}_2'$ thẳng đứng]",
    "",
    "**EM ĐÃ HỌC**",
    "- Trọng lực được kí hiệu là vectơ $\\vec{P}$, có:",
    "– Phương thẳng đứng.",
    "– Chiều hướng về phía tâm Trái Đất.",
    "– Điểm đặt của trọng lực gọi là trọng tâm của vật.",
    "– Độ lớn: P = m.g.",
    "- Khi vật đứng yên trên Trái Đất, trọng lượng của vật bằng độ lớn của trọng lực tác dụng lên vật: P = m.g.",
    "- Lực căng do sợi dây tác dụng vào vật, có phương trùng với phương của sợi dây, có chiều ngược với chiều của lực do vật kéo dãn dây.",
    "",
    "**EM CÓ THỂ**",
    "1. Giải thích được trọng tâm của các vật phẳng, đồng chất, có dạng hình học đối xứng nằm ở tâm đối xứng của vật.",
    "2. Giải thích được tại sao các vệ tinh nhân tạo của Trái Đất cuối cùng đều rơi xuống Trái Đất.",
    "",
    "71"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B18', 'Bài 18 LỰC MA SÁT', 73, 6, $JSON$
{
  "content": [
    "# Bài 18 LỰC MA SÁT",
    "",
    "**Khởi động:**",
    "*Điều gì ngăn cản thùng hàng (Hình a), khiến nó không thể di chuyển? Tại sao lực đẩy tăng lên (Hình b) mà vẫn không làm cho thùng hàng di chuyển?*",
    "*Có cách nào làm thùng hàng di chuyển dễ dàng hơn không?*",
    "[Hình ảnh 2 người đẩy thùng hàng.",
    "a) Đẩy nhẹ, thùng hàng đứng im.",
    "b) Đẩy mạnh hơn, thùng hàng vẫn đứng im]",
    "",
    "## I. LỰC MA SÁT NGHỈ",
    "Lực ma sát nghỉ là lực ma sát tác dụng lên mặt tiếp xúc của vật, khi vật có xu hướng chuyển động nhưng chưa chuyển động (Hình 18.1).",
    "[Hình 18.1. Lực ma sát nghỉ $\\vec{F}_{\\text{ms nghỉ}}$ tác dụng lên vật, hợp lực bằng không ($\\vec{v} = 0$)]",
    "",
    "**? Câu hỏi:**",
    "1. Điều nào sau đây không đúng khi nói về lực ma sát nghỉ?",
    "A. Lực ma sát nghỉ luôn xuất hiện ở bề mặt tiếp xúc giữa hai vật.",
    "B. Lực ma sát nghỉ giữ cho các điểm tiếp xúc của vật không trượt trên bề mặt.",
    "C. Một vật có thể đứng yên trên mặt phẳng nghiêng mà không cần đến lực ma sát nghỉ.",
    "D. Một vật có thể đứng yên trên mặt phẳng ngang mà không cần đến lực ma sát nghỉ.",
    "2. Các tình huống sau đây liên quan đến loại lực ma sát nào?",
    "a) Xoa hai bàn tay vào nhau.",
    "b) Đặt vali lên một băng chuyền đang chuyển động ở sân bay.",
    "",
    "72",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**Hoạt động:**",
    "Quan sát Hình 18.2 và thảo luận các tình huống sau:",
    "Đặt trên bàn một vật nặng có dạng hình hộp.",
    "- Lúc đầu ta đẩy vật bằng một lực có cường độ nhỏ, vật không chuyển động (Hình 18.2a). Lực nào đã ngăn không cho vật chuyển động?",
    "- Tăng lực đẩy đến khi lớn hơn một giá trị $F_0$ nào đó (Hình 18.2b) thì vật bắt đầu trượt. Điều đó chứng tỏ gì?",
    "- Khi vật đã trượt, ta chỉ cần đẩy vật bằng một lực nhỏ hơn giá trị $F_0$ vẫn duy trì được chuyển động trượt của vật (Hình 18.2c). Điều đó chứng tỏ gì?",
    "[Hình 18.2.",
    "a) Vật đứng yên. Lực đẩy $\\vec{F}$ nhỏ.",
    "b) Vật bắt đầu chuyển động. Lực đẩy $\\vec{F}_0$ lớn hơn.",
    "c) Vật tiếp tục chuyển động. Lực đẩy $\\vec{F} < \\vec{F}_0$]",
    "",
    "## II. LỰC MA SÁT TRƯỢT",
    "Ở lớp 6 ta đã biết, lực ma sát trượt là lực ma sát cản trở vật trượt trên bề mặt tiếp xúc (Hình 18.3).",
    "[Hình 18.3. Lực ma sát trượt $\\vec{F}_{\\text{ms}}$. Vật có vận tốc $\\vec{v}$]",
    "Các thí nghiệm dưới đây sẽ giúp các em tìm hiểu thêm một số đặc điểm của lực ma sát trượt.",
    "",
    "**1. Đặc điểm của lực ma sát trượt**",
    "*Thí nghiệm 1: Kiểm chứng độ lớn của lực ma sát phụ thuộc vào vật liệu và tình trạng của bề mặt tiếp xúc, nhưng không phụ thuộc vào diện tích tiếp xúc.*",
    "*Chuẩn bị:* Lực kế (có GHĐ 1,0 N, ĐCNN 0,01 N), khối gỗ hình hộp chữ nhật, các bề mặt: gỗ, giấy.",
    "*Tiến hành:*",
    "1. Đặt mặt có diện tích lớn của khối gỗ lên bề mặt tiếp xúc.",
    "- Gắn lực kế vào giá thí nghiệm để cố định lực kế theo phương nằm ngang.",
    "- Móc khối gỗ vào lực kế, lần lượt kéo các mặt tiếp xúc (mặt gỗ, mặt tờ giấy) theo phương nằm ngang để chúng trượt đều dưới khối gỗ (Hình 18.4).",
    "- Ghi số chỉ của lực kế vào Bảng 18.1. Lấy giá trị trung bình của các số chỉ lực kế làm độ lớn của lực ma sát trượt.",
    "[Hình 18.4. Thí nghiệm đo lực ma sát.",
    "a) Trượt trên mặt gỗ.",
    "b) Trượt trên mặt giấy]",
    "2. Đặt mặt có diện tích nhỏ của khối gỗ lên bề mặt tiếp xúc và lặp lại thí nghiệm như trên.",
    "",
    "73",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**Bảng 18.1**",
    "| Bề mặt tiếp xúc | Lần 1 | Độ lớn lực ma sát trượt (N) | Lần 2 | Lần 3 | Trung bình |",
    "|---|---|---|---|---|---|",
    "| Mặt gỗ | | | | | |",
    "| Mặt giấy | | | | | |",
    "",
    "*Thảo luận và phân tích:*",
    "a) Nêu các lực tác dụng lên khối gỗ khi mặt tiếp xúc bên dưới nó được kéo trượt đều. Tại sao khi đó số chỉ của lực kế bằng độ lớn của lực ma sát trượt?",
    "b) Sắp xếp thứ tự theo mức tăng dần lực ma sát trên mỗi bề mặt.",
    "c) Điều gì xảy ra đối với độ lớn của lực ma sát trượt khi diện tích tiếp xúc thay đổi, khi vật liệu và tình trạng của bề mặt tiếp xúc thay đổi?",
    "",
    "*Thí nghiệm 2: Mối liên hệ giữa độ lớn của lực ma sát trượt với độ lớn của áp lực lên bề mặt tiếp xúc.*",
    "*Chuẩn bị:* Lực kế (có GHĐ 1,0 N, ĐCNN 0,01 N), ba khối gỗ hình hộp chữ nhật giống nhau, mặt tiếp xúc: gỗ.",
    "*Tiến hành:*",
    "- Đo trọng lượng của khối gỗ bằng lực kế. Ghi vào Bảng 18.2 (Áp lực của khối gỗ lên mặt tiếp xúc nằm ngang có độ lớn bằng trọng lượng của khối gỗ).",
    "- Gắn lực kế vào giá thí nghiệm để cố định lực kế theo phương nằm ngang.",
    "- Móc khối gỗ vào lực kế, kéo mặt tiếp xúc (mặt gỗ) theo phương nằm ngang để nó trượt đều dưới khối gỗ. Ghi lại số chỉ của lực kế trong 3 lần thí nghiệm vào Bảng 18.2. Lấy giá trị trung bình các kết quả đo.",
    "- Lần lượt đặt thêm 1, 2 khối gỗ lên khối gỗ đầu tiên và lặp lại bước 3.",
    "",
    "**Bảng 18.2**",
    "| Áp lực của các khối gỗ (N) | Lần 1 | Độ lớn lực ma sát trượt (N) | Lần 2 | Lần 3 | Trung bình |",
    "|---|---|---|---|---|---|",
    "| 1 khối gỗ: ... | | | | | |",
    "| 2 khối gỗ: ... | | | | | |",
    "| 3 khối gỗ: ... | | | | | |",
    "",
    "*Thảo luận và phân tích:*",
    "a) Điều gì xảy ra đối với độ lớn của lực ma sát trượt khi tăng áp lực lên bề mặt tiếp xúc?",
    "b) Vẽ đồ thị cho thấy sự thay đổi độ lớn của lực ma sát trượt khi tăng dần độ lớn của áp lực.",
    "c) Nêu kết luận về những đặc điểm của lực ma sát trượt.",
    "",
    "74",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**3. Công thức của lực ma sát trượt**",
    "**a) Hệ số ma sát trượt**",
    "Tỉ số giữa độ lớn của lực ma sát trượt $F_{\\text{ms}}$ và áp lực N gọi là hệ số ma sát trượt, kí hiệu là $\\mu$.",
    "Hệ số $\\mu$ phụ thuộc vào vật liệu và tình trạng của hai mặt tiếp xúc (xem Bảng 18.3).",
    "**Bảng 18.3.** Hệ số ma sát trượt (gần đúng) của một số cặp vật liệu",
    "| Cặp vật liệu tiếp xúc nhau | $\\mu$ |",
    "|---|---|",
    "| Gỗ trên gỗ (khô) | 0,20 |",
    "| Thép trên thép (khô) | 0,57 |",
    "| Thép trên thép (trơn) | 0,07 |",
    "| Cao su trên bê tông (khô) | 0,70 |",
    "| Cao su trên bê tông (ướt) | 0,50 |",
    "| Cao su trên băng | 0,10 |",
    "",
    "**b) Công thức tính lực ma sát trượt**",
    "$F_{\\text{ms}} = \\mu . N$",
    "",
    "**EM CÓ BIẾT?**",
    "Trong các điều kiện cùng áp lực N thì lực ma sát nghỉ tác dụng vào các vật lăn nhỏ hơn lực ma sát trượt tác dụng lên các vật trượt rất nhiều.",
    "",
    "## III. BÀI TẬP VÍ DỤ",
    "Một người đi xe đạp có khối lượng tổng cộng m = 86 kg đang chuyển động trên đường nằm ngang với vận tốc $v_0 = 4$ m/s. Nếu người đi xe ngừng đạp và hãm phanh để giữ không cho các bánh xe quay, xe trượt đi một đoạn đường 2 m thì dừng lại.",
    "1. Lực nào đã gây ra gia tốc cho xe? Tính độ lớn của lực này.",
    "2. Tính hệ số ma sát trượt giữa mặt đường và lốp xe? Lấy g = 10 m/s$^2$.",
    "*Giải*",
    "Khi tính lực và gia tốc, ta coi người + xe là chất điểm. Chọn chiều dương là chiều chuyển động của người và xe.",
    "1. Gia tốc của chuyển động được tính bằng công thức:",
    "$a = \\frac{v_t^2 - v_0^2}{2.s} = \\frac{0 - 16}{2.2} = -4$ m/s$^2$",
    "Lực gây ra gia tốc này là lực ma sát trượt của mặt đường tác dụng lên lốp xe:",
    "$F = m.a = 86.(-4) = -344$ N",
    "Dấu \"–\" chứng tỏ lực ma sát trượt ngược chiều chuyển động.",
    "2. Hệ số ma sát trượt giữa lốp xe với mặt đường được tính từ công thức:",
    "$F_{\\text{ms}} = \\mu . N \\Rightarrow \\mu = \\frac{F_{\\text{ms}}}{N}$, vì ô tô chuyển động trên đường nằm ngang nên N = P = m.g.",
    "$\\Rightarrow \\mu = \\frac{344}{86.10} = 0,4$.",
    "",
    "**? Câu hỏi:**",
    "1. Các lực tác dụng lên xe chở hàng được quy ước vẽ tại trọng tâm của xe (Hình 18.5):",
    "a) Các lực này có tên gọi là gì?",
    "b) Hãy chỉ ra các cặp lực cân bằng nhau.",
    "2. Để đẩy chiếc tủ, cần tác dụng một lực theo phương nằm ngang có giá trị tối thiểu 300 N để thắng lực ma sát nghỉ. Nếu người kéo tủ với lực 35 N và người kia đẩy tủ với lực 260 N, có thể làm dịch chuyển tủ được không? Biểu diễn các lực tác dụng lên tủ.",
    "[Hình 18.5. Xe chở hàng có 4 lực tác dụng từ trọng tâm: $\\vec{F}_C$ hướng lùi, $\\vec{F}_A$ hướng tới, $\\vec{F}_D$ hướng lên, $\\vec{F}_B$ hướng xuống]",
    "",
    "75",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "## IV. LỰC MA SÁT TRONG ĐỜI SỐNG",
    "**? Câu hỏi:**",
    "Nêu vai trò của lực ma sát trong các tình huống sau:",
    "a) Người di chuyển trên đường.",
    "b) Vận động viên thể dục dụng cụ xoa phấn vào lòng bàn tay trước khi nâng tạ.",
    "",
    "**Hoạt động:**",
    "1. Thảo luận để làm sáng tỏ những vấn đề sau đây:",
    "- Trong thực tế, có một số trường hợp lực ma sát có tác dụng cản trở chuyển động, nhưng cũng có trường hợp lực ma sát thúc đẩy chuyển động.",
    "- Vai trò của ma sát trong lĩnh vực thể thao.",
    "2. Nêu một số cách làm giảm ma sát trong kĩ thuật và trong đời sống.",
    "",
    "**EM ĐÃ HỌC**",
    "- Lực ma sát nghỉ và lực ma sát trượt đều là những lực tiếp xúc.",
    "- Lực ma sát nghỉ có giá trị cực đại $F_0$. Khi lực đẩy (hay kéo) vật $F > F_0$ thì vật bắt đầu trượt.",
    "- Công thức của lực ma sát trượt: $F_{\\text{ms}} = \\mu.N$",
    "Trong đó $\\mu$ là hệ số ma sát trượt, không có đơn vị;",
    "N là áp lực lên bề mặt.",
    "",
    "**EM CÓ BIẾT?**",
    "Trong đời sống và trong kĩ thuật, để giảm ma sát người ta thay vật trượt bằng vật lăn (hình cầu hoặc hình trụ) (Hình 18.6).",
    "[Hình 18.6. Con lăn hoặc ổ bi đặt xen giữa vào hai mặt tiếp xúc]",
    "",
    "**EM CÓ THỂ**",
    "Thuyết trình về ích lợi, tác hại của ma sát trong an toàn giao thông đường bộ.",
    "",
    "76"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B19', 'Bài 19 LỰC CẢN VÀ LỰC NÂNG', 78, 7, $JSON$
{
  "content": [
    "# Bài 19 LỰC CẢN VÀ LỰC NÂNG",
    "",
    "**Khởi động:**",
    "*Một hãng ô tô sử dụng cùng loại động cơ cho hai chiếc ô tô A và B có khối lượng như nhau. Khi cho hai ô tô này chạy thử nghiệm trên cùng quãng đường 100 km, với cùng tốc độ 72 km/h, các kĩ sư thấy rằng ô tô A tiêu thụ ít nhiên liệu hơn nhiều so với ô tô B.*",
    "*Tại sao lại có sự khác biệt như vậy?*",
    "[Hình ảnh 2 chiếc ô tô đang chạy. Ô tô A thon dài, ô tô B vuông vắn]",
    "",
    "## I. LỰC CẢN CỦA CHẤT LƯU",
    "**1. Lực cản**",
    "Thông thường thuật ngữ *chất lưu* được dùng để chỉ chất lỏng và chất khí.",
    "Mọi vật chuyển động trong chất lưu luôn chịu tác dụng bởi lực cản của chất lưu. Lực này ngược hướng chuyển động và cản trở chuyển động của vật (Hình 19.1).",
    "[Hình 19.1. Ví dụ về lực cản của chất lưu.",
    "a) Tên lửa bay lên, lực cản không khí hướng xuống.",
    "b) Người đi xe đạp hướng sang phải, lực cản không khí hướng trái.",
    "c) Nhảy dù, người rơi xuống, lực cản không khí hướng lên.",
    "d) Tàu thuỷ đang chạy sang phải, lực cản của nước hướng trái]",
    "",
    "**2. Lực cản phụ thuộc vào những yếu tố nào?**",
    "**Hoạt động:**",
    "a) Bằng cảm nhận trực giác, em thử đoán xem độ lớn của lực cản phụ thuộc vào những yếu tố nào?",
    "b) Em hãy tìm những thí nghiệm để chứng minh cho những dự đoán của em.",
    "",
    "**? Câu hỏi:**",
    "1. Trong hình ở phần mở đầu bài học, ô tô nào chịu lực cản nhỏ hơn?",
    "2. Nêu thêm một số ví dụ chứng tỏ lực cản của không khí liên quan đến hình dạng và tốc độ của vật.",
    "",
    "77",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**Hoạt động:**",
    "Quan sát Hình 19.2 và thảo luận để làm sáng tỏ về lực cản của nước phụ thuộc vào hình dạng của các vật chuyển động trong nước như thế nào.",
    "[Hình 19.2. Lực cản của nước đối với các vật chuyển động.",
    "a) Tàu cao tốc.",
    "b) Mô tô trên nước.",
    "c) Vận động viên bơi.",
    "d) Cá heo]",
    "",
    "Nhận xét: Lực cản của chất lưu (không khí, nước) phụ thuộc vào *hình dạng* và *tốc độ* của vật.",
    "",
    "## II. LỰC NÂNG CỦA CHẤT LƯU",
    "Khi vật chuyển động trong nước hay trong không khí thì ngoài lực cản (của không khí, của nước), vật còn chịu tác dụng của lực nâng.",
    "Hình 19.3 cho thấy, nếu cánh máy bay nghiêng đi một chút, chếch theo luồng gió, thì tăng thêm lực nâng tác dụng vuông góc với mặt dưới của cánh để nâng máy bay lên cao.",
    "[Hình 19.3. Các lực tác dụng lên máy bay. Trọng lực $\\vec{P}$ hướng xuống, lực nâng $\\vec{F}_n$ hướng lên, lực đẩy $\\vec{F}_d$ hướng tới trước, lực cản $\\vec{F}_c$ hướng ra sau]",
    "",
    "Sau đây là một số tình huống trong thực tiễn, cho thấy khi các vật ở trong chất lưu, chúng chịu tác dụng của lực nâng. Việc giải thích lực nâng tác dụng lên vật sẽ trình bày ở bài 35 của chương VII.",
    "Nhờ có lực nâng:",
    "– Máy bay có thể di chuyển trong không khí (Hình 19.3).",
    "– Tàu thuyền có thể nổi và di chuyển được trên mặt nước (Hình 19.4).",
    "– Khinh khí cầu lơ lửng trên không trung (Hình 19.5a).",
    "– Nhiều sinh vật bay lượn dễ dàng trong không khí (Hình 19.5b).",
    "[Hình 19.4. Tàu nổi trên mặt nước. Trọng lực $\\vec{P}$ hướng xuống, lực nâng $\\vec{F}_A$ hướng lên]",
    "",
    "**! Chú ý:** Khi vật rơi trong chất lưu dưới tác dụng của trọng lực và lực cản của chất lưu thì đến một lúc nào đó vật sẽ đạt tới vận tốc giới hạn và sẽ chuyển động đều với vận tốc này.",
    "",
    "**! Lực đẩy Archimedes**",
    "Lực đẩy Archimedes học ở môn Khoa học tự nhiên lớp 8 là trường hợp riêng của lực nâng vật đứng yên trong chất lưu.",
    "Công thức tính lực đẩy Archimedes:",
    "$F_A = \\rho . g . V$",
    "Trong đó:",
    "$F_A$: lực đẩy Archimedes (N).",
    "$\\rho$: khối lượng riêng của chất lỏng (kg/m$^3$).",
    "V: thể tích phần chất lỏng bị vật chiếm chỗ (m$^3$).",
    "",
    "78",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**? Câu hỏi:**",
    "1. Chuồn chuồn có thể bay lượn trong không trung. Tại sao chúng không bị rơi xuống đất do trọng lực (Hình 19.5b)?",
    "2. Biểu diễn các lực tác dụng lên một khí cầu đang lơ lửng trong không khí (Hình 19.5a).",
    "3. Hình 19.6 biểu diễn các véctơ lực tác dụng lên một máy bay đang bay ngang ở độ cao ổn định với tốc độ không đổi. Nếu khối lượng tổng cộng của máy bay là 500 tấn thì lực nâng có độ lớn bao nhiêu?",
    "4. Nêu những điểm khác biệt giữa lực cản và lực nâng.",
    "[Hình 19.5.",
    "a) Khinh khí cầu lơ lửng.",
    "b) Con chuồn chuồn đang bay]",
    "[Hình 19.6. Máy bay đang bay, có 4 lực tác dụng: Lực nâng của không khí, Trọng lực, Lực đẩy của động cơ, Lực cản của không khí]",
    "",
    "**EM ĐÃ HỌC**",
    "- Lực cản của chất lưu có tác dụng tương tự như lực ma sát, chúng làm chuyển động của các vật bị chậm lại. Lực cản phụ thuộc vào hình dạng và tốc độ của vật.",
    "- Lực nâng của chất lưu giúp khinh khí cầu lơ lửng trên không trung, máy bay di chuyển trong không khí, cho phép tàu thuyền di chuyển trên mặt nước,...",
    "",
    "**EM CÓ THỂ**",
    "1. Giải thích tại sao các phương tiện giao thông tốc độ cao lại cần có hình con thoi.",
    "2. Chỉ ra được lực nâng và lực cản khi máy bay hạ cánh hoặc cất cánh.",
    "",
    "**EM CÓ BIẾT?**",
    "**Hình dạng khí động học là gì?**",
    "Người đầu tiên khởi xướng mô hình khí động học trên ô tô là nhà thiết kế nổi tiếng Eduard Rumpler, cha đẻ của ngành hàng không Đức.",
    "Vào những năm 1930 – 1940, các cuộc đua ô tô bỗng nhiên trở thành “phong trào” rất được ưa chuộng. Các kĩ sư đã cố gắng sản xuất những chiếc xe chuyển động càng nhanh càng tốt. Tuy nhiên, tại đường đua Le Mans, ở nước Pháp năm 1937, chiếc ô tô có dung tích động cơ 1,7 lít đã gây sốc với hai chiến thắng ngoạn mục trước những ô tô có dung tích động cơ 2 lít. Bí quyết về sau được công bố: chiếc ô tô chiến thắng là nhờ cải tiến công nghệ và hình dạng sao cho lực cản nhỏ nhất.",
    "[Hình 19.7. Các nhà sản xuất ô tô thường xuyên nghiên cứu và cải tiến để xe có hình dạng khí động học sao cho lực cản nhỏ nhất]",
    "Từ đó đến nay, ngành công nghiệp ô tô đã tiến một bước rất dài. Hầu hết các kiểu xe ngày nay đều chú trọng đến biện pháp tối ưu hình dạng con thoi (trong khoa học gọi là hình khí động học) và điều đó đã giúp cho xe ít hao phí nhiên liệu hơn xưa.",
    "",
    "79"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B20', 'Bài 20 MỘT SỐ VÍ DỤ VỀ CÁCH GIẢI CÁC BÀI TOÁN THUỘC PHẦN ĐỘNG LỰC HỌC', 81, 8, $JSON$
{
  "content": [
    "# Bài 20 MỘT SỐ VÍ DỤ VỀ CÁCH GIẢI CÁC BÀI TOÁN THUỘC PHẦN ĐỘNG LỰC HỌC",
    "",
    "## I. CÁC BƯỚC GIẢI CHÍNH",
    "1. Chọn vật khảo sát chuyển động. Biểu diễn các lực tác dụng lên vật, trong đó làm rõ phương, chiều và điểm đặt của từng lực.",
    "2. Chọn hai trục vuông góc Ox và Oy; trong đó trục Ox cùng hướng với chuyển động của vật hay cùng hướng với lực kéo khi vật đứng yên. Phân tích các lực theo hai trục này. Áp dụng định luật 2 Newton theo hai trục toạ độ Ox và Oy.",
    "$\\begin{cases} Ox: F_x = F_{1x} + F_{2x} + \\dots = m.a_x & (1) \\\\ Oy: F_y = F_{1y} + F_{2y} + \\dots = 0 & (2) \\end{cases}$",
    "3. Giải hệ phương trình (1) và (2) để tìm gia tốc hay tìm lực, tuỳ từng bài toán.",
    "",
    "## II. CÁC LOẠI BÀI TOÁN",
    "**1. Bài toán xác định gia tốc của vật khi biết lực tác dụng vào vật**",
    "*Ví dụ.* Một người đẩy một thùng hàng, khối lượng 50 kg, trượt trên sàn nhà. Lực đẩy có phương nằm ngang với độ lớn là 180 N. Tính gia tốc của thùng hàng, biết hệ số ma sát trượt giữa thùng hàng và sàn nhà là 0,25. Lấy g = 9,8 m/s$^2$.",
    "*Giải*",
    "Thùng hàng chịu tác dụng của bốn lực: trọng lực $\\vec{P}$, lực đẩy $\\vec{F}$, phản lực $\\vec{N}$ và lực ma sát trượt $\\vec{F}_{\\text{ms}}$ của sàn (Hình 20.1a).",
    "[Hình 20.1.",
    "a) Biểu diễn các lực trên thùng hàng.",
    "b) Biểu diễn các lực trên chất điểm trong hệ toạ độ Oxy]",
    "Coi thùng hàng như một chất điểm (Hình 20.1b).",
    "Áp dụng định luật 2 Newton cho chuyển động của vật theo hai trục Ox, Oy:",
    "$\\begin{cases} Ox: F_x = F - F_{\\text{ms}} = m.a_x = m.a & (1) \\\\ Oy: F_y = N - P = 0 & (2) \\\\ F_{\\text{ms}} = \\mu.N & (3) \\end{cases}$",
    "",
    "Giải hệ phương trình:",
    "Từ (2) $\\Rightarrow N = P = m.g = 50.9,8 = 490$ N",
    "$F_{\\text{ms}} = \\mu.N = 0,25.490 = 122,5$ N",
    "$a = \\frac{F - F_{\\text{ms}}}{m} = \\frac{180 - 122,5}{50} = 1,15$ m/s$^2$.",
    "Thùng hàng trượt với gia tốc $a = 1,15$ m/s$^2$ cùng chiều với trục Ox.",
    "",
    "80",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "**2. Bài toán xác định lực tác dụng vào vật khi biết gia tốc**",
    "*Ví dụ 1.* Một người dùng dây buộc để kéo một thùng gỗ theo phương nằm ngang bằng một lực $\\vec{F}$ (Hình 20.2). Khối lượng của thùng là 35 kg. Hệ số ma sát giữa sàn và đáy thùng là 0,3. Lấy g = 9,8 m/s$^2$.",
    "[Hình 20.2. Người kéo thùng gỗ bằng dây theo phương ngang]",
    "Tính độ lớn của lực kéo trong hai trường hợp:",
    "a) Thùng trượt với gia tốc 0,2 m/s$^2$.",
    "b) Thùng trượt đều.",
    "*Giải*",
    "Thùng chịu tác dụng của bốn lực: trọng lực $\\vec{P} = m.\\vec{g}$, lực kéo $\\vec{F}$, phản lực $\\vec{N}$ và lực ma sát trượt $\\vec{F}_{\\text{ms}}$ của mặt sàn (Hình 20.3a).",
    "[Hình 20.3.",
    "a) Biểu diễn các lực trên thùng gỗ.",
    "b) Biểu diễn các lực trên chất điểm trong hệ toạ độ Oxy]",
    "",
    "Coi thùng như một chất điểm (Hình 20.3b) và áp dụng định luật 2 Newton cho các lực thành phần theo các phương Ox, Oy.",
    "$\\begin{cases} Ox: F_x = F - F_{\\text{ms}} = m.a_x = m.a & (1) \\\\ Oy: F_y = N - P = 0 & (2) \\\\ F_{\\text{ms}} = \\mu.N \\end{cases}$",
    "",
    "Giải hệ phương trình:",
    "Từ (2) $\\Rightarrow N = m.g$",
    "Suy ra: $F_{\\text{ms}} = \\mu.N = \\mu.m.g$",
    "Thay vào (1), ta được:",
    "$F = m.a + \\mu.m.g$",
    "$F = m(a + \\mu.g)$",
    "a) Thùng trượt với gia tốc a = 0,2 m/s$^2$",
    "$F = m(a + \\mu.g) = 35(0,2 + 0,3.9,8) = 109,9$ N.",
    "b) Thùng trượt đều (a = 0)",
    "$F = \\mu.m.g = 0,3.35.9,8 = 102,9$ N.",
    "",
    "81",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "*Ví dụ 2.* Một chiếc hộp gỗ được thả trượt không vận tốc ban đầu từ đầu trên của một tấm gỗ dài L = 2 m. Tấm gỗ đặt nghiêng $30^\\circ$ so với phương ngang. Hệ số ma sát giữa đáy hộp và mặt gỗ là 0,2. Lấy g = 9,8 m/s$^2$. Hỏi sau bao lâu thì hộp trượt xuống đến đầu dưới của tấm gỗ?",
    "*Giải*",
    "Hộp (coi là chất điểm) chịu tác dụng của ba lực: trọng lực $\\vec{P}$, phản lực $\\vec{N}$ và lực ma sát trượt $\\vec{F}_{\\text{ms}}$ (Hình 20.4a).",
    "[Hình 20.4.",
    "a) Biểu diễn các lực trên hộp gỗ trên mặt phẳng nghiêng.",
    "b) Biểu diễn và phân tích các lực trên hệ trục Oxy, Ox song song mặt phẳng nghiêng]",
    "Phân tích trọng lực $\\vec{P}$ thành hai lực thành phần $\\vec{P}_x, \\vec{P}_y$ (Hình 20.4b) và áp dụng định luật 2 Newton theo hai trục Ox, Oy:",
    "$\\begin{cases} Ox: F_x = m.g.\\sin\\alpha - F_{\\text{ms}} = m.a_x = m.a & (1) \\\\ Oy: F_y = N - m.g.\\cos\\alpha = 0 & (2) \\\\ F_{\\text{ms}} = \\mu.N \\end{cases}$",
    "",
    "Giải hệ phương trình: $a = g(\\sin\\alpha - \\mu\\cos\\alpha)$",
    "Thay số, ta được: $a = g(\\sin 30^\\circ - 0,2\\cos 30^\\circ) \\approx 3,2$ m/s$^2$",
    "Hộp trượt xuống với gia tốc $a = 0,64$ m/s$^2$ (! Lỗi sách in, số đúng là 3,2), cùng chiều với trục Ox.",
    "Áp dụng công thức:",
    "$L = \\frac{1}{2}at^2 \\Rightarrow t = \\sqrt{\\frac{2L}{a}} = \\sqrt{\\frac{2.2}{3,2}} \\approx 1,1$ s.",
    "",
    "## III. BÀI TẬP TỰ GIẢI",
    "1. Người ta đẩy một cái thùng có khối lượng 55 kg theo phương ngang với lực 220 N làm thùng chuyển động trên mặt phẳng ngang. Hệ số ma sát trượt giữa thùng và mặt phẳng là 0,35. Tính gia tốc của thùng. Lấy g = 9,8 m/s$^2$.",
    "2. Một quyển sách đặt trên mặt bàn nghiêng và được thả cho trượt xuống. Cho biết góc nghiêng $\\alpha = 30^\\circ$ so với phương ngang và hệ số ma sát giữa quyển sách và mặt bàn là $\\mu = 0,3$. Lấy g = 9,8 m/s$^2$. Tính gia tốc của quyển sách và quãng đường đi được của nó sau 2 s.",
    "3. Một học sinh dùng dây kéo một thùng sách nặng 10 kg chuyển động trên mặt sàn nằm ngang. Dây nghiêng một góc chếch lên trên $30^\\circ$ so với phương ngang. Hệ số ma sát trượt giữa đáy thùng và mặt sàn là $\\mu = 0,2$ (lấy g = 9,8 m/s$^2$). Hãy xác định độ lớn của lực kéo để thùng sách chuyển động thẳng đều.",
    "4. Hai vật có khối lượng lần lượt là $m_1 = 5$ kg và $m_2 = 10$ kg được nối với nhau bằng một sợi dây không dãn và được đặt trên một mặt sàn nằm ngang. Kéo vật 1 bằng một lực $\\vec{F}$ nằm ngang có độ lớn F = 45 N. Hệ số ma sát giữa mỗi vật và mặt sàn là $\\mu = 0,2$. Lấy g = 9,8 m/s$^2$. Tính gia tốc của mỗi vật và lực căng của dây nối.",
    "",
    "82"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B21', 'Bài 21 MOMENT LỰC. CÂN BẰNG CỦA VẬT RẮN', 84, 9, $JSON$
{
  "content": [
    "# Bài 21 MOMENT LỰC. CÂN BẰNG CỦA VẬT RẮN",
    "",
    "**Khởi động:**",
    "*Nếu dùng tay để siết chặt một đai ốc thì việc đó rất khó, tuy nhiên với dụng cụ thích hợp như cờ lê thì việc siết chặt đai ốc trở nên dễ dàng.*",
    "*Tác dụng của dụng cụ này thay đổi thế nào nếu ta tăng độ lớn của lực hoặc sử dụng cờ lê dài hơn?*",
    "[Hình ảnh dùng cờ lê vặn đai ốc]",
    "",
    "## I. MOMENT LỰC",
    "**1. Tác dụng làm quay của lực**",
    "Ở lớp 8 các em đã học trong môn KHTN về tác dụng làm quay của lực. Muốn mô tả chính xác tác dụng của búa khi dùng để nhổ đinh (Hình 21.1a), ta phải đưa vào khái niệm mới là *cánh tay đòn* của lực.",
    "Cánh tay đòn của lực là khoảng cách từ trục quay đến giá của lực, kí hiệu là d (Hình 21.1b).",
    "[Hình 21.1. Dùng búa nhổ đinh.",
    "a) Người cầm búa nhổ đinh.",
    "b) Biểu diễn lực $\\vec{F}$ và cánh tay đòn d từ trục quay O đến giá của lực]",
    "",
    "**? Câu hỏi:**",
    "1. Mô tả thao tác dùng búa để nhổ đinh.",
    "2. Lực $\\vec{F}$ nên đặt vào đâu trên cán búa để nhổ đinh được dễ dàng? Khi đó cánh tay đòn (d) của lực lớn hay nhỏ?",
    "3. Tác dụng làm quay của lực phụ thuộc những yếu tố nào?",
    "",
    "**2. Moment lực**",
    "Ví dụ trên cho phép ta lấy tích F.d làm đại lượng đặc trưng cho tác dụng làm quay của lực và gọi là *moment lực*, kí hiệu là M.",
    "*Moment lực đối với trục quay là đại lượng đặc trưng cho tác dụng làm quay của lực và được đo bằng tích của lực với cánh tay đòn của nó.*",
    "M = F.d",
    "Đơn vị của moment lực là niutơn mét (N.m).",
    "",
    "**? Câu hỏi:**",
    "Hình 21.2 mô tả một chiếc thước mảnh OA, đồng chất, dài 50 cm, có thể quay quanh trục quay cố định ở đầu O.",
    "1. Trong các tình huống ở Hình 21.2a, b, thước OA quay theo chiều kim đồng hồ hay ngược chiều kim đồng hồ?",
    "2. Tính moment lực ứng với mỗi tình huống trong Hình 21.2.",
    "[Hình 21.2. Thước OA quay quanh O.",
    "a) Lực 4N tác dụng ở điểm A thẳng đứng xuống dưới.",
    "b) Lực 2N tác dụng ở điểm A nghiêng góc $20^\\circ$ so với OA]",
    "",
    "83",
    "CHƯƠNG III – ĐỘNG LỰC HỌC",
    "",
    "## II. QUY TẮC MOMENT LỰC",
    "**1. Thí nghiệm**",
    "Dùng một đĩa tròn có trục quay đi qua tâm O, trên mặt đĩa có những lỗ dùng để treo những quả cân. Tác dụng vào đĩa những lực $\\vec{F}_1$ và $\\vec{F}_2$ nằm trong mặt phẳng của đĩa sao cho đĩa đứng yên (Hình 21.3). Khi đó moment của lực $\\vec{F}_1$ đã cân bằng với moment của lực $\\vec{F}_2$.",
    "Về độ lớn ta có: $F_1.d_1 = F_2.d_2$",
    "[Hình 21.3. Thí nghiệm về quy tắc moment lực với đĩa tròn quay quanh tâm]",
    "",
