    "**! Chú ý:**",
    "– Nên chọn số quả nặng hai bên không như nhau.",
    "– Vị trí A và B nên chọn trùng với các vạch chia của thước để tránh sai số khi đo.",
    "",
    "**4. Kết quả thí nghiệm**",
    "**Bảng 22.2.** Tổng hợp hai lực song song cùng chiều",
    "| Lần | $F_1$ (N) | $F_2$ (N) | AB | F | $OA_{tn}$ | $OA_{lt}$ |",
    "|---|---|---|---|---|---|---|",
    "| 1 | | | | | | |",
    "| 2 | | | | | | |",
    "| 3 | | | | | | |",
    "",
    "Xử lí kết quả thí nghiệm: $\\overline{OA}_{\\text{tn}} = \\dots; \\Delta\\overline{OA}_{\\text{tn}} = \\dots$",
    "",
    "**Hoạt động:** Nhận xét và đánh giá kết quả thí nghiệm",
    "1. So sánh các kết quả hợp lực tổng hợp thu được bằng tính toán và bằng thí nghiệm, rút ra kết luận.",
    "2. Em có thể đề xuất một phương án thí nghiệm khác để tiến hành thí nghiệm tổng hợp hai lực song song cùng chiều.",
    "",
    "**EM ĐÃ HỌC**",
    "- Tiến hành thí nghiệm tổng hợp hai lực đồng quy, hai lực song song để nghiệm lại các quy tắc tổng hợp lực.",
    "",
    "**EM CÓ THỂ**",
    "Chế tạo một chiếc cân thăng bằng đơn giản bằng các vật liệu dễ tìm (Hình 22.5):",
    "1. Một thanh thước gỗ có vạch chia.",
    "2. Một chai nước 500 mL.",
    "3. Các dây treo.",
    "4. Vật cần cân.",
    "[Hình 22.5. Thiết kế chế tạo chiếc cân đơn giản. Thanh gỗ (1) treo vật (4) và chai nước (2) qua các dây treo (3)]",
    "",
    "**EM CÓ BIẾT?**",
    "Đòn bẩy là loại máy cơ đơn giản được sử dụng nhiều trong đời sống để biến đổi lực tác dụng lên vật như sử dụng xà beng để nâng vật, đòn gánh để gánh các vật.",
    "",
    "89"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B23', 'Bài 23 NĂNG LƯỢNG. CÔNG CƠ HỌC', 92, 1, $JSON$
{
  "content": [
    "# Bài 23 NĂNG LƯỢNG. CÔNG CƠ HỌC",
    "",
    "**Khởi động:**",
    "[Hình ảnh vận động viên nâng tạ từ vị trí 1 đến vị trí 4]",
    "*Trong các động tác nâng tạ từ vị trí (1) sang vị trí (2), từ vị trí (2) sang vị trí (3), từ vị trí (3) sang vị trí (4) ở hình trên:*",
    "*- Có những quá trình truyền và chuyển hoá năng lượng nào?*",
    "*- Động tác nào có thực hiện công, không thực hiện công?*",
    "",
    "## I. NĂNG LƯỢNG",
    "Ở trường THCS các em đã biết:",
    "– Mọi hiện tượng xảy ra trong tự nhiên đều cần có năng lượng dưới các dạng khác nhau như: cơ năng, hoá năng, nhiệt năng, điện năng, năng lượng ánh sáng, năng lượng âm thanh, năng lượng nguyên tử.",
    "– Năng lượng có thể chuyển hoá từ dạng này sang dạng khác hoặc truyền từ vật này sang vật khác.",
    "– Năng lượng không tự sinh ra hoặc tự mất đi mà chỉ chuyển hoá từ dạng này sang dạng khác hoặc truyền từ vật này sang vật khác.",
    "",
    "**? Câu hỏi:**",
    "1. Khi đun nước bằng ấm điện thì có những quá trình truyền và chuyển hoá năng lượng nào xảy ra?",
    "2. Khi xoa hai tay vào nhau cho nóng thì có những quá trình truyền và chuyển hoá năng lượng nào xảy ra?",
    "3. Một quả bóng cao su được ném từ độ cao h xuống đất cứng và bị nảy lên. Sau mỗi lần nảy lên, độ cao giảm dần, nghĩa là cơ năng giảm dần. Điều đó có trái với định luật bảo toàn năng lượng không? Tại sao? Hãy dự đoán xem còn có hiện tượng gì nữa xảy ra với quả bóng ngoài hiện tượng bị nảy lên và rơi xuống.",
    "4. Có sự truyền và chuyển hoá năng lượng nào trong quá trình bắn pháo hoa?",
    "",
    "**EM CÓ BIẾT?**",
    "Có thể phân năng lượng thành hai loại là động năng (năng lượng của vật do chuyển động mà có) và thế năng (năng lượng lưu trữ của vật). Ví dụ, nhiệt năng là năng lượng chuyển động hỗn loạn của các phân tử; điện năng là năng lượng của chuyển động có hướng của các điện tích dưới tác dụng của điện trường; năng lượng vật có khi ở một độ cao so với mặt đất là thế năng trọng trường,...",
    "",
    "91",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "*Thí nghiệm của Joule về sự truyền, chuyển hoá và bảo toàn năng lượng*",
    "Thí nghiệm mang tính lịch sử được James Joule thực hiện vào những năm 1844 – 1854 nhằm minh hoạ định luật bảo toàn năng lượng. Sơ đồ thí nghiệm được mô tả trong Hình 23.1. Khi cho vật nặng chuyển động đi xuống, dây nối sẽ làm cho trục quay và cánh quạt quay theo. Ma sát giữa cánh quạt và nước làm cho nước nóng lên.",
    "Ở đây có sự truyền năng lượng từ vật nặng sang nước, cụ thể là sự chuyển hoá từ cơ năng sang nhiệt năng.",
    "Thí nghiệm đã cho thấy cơ năng của vật nặng giảm đi bao nhiêu thì nhiệt năng của nước tăng lên bấy nhiêu. Điều đó chứng tỏ, *trong quá trình truyền năng lượng từ vật này sang vật khác, chuyển hoá năng lượng từ dạng này sang dạng khác, năng lượng luôn được bảo toàn.*",
    "[Hình 23.1. Sơ đồ thí nghiệm minh hoạ định luật bảo toàn năng lượng. Đánh số các bộ phận từ 1 đến 5: (1) Vật nặng, (2) Dây nối, (3) Trục quay, (4) Cánh quạt, (5) Nhiệt kế]",
    "",
    "**Hoạt động:**",
    "Hãy thảo luận nhóm để tìm thêm ví dụ minh hoạ cho các quá trình chuyển hoá năng lượng sau đây:",
    "a) Điện năng chuyển hoá thành nhiệt năng.",
    "b) Nhiệt năng chuyển hoá thành điện năng.",
    "c) Quang năng chuyển hoá thành điện năng.",
    "d) Quang năng chuyển hoá thành hoá năng.",
    "",
    "## II. CÔNG CƠ HỌC",
    "**1. Thực hiện công**",
    "Năng lượng có thể truyền từ vật này sang vật khác.",
    "Ví dụ: Khi đẩy cuốn sách, ta tác dụng lực vào nó làm nó chuyển từ trạng thái đứng yên (v = 0; W$_d$ = 0) sang trạng thái chuyển động nhanh dần (vận tốc tăng, động năng tăng). Động năng của sách tăng là do sách đã nhận được năng lượng từ tay ta truyền sang (Hình 23.2).",
    "Việc truyền năng lượng cho vật bằng cách tác dụng lực lên vật làm vật thay đổi trạng thái chuyển động như trên được gọi là *thực hiện công cơ học* (gọi tắt là *thực hiện công*).",
    "[Hình 23.2. Đẩy cuốn sách]",
    "",
    "92",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "**Hoạt động:**",
    "Hãy trao đổi với bạn để chứng minh rằng trong các ví dụ mô tả ở Hình 23.3 có sự truyền năng lượng bằng cách thực hiện công.",
    "[Hình 23.3.",
    "a) Động cơ điện đưa vật nặng chuyển động từ dưới đất lên cao.",
    "b) Hỗn hợp xăng và không khí trong xilanh bị đốt cháy đẩy pittông chuyển động]",
    "",
    "**? Câu hỏi:**",
    "1. Hãy trả lời câu hỏi ở phần khởi động.",
    "2. Khi cho một miếng đồng tiếp xúc với ngọn lửa thì ngọn lửa truyền năng lượng cho miếng đồng làm cho nó nóng lên. Quá trình truyền năng lượng này có phải là thực hiện công hay không? Tại sao?",
    "",
    "**2. Công thức tính công**",
    "**a) Khi lực không đổi và cùng hướng với chuyển động**",
    "Ở lớp 9, chúng ta đã học công thức tính công của lực khi lực không đổi và cùng hướng với chuyển động:",
    "A = F.s (23.1)",
    "trong đó A là công của lực $\\vec{F}$, có đơn vị cùng với đơn vị năng lượng là jun (J): 1 J = 1 N.1 m; F là cường độ của lực tác dụng lên vật làm vật biến đổi chuyển động, đơn vị là niutơn (N), s là quãng đường đi được của vật, đơn vị là mét (m).",
    "Khi lực cùng hướng với chuyển động thì độ dịch chuyển d có độ lớn bằng quãng đường đi được s, nên công thức tính công cũng có thể viết dưới dạng:",
    "A = F.d (23.2)",
    "",
    "**b) Khi lực không đổi và không cùng phương với chuyển động**",
    "Khi người đẩy xe hàng để nó chuyển động theo chiều dương của trục Ox, lực đẩy $\\vec{F}$ làm với hướng chuyển động một góc $\\alpha$ bất kì (Hình 23.4). Ta phân tích lực $\\vec{F}$ ra hai lực thành phần vuông góc với nhau: $\\vec{F}_s$ cùng hướng với chuyển động và $\\vec{F}_n$ vuông góc với $\\vec{F}_s$ (Hình 23.5).",
    "Trong trường hợp này chỉ có thành phần $\\vec{F}_s$ làm vật chuyển động, nên công thực tính công của lực trong trường hợp này là:",
    "$A = F_s.s = (F.\\cos\\alpha).s = F.s.\\cos\\alpha$",
    "[Hình 23.4. Lực không cùng phương với phương chuyển động. Người đẩy máy cắt cỏ bằng lực $\\vec{F}$ nghiêng góc $\\alpha$ so với mặt đất]",
    "",
    "93",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "Tuỳ thuộc vào góc $\\alpha$ mà có thể xảy ra các trường hợp sau:",
    "- $0 \\le \\alpha < 90^\\circ$: thành phần $\\vec{F}_s$ của $\\vec{F}$ lên phương chuyển động cùng chiều với chiều chuyển động. Công của lực được gọi là *công phát động* (A > 0) (Hình 23.5a).",
    "- $\\alpha = 90^\\circ$: lực vuông góc với phương chuyển động, khi đó *lực không sinh công* (A = 0) (Hình 23.5b).",
    "- $90^\\circ < \\alpha \\le 180^\\circ$: thành phần $\\vec{F}_s$ của $\\vec{F}$ lên phương chuyển động ngược chiều với chiều chuyển động, lực làm cản trở chuyển động của vật. Công của lực được gọi là *công cản* (A < 0) (Hình 23.5c).",
    "[Hình 23.5. Các trường hợp công.",
    "a) Công phát động. $\\alpha$ nhọn.",
    "b) Lực không sinh công. $\\alpha = 90^\\circ$.",
    "c) Công cản. $\\alpha$ tù]",
    "",
    "**3. Bài tập ví dụ**",
    "*Bài tập ví dụ 1*",
    "Khi rửa gầm xe ô tô (Hình 23.6), người ta sử dụng máy nâng để nâng ô tô lên độ cao h = 160 cm so với mặt sàn. Cho biết khối lượng ô tô là m = 1,5 tấn và gia tốc trọng trường là g = 10 m/s$^2$. Tính công tối thiểu mà máy nâng đã thực hiện.",
    "*Giải*",
    "Để nâng được ô tô lên thì máy nâng phải tác dụng vào ô tô lực tối thiểu:",
    "$\\vec{F}_{\\text{min}} = -\\vec{P}$",
    "$\\Rightarrow F_{\\text{min}} = P = m.g = 1,5.10^3.10 = 1,5.10^4$ N.",
    "Công tối thiểu mà máy nâng đã thực hiện là:",
    "$A = P.h = 24000$ J = 24 kJ.",
    "[Hình 23.6. Máy nâng ô tô]",
    "",
    "*Bài tập ví dụ 2*",
    "Một bạn học sinh có khối lượng 50 kg đi lên một cầu thang gồm 20 bậc, mỗi bậc cao 15 cm, dài 20 cm (Hình 23.7). Tính công tối thiểu mà bạn ấy phải thực hiện. Coi lực mà học sinh tác dụng lên mỗi bậc thang là không đổi trong quá trình di chuyển. Lấy gia tốc trọng trường là g = 10 m/s$^2$.",
    "*Giải*",
    "– Muốn lên cầu thang này bạn học sinh phải có lực nâng tối thiểu như Hình 23.8:",
    "$\\vec{F}_{\\text{min}} = -\\vec{P}$",
    "$\\Rightarrow F_{\\text{min}} = P = m.g$",
    "Độ dịch chuyển của bạn học sinh là: $\\vec{d} = \\vec{AB}$.",
    "– Công tối thiểu mà bạn ấy phải thực hiện là:",
    "$A_{\\text{min}} = F_{\\text{min}}.d.\\cos\\alpha = F_{\\text{min}}.d.\\sin\\beta$",
    "$= m.g.d.\\sin\\beta = m.g.h$",
    "= 50.10.20.0,15 = 1500 J.",
    "[Hình 23.7. Học sinh đi lên cầu thang]",
    "[Hình 23.8. Biểu diễn lực và độ dịch chuyển của học sinh đi cầu thang. $\\vec{F}_{\\text{min}}$ hướng lên, $\\vec{P}$ hướng xuống. $\\vec{AB}$ là vectơ dịch chuyển, góc $\\alpha$ giữa $\\vec{F}_{\\text{min}}$ và $\\vec{AB}$, góc $\\beta$ giữa phương ngang và $\\vec{AB}$]",
    "",
    "94",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "Nhận xét: Độ lớn tối thiểu của công dùng để đưa vật lên cao luôn là: A = P.h.",
    "Với h là độ cao vật được nâng lên không phụ thuộc vào việc được đưa lên cao theo đường thẳng đứng hay nằm nghiêng.",
    "",
    "**? Câu hỏi:**",
    "1. Trường hợp nào sau đây trọng lực tác dụng lên ô tô thực hiện công phát động, công cản và không thực hiện công?",
    "a) Ô tô đang xuống dốc.",
    "b) Ô tô đang lên dốc.",
    "c) Ô tô chạy trên đường nằm ngang.",
    "2. Một người kéo một thùng hàng khối lượng 80 kg trượt trên sàn nhà bằng một dây có phương hợp góc $30^\\circ$ so với phương nằm ngang. Biết lực tác dụng lên dây bằng 150 N. Tính công của lực đó khi hòm trượt đi được 29 m.",
    "",
    "**EM ĐÃ HỌC**",
    "- Năng lượng có thể chuyển hoá từ dạng này sang dạng khác, hoặc truyền từ vật này sang vật khác và luôn được bảo toàn.",
    "- Công là số đo phần năng lượng được truyền hoặc chuyển hoá trong quá trình thực hiện công.",
    "- Công có đơn vị là jun (J): 1 J = 1 N.1 m.",
    "- Công thức tính công: $A = F.d.\\cos\\alpha$.",
    "",
    "**EM CÓ THỂ**",
    "- Chế tạo được mô hình đơn giản minh hoạ định luật bảo toàn năng lượng.",
    "- Giải thích được nếu một vật chuyển động lên dốc, xuống dốc hoặc trên mặt phẳng ngang thì công của trọng lực đóng vai trò gì.",
    "",
    "**EM CÓ BIẾT?**",
    "Trường hợp tổng quát, công do lực thực hiện phụ thuộc vào ba yếu tố: độ lớn của lực, góc hợp bởi véctơ lực với chiều chuyển động và độ dịch chuyển của vật. Tuy nhiên, có những lực mà công do nó thực hiện không phụ thuộc vào hình dạng đường đi mà chỉ phụ thuộc vào vị trí của điểm đầu và điểm cuối của quỹ đạo. Những lực có đặc điểm này được gọi là lực thế (hay lực bảo toàn).",
    "Trong chương trình phổ thông, các em sẽ học một số lực thế gồm: lực hấp dẫn, lực đàn hồi, lực điện.",
    "",
    "95"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B24', 'Bài 24 CÔNG SUẤT', 97, 2, $JSON$
{
  "content": [
    "# Bài 24 CÔNG SUẤT",
    "",
    "**Khởi động:**",
    "*Để đánh giá việc thực hiện công của người hay thiết bị sinh công, người ta không chỉ quan tâm đến độ lớn của công thực hiện được mà còn quan tâm đến việc công này được thực hiện nhanh hay chậm.*",
    "*Theo em, làm thế nào để xác định được sự nhanh chậm của việc thực hiện công?*",
    "[Hình ảnh hai người khiêng đồ lên cầu thang. Người đi trước nói: \"Tớ thực hiện công nhanh hơn cậu vì tớ leo lên cao hơn cậu\". Người đi sau nói: \"Chưa chắc đâu vì cậu leo trước tớ\"]",
    "",
    "## I. KHÁI NIỆM CÔNG SUẤT",
    "**Hoạt động:**",
    "Hai anh công nhân dùng ròng rọc để kéo xô vữa lên các tầng cao của một công trình xây dựng. Dựa vào bảng số liệu dưới đây, hãy xác định xem ai là người thực hiện công nhanh hơn. Lấy g = 10 m/s$^2$.",
    "**Bảng 24.1**",
    "| Công nhân | Khối lượng xô vữa: m (kg) | Độ cao công trình: h (m) | Công thực hiện: A (J) | Thời gian thực hiện công: t (s) |",
    "|---|---|---|---|---|",
    "| Công nhân 1 | $m_1$ = 20 kg | $h_1$ = 10 m | $A_1 = \\dots ?$ | $t_1$ = 10 s |",
    "| Công nhân 2 | $m_2$ = 21 kg | $h_2$ = 11 m | $A_2 = \\dots ?$ | $t_2$ = 20 s |",
    "",
    "Đại lượng đặc trưng cho khả năng thực hiện công nhanh hay chậm của người hoặc thiết bị sinh công, được gọi là *công suất* hay *tốc độ sinh công*.",
    "",
    "## II. CÔNG THỨC TÍNH CÔNG SUẤT",
    "Nếu trong thời gian t, công thực hiện được là A thì tốc độ sinh công, tức công suất là:",
    "$\\mathcal{P} = \\frac{A}{t}$ (24.1)",
    "Nếu A tính bằng jun (J), t tính bằng giây (s) thì $\\mathcal{P}$ tính bằng oát (W):",
    "$1 \\text{ W} = \\frac{1 \\text{ J}}{1 \\text{ s}}$",
    "Các bội của oát (W) là:",
    "1 kilôoát = 1 kW = 10$^3$ W",
    "1 mêgaoát = 1 MW = 10$^6$ W",
    "",
    "**! Chú ý:** Kilôoát giờ (kW.h) không phải là đơn vị công suất mà là đơn vị công. *1 kW.h là công của một thiết bị sinh công có công suất là 1 kW thực hiện trong 1 giờ.*",
    "",
    "**? Câu hỏi:**",
    "Coi công suất trung bình của trái tim là 3 W.",
    "a) Trong một ngày – đêm trung bình trái tim thực hiện một công là bao nhiêu?",
    "b) Nếu một người sống 70 tuổi thì công của trái tim thực hiện là bao nhiêu? Một ô tô tải muốn thực hiện được công này phải thực hiện trong thời gian bao lâu? Coi công suất của xe ô tô tải là 3.10$^5$ W.",
    "",
    "96",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "## III. LIÊN HỆ GIỮA CÔNG SUẤT VỚI LỰC VÀ TỐC ĐỘ",
    "Khi vật chuyển động cùng hướng với lực và lực không đổi thì:",
    "$\\mathcal{P} = \\frac{A}{t} = \\frac{F.s}{t} = F.v$ (24.2)",
    "Công thức (24.2) là công thức tính công suất trung bình. Công thức tính công suất tức thời là:",
    "$\\mathcal{P}_t = F.v_t$ (24.3)",
    "Nếu $v$ là tốc độ trung bình của vật thì $\\mathcal{P}$ là công suất trung bình của lực làm vật chuyển động.",
    "Nếu $v_t$ là tốc độ tức thời của vật thì $\\mathcal{P}_t$ là công suất tức thời của lực làm vật chuyển động.",
    "*Bài tập ví dụ*",
    "Một người kéo một thùng nước 15 kg từ giếng sâu 8 m lên trong 10 s. Hãy tính công suất của người kéo. Biết thùng nước chuyển động đều và lấy g = 10 m/s$^2$.",
    "*Giải*",
    "Vì vật chuyển động thẳng đều nên tốc độ của vật là:",
    "$v = \\frac{s}{t} = \\frac{8}{10} = 0,8$ m/s",
    "và lực kéo vật lên bằng trọng lượng của vật:",
    "F = P = m.g = 15.10 = 150 N",
    "Công suất của người kéo bằng:",
    "$\\mathcal{P} = F.v = 150.0,8 = 120$ W.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy giải thích tác dụng của líp nhiều tầng trong xe đạp thể thao (Hình 24.1).",
    "2. Hình 24.2 mô tả hộp số xe máy. Hãy giải thích tại sao khi đi xe máy trên những đoạn đường dốc hoặc có ma sát lớn ta thường đi ở số nhỏ.",
    "3. Động cơ của một thang máy tác dụng lực kéo 20 000 N để thang máy chuyển động thẳng lên trên trong 10 s và quãng đường đi được tương ứng là 18 m. Công suất trung bình của động cơ là",
    "A. 36 kW. B. 3,6 kW.",
    "C. 11 kW. D. 1,1 kW.",
    "4. Một ô tô khối lượng 1 tấn đang hoạt động với công suất 5 kW và chuyển động thẳng đều với vận tốc 54 km/h thì lên dốc. Hỏi động cơ ô tô phải hoạt động với công suất bằng bao nhiêu để có thể lên dốc với tốc độ như cũ? Biết hệ số ma sát giữa bánh xe và mặt đường không đổi, dốc nghiêng góc $2,3^\\circ$ so với mặt đường nằm ngang và g = 10 m/s$^2$.",
    "[Hình 24.1. Líp xe đạp thể thao]",
    "[Hình 24.2. Hộp số xe máy]",
    "",
    "97",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "**Hoạt động:** Thi xem ai là người có công suất lớn hơn",
    "1. Hãy nêu tên dụng cụ cần dùng và cách tiến hành việc đo thời gian lên cầu thang",
    "2. Thảo luận trong nhóm về kế hoạch hoạt động để xác định công suất khi lên thang gác của 5 người đại diện các tổ có trọng lượng khác nhau, trong đó ghi rõ:",
    "a) Mục đích của hoạt động.",
    "b) Dụng cụ cần sử dụng.",
    "c) Các bước tiến hành hoạt động.",
    "d) Bảng ghi kết quả.",
    "**Bảng 24.2.** Mẫu bảng ghi kết quả",
    "| Tên người | Trọng lượng (N) | Độ cao (m) | Công (J) | Thời gian (s) | Công suất (W) |",
    "|---|---|---|---|---|---|",
    "| 1. \\dots | $P_1 = \\dots$ | $h = \\dots$ | $A_1 = \\dots$ | $t_1 = \\dots$ | $\\mathcal{P}_1 = \\dots$ |",
    "| 2. \\dots | $P_2 = \\dots$ | $h = \\dots$ | $A_2 = \\dots$ | $t_2 = \\dots$ | $\\mathcal{P}_2 = \\dots$ |",
    "| 3. \\dots | $P_3 = \\dots$ | $h = \\dots$ | $A_3 = \\dots$ | $t_3 = \\dots$ | $\\mathcal{P}_3 = \\dots$ |",
    "| 4. \\dots | $P_4 = \\dots$ | $h = \\dots$ | $A_4 = \\dots$ | $t_4 = \\dots$ | $\\mathcal{P}_4 = \\dots$ |",
    "| 5. \\dots | $P_5 = \\dots$ | $h = \\dots$ | $A_5 = \\dots$ | $t_5 = \\dots$ | $\\mathcal{P}_5 = \\dots$ |",
    "",
    "**EM ĐÃ HỌC**",
    "- Công suất là đại lượng đặc trưng cho tốc độ sinh công, được đo bằng công sinh ra trong một giây và có đơn vị là oát (W):",
    "$\\mathcal{P} = \\frac{A}{t}$",
    "- Liên hệ giữa công suất với lực và tốc độ: $\\mathcal{P} = F.v$",
    "Công suất trung bình: $\\mathcal{P} = \\frac{A}{t} = \\frac{F.s}{t} = F.v$",
    "Công suất tức thời: $\\mathcal{P}_t = F.v_t$",
    "",
    "**EM CÓ THỂ**",
    "1. Tính được công suất của các quá trình sinh công.",
    "2. Vận dụng khái niệm công suất để giải thích nguyên tắc hoạt động của một số thiết bị máy móc.",
    "",
    "98"
  ]
}
