INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B25', 'Bài 25 ĐỘNG NĂNG, THẾ NĂNG', 100, 3, $JSON$
{
  "content": [
    "# Bài 25 ĐỘNG NĂNG, THẾ NĂNG",
    "",
    "**Khởi động:**",
    "[Hình ảnh tàu lượn siêu tốc đang lao xuống]",
    "*Hãy mô tả hoạt động của tàu lượn.*",
    "*Tại sao khi tàu lượn ở vị trí cao nhất của đường ray thì tốc độ của nó lại chậm nhất và ngược lại?*",
    "",
    "## I. ĐỘNG NĂNG",
    "**1. Khái niệm động năng**",
    "Chúng ta đã biết động năng của một vật là năng lượng mà vật có được do chuyển động.",
    "Một vật có khối lượng m đang chuyển động với tốc độ v thì động năng là:",
    "$W_d = \\frac{1}{2}m.v^2$ (25.1)",
    "Trong hệ đơn vị SI, đơn vị động năng là jun (J).",
    "Qua các ví dụ về năng lượng sóng, chuyển động của thiên thạch, chuyển động của mũi tên trong phần câu hỏi bên, ta thấy vật đang chuyển động có khả năng thực hiện công. Ta nói rằng vật đó mang năng lượng dưới dạng động năng.",
    "*Bài tập ví dụ 1:* Một vận động viên quần vợt thực hiện cú giao bóng kỉ lục, quả bóng đạt tới tốc độ 196 km/h. Biết khối lượng quả bóng là 60 g. Tính động năng của quả bóng.",
    "*Giải*",
    "Động năng của quả bóng được tính theo công thức:",
    "$W_d = \\frac{1}{2}m.v^2$",
    "Thay số:",
    "$W_d = \\frac{1}{2}.0,06.\\left(196.1000.\\frac{1}{3600}\\right)^2 \\approx 89$ J.",
    "",
    "**? Câu hỏi:**",
    "1. Năng lượng của các con sóng trong Hình 25.1 tồn tại dưới dạng nào?",
    "- Tại sao sóng thần lại có sức tàn phá mạnh hơn rất nhiều so với sóng thông thường?",
    "- Tại sao sóng thần chỉ gây ra sự tàn phá khi xô vào vật cản?",
    "2. Khi đang bay, năng lượng của thiên thạch tồn tại dưới dạng nào?",
    "- Tại sao năng lượng của thiên thạch lại rất lớn so với năng lượng của các vật thường gặp?",
    "- Khi va vào Trái Đất (Hình 25.2), năng lượng của thiên thạch được chuyển hoá thành những dạng năng lượng nào?",
    "3. Khi sóng đổ vào bờ nó sinh công và có thể xô đổ các vật trên bờ. Tuy nhiên, với vận động viên lướt sóng thì không bị ảnh hưởng. Tại sao?",
    "4. Một mũi tên nặng 48 g đang chuyển động với tốc độ 10 m/s. Tìm động năng của mũi tên.",
    "[Hình 25.1. Sóng thần]",
    "[Hình 25.2. Hố lõm do thiên thạch gây ra khi va vào Trái Đất]",
    "",
    "99",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "**2. Liên hệ giữa động năng và công của lực**",
    "Xét một vật khối lượng m chuyển động thẳng biến đổi đều với gia tốc a từ trạng thái đứng yên dưới tác dụng của lực không đổi F. Sau khi đi được quãng đường s, vật đạt tốc độ v thì: $v^2 = 2.a.s$.",
    "Vì $a = \\frac{F}{m}$ nên $v^2 = \\frac{2.F.s}{m}$",
    "và $\\frac{1}{2}.m.v^2 = F.s \\Rightarrow W_d = A$ (25.2)",
    "*Như vậy, nếu ban đầu vật đứng yên thì động năng của vật có giá trị bằng công của lực tác dụng lên vật.*",
    "",
    "## II. THẾ NĂNG",
    "**1. Khái niệm thế năng trọng trường**",
    "Chúng ta đã biết một vật đặt ở độ cao h so với mặt đất thì lưu trữ năng lượng dưới dạng thế năng. Vì thế năng này liên quan đến trọng lực nên được gọi là *thế năng trọng trường* (thường được gọi tắt là *thế năng*), với độ lớn được tính bằng công thức: $W_t = P.h = m.g.h$.",
    "Đơn vị thế năng trọng trường là jun (J).",
    "**! Chú ý:** Độ lớn của thế năng trọng trường phụ thuộc vào việc chọn mốc tính độ cao. Thường người ta tính độ cao của các vật so với mặt đất được coi là có độ cao bằng 0.",
    "",
    "**? Câu hỏi:**",
    "Máy đóng cọc (Hình 25.3) hoạt động như sau: Búa máy được nâng lên đến một độ cao nhất định rồi thả cho rơi xuống cọc cần đóng.",
    "1. Khi búa đang ở một độ cao nhất định thì năng lượng của nó tồn tại dưới dạng nào? Năng lượng đó do đâu mà có?",
    "2. Trong quá trình rơi, năng lượng của búa chuyển từ dạng nào sang dạng nào?",
    "3. Khi chạm vào đầu cọc thì búa sinh công để làm gì?",
    "[Hình 25.3. Máy đóng cọc]",
    "",
    "*Bài tập ví dụ 2:* Máy đóng cọc có đầu búa nặng 0,5 tấn, được nâng lên độ cao 10 m so với mặt đất. Tính thế năng của đầu búa. Lấy g = 9,8 m/s$^2$.",
    "*Giải*",
    "Thế năng của đầu búa được tính theo công thức:",
    "$W_t = m.g.h = 500.9,8.10 = 49 000 \\text{ J} = 49 \\text{ kJ}$",
    "",
    "**? Câu hỏi:**",
    "1. Thả một quả bóng từ độ cao h xuống sàn nhà. Động năng của quả bóng được chuyển hoá thành những dạng năng lượng nào ngay khi quả bóng chạm vào sàn nhà?",
    "2. Một vật có khối lượng 10 kg đang chuyển động với tốc độ 5 km/h trên mặt bàn nằm ngang. Do có ma sát, vật chuyển động chậm dần đều và đi được 1 m thì dừng lại. Tính hệ số ma sát giữa vật và mặt bàn. Lấy gia tốc trọng trường g = 9,8 m/s$^2$.",
    "",
    "**EM CÓ BIẾT?**",
    "Ngoài thế năng trọng trường còn có nhiều loại thế năng khác, dưới đây là một ví dụ (Hình 25.4).",
    "[Hình 25.4. Người giương cung]",
    "Khi giương cung thì cánh cung bị biến dạng đàn hồi. Nếu người đó buông tay thì mũi tên sẽ bị dây cung đẩy đi xa. Điều này chứng tỏ khi giương cung thì cánh cung bị biến dạng đã có năng lượng dự trữ để thực hiện công đẩy mũi tên đi. Năng lượng dự trữ này được gọi là thế năng đàn hồi.",
    "",
    "101",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "Vì độ cao h phụ thuộc vào vị trí được chọn làm mốc nên thế năng cũng phụ thuộc vào vị trí được chọn làm mốc.",
    "Trong trọng trường, hiệu thế năng giữa hai điểm chỉ phụ thuộc vào chênh lệch độ cao theo phương thẳng đứng mà không phụ thuộc vào khoảng cách giữa hai điểm.",
    "",
    "**2. Liên hệ giữa thế năng và công của lực thế**",
    "Muốn đưa một vật có khối lượng m từ mặt đất lên một độ cao h, ta phải tác dụng vào vật lực nâng F có độ lớn tối thiểu bằng trọng lượng P của vật.",
    "Công mà lực nâng F thực hiện là:",
    "$A = F.s = P.h = m.g.h = W_t$",
    "*Vậy thế năng của vật ở độ cao h có độ lớn bằng công của lực dùng để nâng đều vật lên độ cao này.*",
    "Công trong trường hợp này được gọi là công của lực thế, nó không phụ thuộc vào độ lớn quãng đường đi được mà chỉ phụ thuộc vào sự chênh lệch độ cao của vị trí đầu và vị trí cuối.",
    "",
    "**? Câu hỏi:**",
    "1. Một chiếc cần cẩu xây dựng cẩu một khối vật liệu nặng 500 kg từ vị trí A ở mặt đất đến vị trí B của một toà nhà cao tầng với các thông số cho trên Hình 25.6. Lấy gia tốc trọng trường g = 9,8 m/s$^2$. Tính thế năng của khối vật liệu tại B và công mà cần cẩu đã thực hiện.",
    "2. Hãy chứng minh có thể dùng một mặt phẳng nghiêng để đưa một vật lên cao với một lực nhỏ hơn trọng lượng của vật (Hình 25.7). Coi ma sát không đáng kể.",
    "",
    "**? Câu hỏi:**",
    "[Hình 25.5. Sách trên giá và sách trên ghế]",
    "Hình 25.5 mô tả một cuốn sách được đặt trên giá sách. Hãy so sánh thế năng của cuốn sách trong hai trường hợp: gốc thế năng là sàn nhà và gốc thế năng là mặt bàn.",
    "[Hình 25.6. Cần cẩu kéo vật từ A (mặt đất) lên B (tầng cao) với độ cao 40m, theo đường xiên 50m. Điểm chiếu của B xuống đất cách A 30m]",
    "[Hình 25.7. Kéo vật lên mặt phẳng nghiêng dài $l$, cao h bằng lực $\\vec{F}$]",
    "",
    "**EM ĐÃ HỌC**",
    "- Động năng là năng lượng mà vật có được do chuyển động: $W_d = \\frac{1}{2}m.v^2$ có giá trị bằng công của lực làm cho vật chuyển động từ trạng thái đứng yên đến khi đạt được tốc độ đó.",
    "- Thế năng của vật trong trường trọng lực là năng lượng lưu trữ trong vật do độ cao của vật so với gốc thế năng: $W_t = m.g.h$, có giá trị bằng công của lực để đưa vật từ gốc thế năng đến độ cao đó.",
    "",
    "**EM CÓ THỂ**",
    "Giải thích được hoạt động của máy đóng cọc dựa trên sự chuyển hoá động năng và thế năng của vật.",
    "",
    "102"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B26', 'Bài 26 CƠ NĂNG VÀ ĐỊNH LUẬT BẢO TOÀN CƠ NĂNG', 103, 4, $JSON$
{
  "content": [
    "# Bài 26 CƠ NĂNG VÀ ĐỊNH LUẬT BẢO TOÀN CƠ NĂNG",
    "",
    "**Khởi động:**",
    "*Kỉ lục nhảy sào thế giới hiện nay là 6,17 m do vận động viên người Thuỵ Điển Amand Duplantis lập năm 2020, kỉ lục nhảy cao thế giới hiện nay là 2,45 m do vận động viên người Cuba Javier Sotomayor lập năm 1993. Tại sao vận động viên nhảy sào có thể nhảy cao hơn vận động viên nhảy cao nhiều đến thế?*",
    "[Hình ảnh vận động viên nhảy sào]",
    "",
    "## I. SỰ CHUYỂN HOÁ GIỮA ĐỘNG NĂNG VÀ THẾ NĂNG",
    "Chúng ta đã biết ở Trung học cơ sở:",
    "– Cơ năng của một vật là tổng động năng và thế năng của nó. Khi vật chuyển động trong trường trọng lực thì cơ năng có dạng:",
    "$W_c = W_d + W_t = \\frac{1}{2}m.v^2 + m.g.h$ (26.1)",
    "– Động năng và thế năng có thể chuyển hoá qua lại lẫn nhau.",
    "[Hình 26.1. Tàu lượn siêu tốc với các điểm A (thấp nhất), B (cao nhất), C, D, E]",
    "",
    "**? Câu hỏi:**",
    "1. Khi nước chảy từ thác xuống:",
    "a) Lực nào làm cho nước chảy từ đỉnh thác xuống dưới?",
    "b) Lực nào sinh công trong quá trình này?",
    "c) Động năng và thế năng của nó thay đổi như thế nào?",
    "d) Hãy dự đoán về mối liên hệ giữa độ tăng động năng và độ giảm thế năng.",
    "2. Từ một điểm ở độ cao h so với mặt đất, ném một vật có khối lượng m lên cao với vận tốc ban đầu $v_0$.",
    "a) Khi vật đi lên có những lực nào tác dụng lên vật, lực đó sinh công cản hay công phát động?",
    "b) Trong quá trình vật đi lên rồi rơi xuống thì dạng năng lượng nào tăng, dạng năng lượng nào giảm? Hãy dự đoán về mối liên hệ giữa độ tăng của động năng và độ giảm của thế năng.",
    "",
    "**? Câu hỏi:**",
    "1. Trên Hình 26.1 là một phần đường đi của tàu lượn siêu tốc. Em hãy phân tích sự chuyển hoá giữa động năng và thế năng của tàu lượn trên từng đoạn đường.",
    "2. Trong các quá trình hoạt động của tàu lượn, ngoài động năng và thế năng còn có dạng năng lượng nào khác tham gia vào quá trình chuyển hoá?",
    "",
    "103",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "Như vậy động năng và thế năng có thể chuyển hoá qua lại lẫn nhau. Nếu thế năng chuyển thành động năng thì lực sẽ sinh công phát động, ngược lại, khi động năng chuyển thành thế năng thì lực sinh công cản.",
    "Nhưng độ giảm của động năng có bằng độ tăng của thế năng, hay cơ năng không đổi không?",
    "",
    "## II. ĐỊNH LUẬT BẢO TOÀN CƠ NĂNG",
    "**1. Thí nghiệm về con lắc đồng hồ**",
    "Bây giờ ta hãy xét quá trình chuyển hoá giữa động năng và thế năng trong dao động của con lắc đồng hồ (Hình 26.2a).",
    "Mô hình đơn giản của con lắc đồng hồ gồm một thanh nhẹ, không dãn, một đầu được giữ cố định, đầu còn lại nối với một vật nặng (Hình 26.2b).",
    "Đưa vật nặng lên điểm A có độ cao xác định h so với điểm O rồi thả cho vật chuyển động tự do. Ta thấy vật chuyển động nhanh dần từ A xuống O, tiếp tục chuyển động chậm dần từ O lên B, rồi lại chuyển động nhanh dần từ B xuống O, chậm dần từ O lên A,...",
    "[Hình 26.2. Con lắc đồng hồ quả lắc.",
    "a) Đồng hồ quả lắc thực tế.",
    "b) Sơ đồ dao động từ A đến O đến B]",
    "",
    "**? Câu hỏi:**",
    "1. Khi vật chuyển động trên cung AO thì:",
    "a) Những lực nào sinh công? Công nào là công phát động, công nào là công cản?",
    "b) Động năng và thế năng của vật thay đổi như thế nào?",
    "2. Trả lời những câu hỏi trên cho quá trình vật chuyển động trên cung OB.",
    "3. Nếu bỏ qua ma sát thì A và B luôn nằm trên cùng một độ cao. Hiện tượng này chứng tỏ điều gì?",
    "",
    "**2. Định luật bảo toàn cơ năng**",
    "Thí nghiệm trên cho thấy độ tăng/giảm của động năng bằng độ giảm/tăng của thế năng, nghĩa là cơ năng luôn không đổi. Từ đó, ta có thể phát biểu định luật bảo toàn cơ năng như sau:",
    "*Khi một vật chuyển động trong trọng trường chỉ chịu tác dụng của trọng lực thì cơ năng của vật được bảo toàn.*",
    "[Hình 26.3. Vận động viên trượt ván trong máng]",
    "Hình 26.3 mô tả vận động viên tham gia trượt ván trong máng. Bỏ qua mọi ma sát, hãy phân tích sự bảo toàn cơ năng của vận động viên này.",
    "",
    "104",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "*Bài tập ví dụ:*",
    "Một con lắc đơn (Hình 26.4), biết độ dài dây treo là $\\ell$ = 0,6 m. Đưa vật lên vị trí A hợp với phương thẳng đứng OC một góc $\\alpha = 30^\\circ$ rồi thả nhẹ nhàng, vật sẽ đi xuống O (vị trí thấp nhất) rồi đi đến B, sau đó quay lại và dao động cứ thế tiếp diễn. Bỏ qua tác dụng của các lực cản, lực ma sát, lấy g = 9,8 m/s$^2$. Hãy tính độ lớn vận tốc của vật tại vị trí O.",
    "[Hình 26.4. Con lắc đơn dao động từ A qua O đến B]",
    "*Giải*",
    "Chọn mốc tính thế năng tại vị trí thấp nhất O.",
    "Gọi cơ năng tại vị trí A, O lần lượt là W$_A$ và W$_O$.",
    "Thế năng tại vị trí A và O là:",
    "W$_{tA}$ = m.g.h$_A$. Từ Hình 26.4 ta có:",
    "h$_A$ = OC – CE = $\\ell - \\ell.\\cos\\alpha$ = $\\ell.(1 - \\cos\\alpha)$",
    "$\\Rightarrow$ W$_{tA}$ = $m.g.\\ell(1 - \\cos\\alpha)$;",
    "W$_{tO}$ = m.g.h$_O$, vì h$_O$ = 0 $\\Rightarrow$ W$_{tO}$ = 0",
    "Động năng tại vị trí A và O là:",
    "W$_{dA}$ = 0; W$_{dO}$ = $\\frac{1}{2}m.v_O^2$",
    "Áp dụng định luật bảo toàn cơ năng ta có:",
    "W$_A$ = W$_O \\Leftrightarrow$ W$_{tA}$ + W$_{dA}$ = W$_{tO}$ + W$_{dO}$",
    "$\\Leftrightarrow m.g.\\ell.(1 - \\cos\\alpha) = \\frac{1}{2}m.v_O^2$",
    "$\\Leftrightarrow v_O = \\sqrt{2.g.\\ell(1 - \\cos\\alpha)}$",
    "Thay số ta có:",
    "$v_O = \\sqrt{2.9,8.0,6(1 - \\cos30^\\circ)} \\approx 1,26$ m/s.",
    "",
    "**EM CÓ BIẾT?**",
    "Chúng ta cũng có thể dùng các kiến thức của bài trước để chứng minh rằng khi một vật chuyển động trong trọng trường chỉ chịu tác dụng của trọng lực thì cơ năng của nó được bảo toàn.",
    "Ví dụ: Xét sự thay đổi động năng và thế năng của một vật có khối lượng m rơi tự do từ vị trí A (độ cao h$_1$) xuống vị trí B (độ cao h$_2$) (Hình 26.5).",
    "[Hình 26.5. Vật rơi tự do từ A độ cao h1 xuống B độ cao h2]",
    "Trong quá trình chuyển động đó, công A$_{AB}$ của trọng lực được xác định bởi hiệu thế năng tại A và B:",
    "A$_{AB}$ = W$_{tA}$ – W$_{tB}$ = m.g.h$_1$ – m.g.h$_2$ (1)",
    "Nếu trong quá trình đó, vật chỉ chịu tác dụng của trọng lực thì công của trọng lực cũng được tính bằng độ biến thiên động năng từ A đến B:",
    "A$_{AB}$ = W$_{dB}$ – W$_{dA}$ = $\\frac{1}{2}m.v_B^2 - \\frac{1}{2}m.v_A^2$ (2)",
    "Từ (1) và (2) ta có:",
    "W$_{tA}$ – W$_{tB}$ = W$_{dB}$ – W$_{dA}$",
    "$\\Leftrightarrow$ W$_{tA}$ + W$_{dA}$ = W$_{tB}$ + W$_{dB}$",
    "$\\Leftrightarrow$ W$_A$ = W$_B$",
    "Với W$_A$, W$_B$ lần lượt là cơ năng của vật tại A và B.",
    "",
    "105",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "**Hoạt động:**",
    "Chế tạo mô hình minh hoạ định luật bảo toàn năng lượng.",
    "*Dụng cụ:* một viên bi, hai thanh kim loại nhẵn, hai giá đỡ có vít điều chỉnh độ cao.",
    "*Chế tạo:* Dùng hai thanh kim loại uốn thành đường ray và gắn lên giá đỡ để tạo được mô hình như Hình 26.6.",
    "[Hình 26.6. Mô hình minh hoạ định luật bảo toàn năng lượng. Đường ray kim loại cong uốn lượn có điểm A cao, điểm B thấp, C cao, D cao. Viên bi rơi từ A qua B vòng qua vòng cung C]",
    "*Thí nghiệm:*",
    "- Thả viên bi từ điểm A trên đường ray.",
    "- Viên bi có thể chuyển động tới điểm D không? Tại sao? Làm thí nghiệm để kiểm tra.",
    "",
    "**? Câu hỏi:**",
    "1. Một vật được thả cho rơi tự do từ độ cao h = 10 m so với mặt đất. Bỏ qua mọi ma sát. Ở độ cao nào thì vật có động năng bằng thế năng?",
    "2. Thả một vật có khối lượng m = 0,5 kg từ độ cao h$_1$ = 0,8 m so với mặt đất. Xác định động năng và thế năng của vật ở độ cao h$_2$ = 0,6 m. Lấy g = 9,8 m/s$^2$.",
    "",
    "**EM ĐÃ HỌC**",
    "- Động năng và thế năng của vật có thể chuyển hoá qua lại lẫn nhau.",
    "- Cơ năng của một vật là tổng của động năng và thế năng. Nếu vật chuyển động trong trọng trường chỉ chịu tác dụng bởi trọng lực thì cơ năng của nó được bảo toàn.",
    "",
    "**EM CÓ THỂ**",
    "1. Vận dụng định luật bảo toàn cơ năng để giải thích một số tình huống trong đời sống, kĩ thuật.",
    "2. Giải thích được vì sao vận động viên nhảy sào có thể nhảy lên được tới hơn 6 m, trong khi đó vận động viên nhảy cao chỉ nhảy được tới hơn 2 m.",
    "",
    "106"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B27', 'Bài 27 HIỆU SUẤT', 107, 5, $JSON$
{
  "content": [
    "# Bài 27 HIỆU SUẤT",
    "",
    "**Khởi động:**",
    "*Theo em thì có thể có bao nhiêu phần trăm động năng của thác nước được nhà máy thuỷ điện chuyển hoá thành điện năng?*",
    "[Hình ảnh đập nước của nhà máy thuỷ điện]",
    "",
    "## I. NĂNG LƯỢNG CÓ ÍCH VÀ NĂNG LƯỢNG HAO PHÍ",
    "Chúng ta đã biết khi năng lượng được chuyển từ dạng này sang dạng khác, từ vật này sang vật khác, thì luôn có một phần bị hao phí.",
    "Trong các động cơ nhiệt thông thường có khoảng từ 60% đến 70% năng lượng bị hao phí, trong các động cơ điện năng lượng hao phí thấp hơn, chỉ vào khoảng 10%, nhưng trong các pin mặt trời thì ngược lại, chỉ có khoảng 10% năng lượng của ánh sáng mặt trời được chuyển hoá thành điện năng, còn lại là năng lượng hao phí.",
    "",
    "**Hoạt động:**",
    "Hãy thảo luận về các vấn đề sau:",
    "1. Xác định năng lượng có ích và năng lượng hao phí khi chơi thể thao.",
    "2. Nếu chơi thể thao trong thời tiết lạnh thì nhiệt năng mà cơ thể toả ra có được xem là năng lượng có ích không? Vì sao?",
    "",
    "**? Câu hỏi:**",
    "1. Trong động cơ ô tô chạy bằng xăng và trong quạt điện:",
    "a) Có những sự chuyển hoá năng lượng nào?",
    "b) Trong số những dạng năng lượng tạo thành, dạng năng lượng nào là có ích, dạng năng lượng nào là hao phí?",
    "2. Xác định năng lượng có ích và năng lượng hao phí trong các trường hợp dưới đây:",
    "a) Ắcquy khi nạp điện.",
    "b) Ắcquy khi phóng điện.",
    "c) Sử dụng ròng rọc để kéo vật nặng lên cao.",
    "d) Bếp từ khi đang hoạt động.",
    "",
    "## II. HIỆU SUẤT",
    "Để đánh giá tỉ lệ giữa năng lượng có ích và năng lượng toàn phần, người ta dùng khái niệm hiệu suất.",
    "Hiệu suất = $\\frac{\\text{Năng lượng có ích}}{\\text{Năng lượng toàn phần}}$",
    "$H = \\frac{W_{ci}}{W_{tp}} . 100\\%$ (27.1)",
    "hoặc $H = \\frac{\\mathcal{P}_{ci}}{\\mathcal{P}_{tp}} . 100\\%$ với $\\mathcal{P}_{ci}$ là công suất có ích, $\\mathcal{P}_{tp}$ là công suất toàn phần.",
    "[Hình 27.1. Sơ đồ dòng năng lượng: Năng lượng toàn phần đi vào, chia thành năng lượng có ích và năng lượng hao phí đi ra]",
    "",
    "107",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "Từ công thức tính hiệu suất chung ở trên người ta có thể viết công thức tính hiệu suất cho từng trường hợp cụ thể.",
    "Ví dụ, hiệu suất của động cơ nhiệt được viết dưới dạng:",
    "$H = \\frac{A}{Q} . 100\\%$ (27.2)",
    "Trong đó, A là công cơ học mà động cơ thực hiện được, Q là nhiệt lượng mà động cơ nhận được từ nhiên liệu bị đốt cháy.",
    "**Bảng 27.1.** Hiệu suất của một số thiết bị điện",
    "| Thiết bị | Năng lượng đầu vào | Năng lượng đầu ra có ích | Hiệu suất |",
    "|---|---|---|---|",
    "| Máy phát điện | Cơ năng | Điện năng | 96% |",
    "| Tuabin nước | Cơ năng | Cơ năng | 90% |",
    "| Máy hơi nước | Hoá năng | Cơ năng | 15% |",
    "| Động cơ xăng | Hoá năng | Cơ năng | 35% |",
    "| Tuabin hơi nước | Hoá năng | Cơ năng | 28% |",
    "| Động cơ điện | Điện năng | Cơ năng | 96% |",
    "| Đèn dây tóc | Điện năng | Quang năng | 7% |",
    "| Đèn LED | Điện năng | Quang năng | 95% |",
    "| Bếp điện | Điện năng | Nhiệt năng | 90% |",
    "",
    "*Bài tập ví dụ:* Một em bé nặng 20 kg chơi cầu trượt từ trạng thái đứng yên ở đỉnh cầu trượt dài 4 m, nghiêng góc $40^\\circ$ so với phương nằm ngang (Hình 27.2). Khi đến chân cầu trượt, tốc độ của em bé này là 3,2 m/s. Lấy gia tốc trọng trường là 10 m/s$^2$.",
    "a) Tính độ lớn lực ma sát tác dụng vào em bé này.",
    "b) Tính hiệu suất của quá trình chuyển thế năng thành động năng của em bé này.",
    "[Hình 27.2. Cầu trượt. Góc nghiêng $\\alpha$, độ dài $l$, chiều cao h]",
    "*Giải*",
    "a) Độ lớn lực ma sát",
    "Độ cao của đỉnh cầu trượt so với mặt đất:",
    "$h = \\ell.\\sin\\alpha = 4.\\sin 40^\\circ \\approx 2,57$ m",
    "Do có ma sát nên khi trượt, một phần thế năng của em bé được chuyển hoá thành động năng, một phần thắng công cản A của lực ma sát:",
    "$m.g.h = \\frac{m.v^2}{2} + A$",
    "Độ lớn công cản của lực ma sát:",
    "$A = m.g.h - \\frac{m.v^2}{2} \\approx 411,6$ J",
    "Từ biểu thức tính công: $A = F.s.\\cos\\alpha$",
    "Ta có độ lớn lực ma sát: $F = \\frac{A}{\\ell} \\approx 102,9$ N.",
    "b) Hiệu suất",
    "– Năng lượng toàn phần bằng thế năng của em bé ở đỉnh cầu trượt:",
    "$W_{tp} = m.g.h = 514$ J.",
    "",
    "108",
    "CHƯƠNG IV – NĂNG LƯỢNG, CÔNG, CÔNG SUẤT",
    "",
    "– Năng lượng hao phí bằng độ lớn công của lực ma sát nên năng lượng có ích là:",
    "$W_{ci} = W_{tp} - A = 102,4$ J",
    "– Hiệu suất của quá trình biến đổi thế năng thành động năng:",
    "$H = \\frac{W_{ci}}{W_{tp}} . 100\\% = \\frac{102,4}{514} . 100\\% \\approx 20\\%$.",
    "",
    "**? Câu hỏi:**",
    "1. Phân tích sự tiêu hao năng lượng ở động cơ đốt trong dùng trong ô tô (Hình 27.3).",
    "[Hình 27.3. Sơ đồ phân bố sự chuyển hoá năng lượng (cho động cơ xăng của ô tô).",
    "Tổng năng lượng do nhiên liệu bị đốt cháy cung cấp (100%):",
    "- 30% -> Ra ngoài theo khí thải (24%), Truyền cho hệ thống làm mát (6%)",
    "- 35% -> Nhiệt sinh công trong hoạt động. (Trong đó 41% (của 35%) -> Đến các bánh xe)",
    "- Các tiêu hao khác: Bức xạ nhiệt ra ngoài 5%]",
    "*(Ghi chú: Lược đồ trong sách có vẻ các con số phần trăm không cộng lại thành 100% một cách rõ ràng theo sơ đồ)*",
    "",
    "2. Hiệu suất của nhà máy điện dùng năng lượng mặt trời không bằng 1/3 hiệu suất của nhà máy nhiệt điện. Tại sao người ta vẫn khuyến khích xây dựng nhà máy điện dùng năng lượng mặt trời?",
    "3. Một ô tô chuyển động với vận tốc 54 km/h có thể đi được đoạn đường dài bao nhiêu khi tiêu thụ hết 60 lít xăng? Biết động cơ của ô tô có công suất 45 kW; hiệu suất 25%; 1 kg xăng đốt cháy hoàn toàn toả ra nhiệt lượng bằng $46.10^6$ J/kg và khối lượng riêng của xăng là 700 kg/m$^3$.",
    "",
    "**EM ĐÃ HỌC**",
    "- Luôn tồn tại năng lượng hao phí trong các quá trình chuyển hoá năng lượng.",
    "- Hiệu suất được định nghĩa theo công thức: $H = \\frac{W_{ci}}{W_{tp}} . 100\\% = \\frac{\\mathcal{P}_{ci}}{\\mathcal{P}_{tp}} . 100\\%$",
    "",
    "**EM CÓ THỂ**",
    "1. Vận dụng khái niệm hiệu suất để tính được phần năng lượng có ích và phần năng lượng hao phí trong quá trình hoạt động của các thiết bị phổ biến trong đời sống và kĩ thuật.",
    "2. Tìm phương án giảm năng lượng hao phí khi sử dụng các thiết bị điện trong gia đình hoặc động cơ ô tô, xe máy.",
    "",
    "109"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B28', 'Bài 28 ĐỘNG LƯỢNG', 111, 1, $JSON$
{
  "content": [
    "# Bài 28 ĐỘNG LƯỢNG",
    "",
    "**Khởi động:**",
    "*Quan sát hình dưới đây.*",
    "*- Hình a: Xe tải và xe con đang chạy cạnh nhau với cùng vận tốc. Khi đèn tín hiệu màu đỏ bật sáng, xe nào muốn dừng lại thì cần phải có một lực hãm lớn hơn. Tại sao?*",
    "*- Hình b: Cầu thủ đá bóng sút phạt 11 m. Thủ môn khó bắt bóng hơn khi bóng bay tới có tốc độ lớn hay nhỏ? Tại sao?*",
    "[Hình a: Xe tải và xe con chạy tới đèn đỏ. Hình b: Cầu thủ sút phạt đền, thủ môn cố bắt bóng]",
    "",
    "## I. ĐỘNG LƯỢNG",
    "**Hoạt động:**",
    "Thực hiện các thí nghiệm sau để tìm hiểu về sự truyền chuyển động trong tương tác giữa các vật.",
    "*Chuẩn bị:*",
    "– Ba viên bi A, B, C (chọn bi B nặng hơn A và C).",
    "– Máng trượt (có thể dùng ống nhựa cắt dọc).",
    "– Một vài vật (hộp giấy, quyển sách) để tạo độ dốc của máng trượt.",
    "– Đặt viên bi C ngay dưới chân máng trượt như Hình 28.1.",
    "[Hình 28.1. Thí nghiệm tìm hiểu về sự truyền chuyển động trong tương tác. Viên bi A trên máng nghiêng lăn xuống va chạm viên bi C ở chân máng]",
    "*Tiến hành:*",
    "– *Thí nghiệm 1:* Lần lượt thả hai viên bi: A, B (bi B nặng hơn bi A) chuyển động trên máng trượt. Quan sát và đo quãng đường dịch chuyển của viên bi C sau va chạm ứng với mỗi lần thả.",
    "– *Thí nghiệm 2:* Bây giờ chỉ thả viên bi A lăn xuống máng trượt nhưng tăng độ dốc của máng trượt. Quan sát và đo quãng đường dịch chuyển của viên bi C sau va chạm ứng với mỗi lần thả.",
    "*Thảo luận:*",
    "– Trong thí nghiệm 1, vận tốc của hai viên bi A và B khi đến chân dốc có giống nhau không? Viên bi nào đẩy viên bi C lăn xa hơn? Tại sao?",
    "– Trong thí nghiệm 2, ứng với độ dốc nào thì viên bi A có vận tốc lớn hơn khi va chạm với bi C? Ở trường hợp nào, viên bi C lăn xa hơn? Tại sao?",
    "",
    "Từ hai thí nghiệm trên, ta thấy vật có khối lượng và vận tốc càng lớn thì sự truyền chuyển động trong tương tác với các vật khác càng mạnh. Đại lượng đặc trưng cho khả năng truyền chuyển động của một vật khi tương tác với vật khác gọi là *động lượng* của vật.",
    "",
    "110",
    "CHƯƠNG V – ĐỘNG LƯỢNG",
    "",
    "Động lượng của một vật khối lượng m đang chuyển động với vận tốc $\\vec{v}$ là đại lượng được xác định bởi công thức:",
    "$\\vec{p} = m.\\vec{v}$ (28.1)",
    "Động lượng là một đại lượng vectơ có cùng hướng với vận tốc của vật.",
    "Đơn vị động lượng là: kg.m/s.",
    "",
    "**? Câu hỏi:**",
    "1. Tìm thêm ví dụ minh hoạ cho ý nghĩa vật lí trên của động lượng.",
    "2. a) Động lượng của xe tải hay ô tô trong hình ở đầu bài lớn hơn?",
    "b) Trong trường hợp sút phạt 11 m, tại sao thủ môn khó bắt bóng hơn nếu bóng có động lượng tăng?",
    "",
    "## II. XUNG LƯỢNG CỦA LỰC",
    "**1. Xung lượng**",
    "Khi một lực $\\vec{F}$ tác dụng lên một vật trong khoảng thời gian ngắn $\\Delta t$ thì tích $\\vec{F}.\\Delta t$ được định nghĩa là xung lượng của lực $\\vec{F}$ trong khoảng thời gian $\\Delta t$ ấy (Lực $\\vec{F}$ được xem là không đổi trong khoảng thời gian tác dụng ngắn $\\Delta t$).",
    "Đơn vị xung lượng của lực là N.s.",
    "",
    "**? Câu hỏi:**",
    "1. Trong các ví dụ sau, các vật đã chịu tác dụng của các lực nào trong thời gian rất ngắn?",
    "– Cầu thủ thực hiện một cú đá vô lê đã đưa được bóng vào lưới đối phương.",
    "– Trong môn bi-a, quả bi-a đang chuyển động thì va chạm vào thành bàn nên nó bị đổi hướng.",
    "– Trong môn chơi gôn, một quả bóng gôn đang nằm yên. Sau một cú đánh, quả bóng bay đi rất nhanh.",
    "2. Hãy chỉ ra sự biến đổi trạng thái chuyển động của vật trong các ví dụ trên như thế nào? Tại sao lực tác dụng lên vật trong một khoảng thời gian ngắn lại có thể gây ra biến đổi đáng kể trạng thái chuyển động của vật đó?",
    "",
    "**? Câu hỏi:**",
    "1. a) Nêu định nghĩa và đơn vị của động lượng.",
    "b) Vẽ vectơ động lượng của một quả bóng tennis vừa bật khỏi mặt vợt (Hình 28.2).",
    "[Hình 28.2. Vợt tennis đánh quả bóng]",
    "2. Phát biểu nào sau đây **không đúng** khi nói về động lượng?",
    "A. Động lượng của một vật đặc trưng cho trạng thái chuyển động của vật đó.",
    "B. Động lượng là đại lượng vectơ.",
    "C. Động lượng có đơn vị là kg.m/s.",
    "D. Động lượng của một vật chỉ phụ thuộc vào vận tốc của vật đó.",
    "3. Tính độ lớn động lượng trong các trường hợp sau:",
    "a) Một xe buýt khối lượng 3 tấn đang chuyển động với tốc độ 72 km/h.",
    "b) Một hòn đá khối lượng 500 g chuyển động với tốc độ 10 m/s.",
    "c) Một electron chuyển động với tốc độ $2.10^7$ m/s. Biết khối lượng electron bằng $9,1.10^{-31}$ kg.",
    "4. Một xe tải có khối lượng 1,5 tấn chuyển động với tốc độ 36 km/h và một ô tô có khối lượng 750 kg chuyển động ngược chiều với tốc độ 54 km/h. So sánh động lượng của hai xe.",
    "5. Tại sao đơn vị của động lượng còn có thể viết là N.s?",
    "",
    "111",
    "CHƯƠNG V – ĐỘNG LƯỢNG",
    "",
    "**2. Liên hệ giữa xung lượng của lực và độ biến thiên động lượng**",
    "Giả sử có một lực $\\vec{F}$ (không đổi) tác dụng lên một vật khối lượng m đang chuyển động với vận tốc $\\vec{v}_1$. Trong khoảng thời gian tác dụng $\\Delta t$, vận tốc của vật biến đổi thành $\\vec{v}_2$, nghĩa là vật đã có gia tốc:",
    "$\\vec{a} = \\frac{\\vec{v}_2 - \\vec{v}_1}{\\Delta t}$",
    "Theo định luật 2 Newton:",
    "$\\vec{F} = m.\\vec{a} = m\\frac{\\vec{v}_2 - \\vec{v}_1}{\\Delta t}$",
    "Suy ra:",
    "$\\vec{F}.\\Delta t = m.\\vec{v}_2 - m.\\vec{v}_1 = \\vec{p}_2 - \\vec{p}_1$ (28.2)",
    "Vế trái của (28.2) chính là xung lượng của lực trong khoảng thời gian $\\Delta t$, còn vế phải là độ biến thiên động lượng của vật.",
    "Từ (28.2), ta có thể viết: $\\vec{F}.\\Delta t = \\Delta\\vec{p}$ (28.3)",
    "Công thức (28.3) cho thấy:",
    "Xung lượng của lực tác dụng lên vật trong một khoảng thời gian bằng độ biến thiên động lượng của vật trong khoảng thời gian đó.",
    "",
    "**3. Dạng tổng quát của định luật 2 Newton**",
    "Từ (28.3), ta có thể viết: $\\vec{F} = \\frac{\\Delta\\vec{p}}{\\Delta t}$ (28.4)",
    "Công thức (28.4) cho thấy: *Lực tổng hợp tác dụng lên vật bằng tốc độ thay đổi động lượng của vật.*",
    "Phát biểu trên được xem như một cách diễn đạt khác của định luật 2 Newton.",
    "",
    "**? Câu hỏi:**",
    "1. a) Xung lượng của lực gây ra tác dụng gì?",
    "b) Một quả bóng khối lượng m đang bay ngang với tốc độ v thì đập vào một bức tường và bật trở lại với cùng tốc độ. Xung lượng của lực gây ra bởi tường lên quả bóng là",
    "A. mv. B. –mv. C. 2mv. D. –2mv.",
    "2. Thủ môn khi bắt bóng muốn không đau tay và khỏi ngã thì phải co tay lại và lùi người một chút theo hướng đi của quả bóng. Thủ môn làm thế để",
    "A. làm giảm động lượng của quả bóng.",
    "B. làm giảm độ biến thiên động lượng của quả bóng.",
    "C. làm tăng xung lượng của lực quả bóng tác dụng lên tay.",
    "D. làm giảm cường độ của lực quả bóng tác dụng lên tay.",
    "3. Một quả bóng gôn có khối lượng 46 g đang nằm yên, sau một cú đánh quả bóng bay lên với tốc độ 70 m/s. Tính xung lượng của lực và độ lớn trung bình của lực tác dụng vào quả bóng. Biết thời gian tác dụng là $0,5.10^{-3}$ s.",
    "4. Hai vật có khối lượng lần lượt là $m_1$ = 1 kg và $m_2$ = 2 kg, chuyển động với vận tốc có độ lớn lần lượt là $v_1$ = 3 m/s và $v_2$ = 2 m/s.",
    "a) Tính động lượng của mỗi vật.",
    "b) Vật nào khó dừng lại hơn? Vì sao?",
    "",
    "**EM ĐÃ HỌC**",
    "- Động lượng của một vật khối lượng m đang chuyển động với vận tốc $\\vec{v}$ là đại lượng được xác định bởi công thức: $\\vec{p} = m.\\vec{v}$.",
    "- Động lượng là đại lượng đặc trưng cho sự truyền tương tác giữa các vật.",
    "- Tích $\\vec{F}.\\Delta t$ được gọi là xung lượng của lực tác dụng trong khoảng thời gian ngắn $\\Delta t$ và bằng độ biến thiên động lượng của vật trong thời gian đó: $\\vec{F}.\\Delta t = \\Delta\\vec{p}$.",
    "",
    "**EM CÓ THỂ**",
    "1. Mô tả và tính độ lớn động lượng của Trái Đất trong chuyển động quanh Mặt Trời, khi biết khối lượng Trái Đất và bán kính quỹ đạo.",
    "2. Tính động lượng của hệ “tên lửa + khí” ngay trước và sau khi phụt khí, khi đã biết khối lượng, vận tốc của tên lửa và của khí phụt ra.",
    "",
    "112"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B29', 'Bài 29 ĐỊNH LUẬT BẢO TOÀN ĐỘNG LƯỢNG', 114, 2, $JSON$
{
  "content": [
    "# Bài 29 ĐỊNH LUẬT BẢO TOÀN ĐỘNG LƯỢNG",
    "",
    "**Khởi động:**",
    "*Một người đang ở trong một chiếc thuyền nhỏ đứng yên, tại sao thuyền bị lùi lại khi người đó bước lên bờ?*",
    "[Hình ảnh người bước từ thuyền nhỏ lên bờ, thuyền bị đẩy ra xa]",
    "",
    "## I. ĐỊNH LUẬT BẢO TOÀN ĐỘNG LƯỢNG",
    "**1. Hệ kín (hay hệ cô lập)**",
    "a) *Một hệ nhiều vật được gọi là hệ kín khi không có ngoại lực tác dụng lên hệ hoặc nếu có thì các lực ấy cân bằng nhau.* Trong một hệ kín, chỉ có các *nội lực* (các lực tác dụng giữa các vật trong hệ) tương tác giữa các vật. Các nội lực này theo định luật 3 Newton trực đối nhau từng đôi một.",
    "b) Nếu trong quá trình tương tác, các nội lực xuất hiện lớn hơn các ngoại lực rất nhiều thì có thể bỏ qua các ngoại lực và coi hệ là kín. Ví dụ như: va chạm, đạn nổ, pháo nổ,...",
    "",
    "**? Câu hỏi:**",
    "Hãy cho ví dụ về hệ kín.",
    "",
    "**2. Định luật bảo toàn động lượng**",
    "Xét một hệ kín gồm hai vật trượt trên một đệm khí đến va chạm với nhau.",
    "Vì các lực $\\vec{F}_1$ và $\\vec{F}_2$ là cặp nội lực trực đối nhau, nên theo định luật 3 Newton, ta viết:",
    "$\\vec{F}_1 = -\\vec{F}_2$ (29.1)",
    "Dưới tác dụng của các lực $\\vec{F}_1$ và $\\vec{F}_2$, trong khoảng thời gian $\\Delta t$, động lượng của mỗi vật có độ biến thiên lần lượt là $\\Delta\\vec{p}_1$ và $\\Delta\\vec{p}_2$.",
    "Áp dụng công thức $\\vec{F}.\\Delta t = \\Delta\\vec{p}$ cho từng vật, ta có:",
    "$\\begin{cases} \\vec{F}_1.\\Delta t = \\Delta\\vec{p}_1 \\\\ \\vec{F}_2.\\Delta t = \\Delta\\vec{p}_2 \\end{cases}$ (29.2)",
    "Từ (29.1) và (29.2), suy ra:",
    "$\\Delta\\vec{p}_1 = -\\Delta\\vec{p}_2$ hay $\\Delta\\vec{p}_1 + \\Delta\\vec{p}_2 = \\vec{0}$",
    "Gọi $\\vec{p} = \\vec{p}_1 + \\vec{p}_2$ là động lượng toàn phần của hệ. Ta có biến thiên động lượng toàn phần của hệ bằng tổng các biến thiên động lượng của mỗi vật: $\\Delta\\vec{p} = \\Delta\\vec{p}_1 + \\Delta\\vec{p}_2 = \\vec{0}$",
    "Biến thiên động lượng của hệ bằng không, nghĩa là động lượng toàn phần của hệ không đổi.",
    "$\\vec{p} = \\vec{p}_1 + \\vec{p}_2$ (không đổi)",
    "Kết quả này có thể mở rộng cho hệ kín gồm nhiều vật.",
    "",
    "113",
    "CHƯƠNG V – ĐỘNG LƯỢNG",
    "",
    "Từ đó, ta có thể phát biểu: *Động lượng toàn phần của hệ kín là một đại lượng bảo toàn.*",
    "Phát biểu trên được gọi là định luật bảo toàn động lượng.",
    "Định luật bảo toàn động lượng có nhiều ứng dụng thực tế: giải các bài toán va chạm, làm cơ sở cho nguyên tắc chuyển động phản lực.",
    "",
    "**? Câu hỏi:**",
    "Một hệ gồm hai vật có khối lượng lần lượt là $m_1$ và $m_2$, chuyển động với vận tốc có độ lớn lần lượt là $v_1$ và $v_2$ hướng vào nhau. Bỏ qua mọi ma sát và lực cản của không khí. Viết biểu thức của định luật bảo toàn động lượng cho hệ này.",
    "",
    "## II. VA CHẠM ĐÀN HỒI VÀ VA CHẠM MỀM",
    "Có hai kiểu va chạm thường gặp là va chạm đàn hồi và va chạm mềm.",
    "",
    "**1. Va chạm đàn hồi**",
    "Hình 29.1 mô tả một thí nghiệm về va chạm đàn hồi.",
    "[Hình 29.1. Va chạm đàn hồi. Hai xe A và B gắn cầu kim loại.",
    "Trước va chạm: $v_A = v$, $v_B = 0$",
    "Sau va chạm: $v'_A = 0$, $v'_B = v$ (Trường hợp 2 xe cùng khối lượng)]",
    "Dùng hai xe A và B giống nhau, ở đầu mỗi xe có gắn một quả cầu kim loại nhỏ, cho xe A chuyển động với vận tốc $v_A = v$ tới va chạm với xe B đang đứng yên. Kết quả của va chạm làm xe A đang chuyển động thì dừng lại, còn xe B đang đứng yên thì chuyển động với đúng vận tốc $v'_B = v$ (Hình 29.1). Còn nếu xe A chuyển động đến va chạm trực diện với xe B có vận tốc $v_B = -v$, thì sau va chạm cả hai xe đổi chiều vận tốc: $v'_A = -v$ và $v'_B = v$. Đó là hai ví dụ về kiểu va chạm đàn hồi.",
    "Va chạm như thế gọi là va chạm đàn hồi.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy tính động lượng và động năng của hệ trước và sau va chạm đàn hồi. (Hình 29.1)",
    "2. Từ kết quả tính được rút ra nhận xét gì?",
    "",
    "**2. Va chạm mềm**",
    "Hình 29.2 mô tả một thí nghiệm về va chạm mềm.",
    "[Hình 29.2. Va chạm mềm. Hai xe A và B gắn miếng nhựa dính.",
    "Trước va chạm: $v_A = v$, $v_B = 0$",
    "Sau va chạm: 2 xe dính vào nhau $v_{AB} = \\frac{v}{2}$]",
    "Dùng hai xe A và B giống nhau, ở đầu mỗi xe có gắn một miếng nhựa dính. Cho xe A chuyển động với vận tốc $v_A = v$ tới va chạm với xe kia đang đứng yên. Sau va chạm, cả hai xe dính vào nhau và chuyển động với vận tốc bằng $v_{AB} = \\frac{v}{2}$. Kiểu va chạm “dính” này gọi là va chạm mềm.",
    "",
    "114",
    "CHƯƠNG V – ĐỘNG LƯỢNG",
    "",
    "**? Câu hỏi:**",
    "1. Hãy tính động lượng và động năng của hệ trong Hình 29.2 trước và sau va chạm.",
    "2. Từ kết quả tính được rút ra nhận xét gì?",
    "3. Trong Hình 29.3, nếu kéo bi (1) lên thêm một độ cao h rồi thả ra. Con lắc sẽ rơi xuống và va chạm với hai con lắc còn lại. Hãy dự đoán xem va chạm là va chạm gì. Con lắc (2), (3) lên tới độ cao nào? Làm thí nghiệm để kiểm tra.",
    "[Hình 29.3. Con lắc Newton gồm 3 quả cầu kim loại. Quả (1) kéo lên một góc, (2) và (3) đứng yên]",
    "",
    "**EM ĐÃ HỌC**",
    "- Một hệ nhiều vật tác dụng lẫn nhau được gọi là hệ kín (hay hệ cô lập) khi không có ngoại lực tác dụng vào hệ hoặc khi các ngoại lực cân bằng nhau.",
    "- Định luật bảo toàn động lượng: “Động lượng toàn phần của hệ kín là một đại lượng bảo toàn”.",
    "- Có hai kiểu va chạm thường gặp là va chạm đàn hồi và va chạm mềm.",
    "",
    "**EM CÓ THỂ**",
    "Vận dụng định luật bảo toàn động lượng để giải thích:",
    "1. Tại sao hai người đang đứng yên trên sân băng bị lùi ra xa nhau khi họ dùng tay đẩy vào nhau (Hình 29.4).",
    "2. Tại sao tốc độ lùi của mỗi người có khối lượng khác nhau thì khác nhau.",
    "[Hình 29.4. Hai người đứng trên sân băng đẩy nhau rồi lùi lại với vận tốc $V_1, V_2$]",
    "",
    "115"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B30', 'Bài 30 THỰC HÀNH: XÁC ĐỊNH ĐỘNG LƯỢNG CỦA VẬT TRƯỚC VÀ SAU VA CHẠM', 117, 3, $JSON$
{
  "content": [
    "# Bài 30 THỰC HÀNH: XÁC ĐỊNH ĐỘNG LƯỢNG CỦA VẬT TRƯỚC VÀ SAU VA CHẠM",
    "",
    "**Khởi động:**",
    "*Có hai xe chuyển động va chạm vào nhau thì động lượng các xe thay đổi. Em hãy nêu các trường hợp có thể xảy ra và dự đoán sau va chạm hai xe chuyển động như thế nào. Làm thế nào xác định được động lượng của hai xe trước và sau va chạm bằng dụng cụ thí nghiệm, từ đó kiểm nghiệm định luật bảo toàn động lượng?*",
    "",
    "## I. DỤNG CỤ THÍ NGHIỆM",
    "– Băng đệm khí (1).",
    "– Đồng hồ đo thời gian hiện số (2).",
    "– Hai cổng quang điện (3).",
    "– Bơm nén khí (4).",
    "– Hai xe trượt (5).",
    "– Hai tấm cản quang (6).",
    "– Cân điện tử (7).",
    "– Một số quả nặng (8).",
    "– Lò xo hoặc thanh nhựa hình chữ U để mắc dây cao su đàn hồi (9).",
    "– Chốt ghim (10).",
    "– Các dây nối (11).",
    "[Hình 30.1. Bộ dụng cụ thí nghiệm xác định động lượng trước và sau va chạm. Các chi tiết đánh số từ 1 đến 11]",
    "",
    "## II. THIẾT KẾ PHƯƠNG ÁN THÍ NGHIỆM",
    "Để hai xe va chạm trên đệm khí, có thể thực hiện như sau:",
    "– Điều chỉnh cho băng đệm khí nằm ngang và lắp ống dẫn khí từ bơm nén khí vào băng đệm khí.",
    "– Lắp hai cổng quang điện vào hai giá đỡ đặt cách nhau một khoảng.",
    "– Nối dây từ hai cổng quang điện vào đồng hồ đo thời gian hiện số.",
    "– Lắp tấm cản quang và các chốt cắm thích hợp lên mỗi xe và đặt hai xe lên băng đệm khí.",
    "– Cấp điện cho bơm nén khí và đồng hồ đo thời gian hiện số.",
    "",
    "**Hoạt động:**",
    "Đẩy cho hai xe chuyển động va chạm vào nhau trên đệm khí và thảo luận:",
    "1. Khi hai xe chuyển động trên đệm khí nằm ngang, hệ hai xe chuyển động có phải là hệ kín không? Vì sao?",
    "2. Để xác định động lượng của hai xe trước và sau va chạm cần đo các đại lượng nào?",
    "3. Hãy thử các trường hợp mà em đã dự đoán và suy nghĩ làm thế nào đo được các đại lượng để xác định động lượng của hai xe trước và sau va chạm.",
    "4. Thiết kế phương án thí nghiệm để xác định động lượng của hai xe trước và sau va chạm tương ứng với các trường hợp va chạm có thể xảy ra.",
    "",
    "116",
    "CHƯƠNG V – ĐỘNG LƯỢNG",
    "",
    "## III. TIẾN HÀNH THÍ NGHIỆM",
    "*Thí nghiệm 1: Va chạm mềm*",
    "Hai xe chuyển động va chạm vào nhau, sau va chạm hai xe dính vào nhau và chuyển động với cùng vận tốc.",
    "1. Bố trí thí nghiệm như Hình 30.2.",
    "2. Lắp tấm cản quang vào xe và các chốt cắm thích hợp lên hai xe, sau đó cân khối lượng xe và ghi vào Bảng 30.1.",
    "3. Cấp điện cho bơm nén khí và đồng hồ đo thời gian, điều chỉnh tốc độ của bơm nén khí thích hợp, cho đồng hồ đo thời gian hoạt động ở chế độ đo thời gian vật chắn cổng quang điện.",
    "4. Ấn nút Reset trên mặt đồng hồ để đưa số chỉ của đồng hồ về 0.000.",
    "5. Đặt xe 2 lên băng đệm khí giữa hai cổng quang điện, đặt xe 1 ở khoảng bên ngoài hai cổng quang điện.",
    "6. Đẩy xe 1 va chạm vào xe 2.",
    "7. Lần lượt đọc trên đồng hồ các khoảng thời gian $t_1, t_2$ và ghi vào Bảng 30.1.",
    "8. Gắn thêm vào xe các gia trọng, lặp lại các bước 4, 5, 6, 7 hai lần.",
    "[Hình 30.2. Bố trí thí nghiệm xác định động lượng trong trường hợp va chạm mềm]",
    "",
    "**! Chú ý:** Gắn tấm chắn cổng quang điện và điều chỉnh cho song song với băng đệm khí.",
    "",
    "*Thí nghiệm 2: Va chạm đàn hồi*",
    "Hai xe chuyển động va chạm vào nhau, sau va chạm hai xe chuyển động về hai phía ngược nhau (Hình 30.3).",
    "1. Bố trí thí nghiệm như Hình 30.3.",
    "2. Gắn lò xo (hoặc thanh nhựa hình chữ U có dây cao su đàn hồi vào 1 xe). Cân hai xe và ghi vào Bảng 30.2.",
    "3. Đặt hai xe lên băng đệm khí ở vị trí giữa hai cổng quang. Lấy sợi dây nhỏ buộc hai xe để nén lò xo lại. Ấn nút Reset trên mặt đồng hồ.",
    "4. Cắt sợi dây để lò xo bung ra, đẩy hai xe về hai phía.",
    "5. Lần lượt đọc trên đồng hồ các khoảng thời gian $t_1, t_2$ và ghi vào Bảng 30.2.",
    "6. Gắn thêm vào hai xe các gia trọng, lặp lại các bước 3, 4, 5 hai lần nữa.",
    "[Hình 30.3. Thí nghiệm xác định động lượng trong trường hợp va chạm đàn hồi]",
    "",
    "117",
    "CHƯƠNG V – ĐỘNG LƯỢNG",
    "",
    "## IV. KẾT QUẢ THÍ NGHIỆM",
    "**Bảng 30.1.** Thí nghiệm va chạm mềm",
    "Độ dài tấm cản quang: $\\dots\\dots\\dots$ (m)",
    "| | | | Trước va chạm | | | Sau va chạm | | |",
    "|---|---|---|---|---|---|---|---|---|",
    "| Lần | $m_1$ | $m_2$ | $t_1$ | $v_1$ | $p_1$ | $p_2$ | p | $t'_1$ | $V_1 = V_2$ | p' |",
    "| 1 | | | | | | | | | | |",
    "| 2 | | | | | | | | | | |",
    "| 3 | | | | | | | | | | |",
    "",
    "**Bảng 30.2.** Thí nghiệm va chạm đàn hồi",
    "| | | | Trước va chạm | | | | Sau va chạm | | | |",
    "|---|---|---|---|---|---|---|---|---|---|---|",
    "| Lần | $m_1$ | $m_2$ | $p_1$ | $p_2$ | $t'_1$ | $t'_2$ | $v'_1$ | $v'_2$ | $p'_1$ | $p'_2$ |",
    "| 1 | | | | | | | | | | |",
    "| 2 | | | | | | | | | | |",
    "| 3 | | | | | | | | | | |",
    "",
    "**Hoạt động:** Nhận xét và đánh giá kết quả thí nghiệm",
    "1. Từ Bảng 30.1 và Bảng 30.2, hãy so sánh các kết quả xác định động lượng của hai xe trước và sau va chạm trong hai thí nghiệm.",
    "2. Em có thể đề xuất một phương án thí nghiệm khác để xác định động lượng của hai xe trước và sau va chạm.",
    "",
    "**EM ĐÃ HỌC**",
    "- Sử dụng băng đệm khí, cổng quang và đồng hồ đo thời gian hiện số có thể tiến hành thí nghiệm xác định động lượng của vật trước và sau va chạm đối với va chạm mềm, va chạm đàn hồi.",
    "- Để tiến hành thí nghiệm chính xác, cần đặt máng ngang và giảm ma sát ít nhất có thể.",
    "",
    "**EM CÓ THỂ**",
    "Sử dụng điện thoại thông minh và phần mềm phân tích video để xác định được vận tốc và động lượng trước và sau va chạm của hai viên bi có khối lượng xác định.",
    "[Hình 30.4. Thiết kế thí nghiệm xác định động lượng của hai viên bi trước và sau va chạm bằng điện thoại thông minh]",
    "",
    "**EM CÓ BIẾT?**",
    "Trong thiết kế ô tô, ngoài túi khí và dây an toàn trên ô tô, nhà sản xuất còn tạo ra “vùng hấp thụ xung lượng của lực” – đó là phần khung thép mềm hơn các vùng khác.",
    "Khi có va chạm, độ biến thiên động lượng của xe trong một khoảng thời gian bằng xung của lực tác dụng lên xe trong khoảng thời gian đó: $\\Delta\\vec{p} = \\vec{F}.\\Delta t$. Vùng hấp thụ xung lượng của lực sẽ biến dạng giúp xe giảm tốc độ chậm hơn, kéo dài thời gian va chạm để giảm lực tác dụng, giúp giảm chấn thương cho người ngồi trong xe.",
    "",
    "118"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B31', 'Bài 31 ĐỘNG HỌC CỦA CHUYỂN ĐỘNG TRÒN ĐỀU', 121, 1, $JSON$
{
  "content": [
    "# Bài 31 ĐỘNG HỌC CỦA CHUYỂN ĐỘNG TRÒN ĐỀU",
    "",
    "**Khởi động:**",
    "*Khi xe mô tô đua vào khúc cua thì có những bộ phận nào của xe chuyển động tròn?*",
    "[Hình ảnh người đi xe mô tô thể thao đang vào cua nghiêng xe]",
    "",
    "## I. MÔ TẢ CHUYỂN ĐỘNG TRÒN",
    "Trong cuộc sống hằng ngày ta gặp nhiều vật chuyển động tròn như: cánh quạt, kim đồng hồ, đu quay,...",
    "Để xác định vị trí của vật chuyển động tròn ta có thể dựa vào quãng đường đi s (độ dài cung tròn) hoặc độ dịch chuyển góc $\\theta$ tính từ vị trí ban đầu.",
    "Khi vật chuyển động tròn trong thời gian t từ A đến B thì độ dịch chuyển góc của vật trong thời gian này là góc ở tâm $\\theta$ chắn cung AB có độ dài s bằng quãng đường đi được cũng trong thời gian đó (Hình 31.1).",
    "[Hình 31.1. Quãng đường s và độ dịch chuyển góc $\\theta$. Đường tròn tâm O bán kính r. Điểm A và B trên đường tròn, cung AB là s, góc ở tâm là $\\theta$]",
    "",
    "Trong Toán học, ta đã biết mối quan hệ giữa độ dài cung với góc chắn tâm và bán kính đường tròn:",
    "$\\theta = \\frac{s}{r}$ (31.1)",
    "Trong Vật lí người ta thường dùng đơn vị góc là rađian (kí hiệu rad). Có thể dễ dàng chuyển đơn vị độ sang rad. Ví dụ, khi vật chuyển động được 1 vòng tròn, ta có:",
    "$\\theta = \\frac{2.\\pi.r}{r} = 2.\\pi$",
    "Do đó: $360^\\circ = 2.\\pi \\text{ (rad)}$",
    "Tương tự, ta có: $180^\\circ = \\pi \\text{ (rad)}$.",
    "",
    "**? Câu hỏi:**",
    "1. Chứng minh rằng một rađian là góc ở tâm chắn cung có độ dài bằng bán kính đường tròn.",
    "2. Tính quãng đường đi được khi vật chuyển động tròn có độ dịch chuyển góc 1 rad, biết bán kính đường tròn là 2 m.",
    "3. Xét chuyển động của kim giờ đồng hồ. Tìm độ dịch chuyển góc của nó (theo độ và rađian):",
    "a) Trong mỗi giờ.",
    "b) Trong khoảng thời gian từ 12 giờ đến 15 giờ 30 phút.",
    "",
    "120",
    "CHƯƠNG VI – CHUYỂN ĐỘNG TRÒN ĐỀU",
    "",
    "## II. CHUYỂN ĐỘNG TRÒN ĐỀU. TỐC ĐỘ VÀ TỐC ĐỘ GÓC",
    "**1. Tốc độ**",
    "Trong chuyển động tròn, để đặc trưng cho sự nhanh hay chậm ta cũng dùng khái niệm tốc độ như trong chuyển động thẳng.",
    "Chuyển động tròn đều là chuyển động theo quỹ đạo tròn có tốc độ không thay đổi:",
    "$v = \\frac{s}{t} = \\text{hằng số}$ (31.2)",
    "",
    "**? Câu hỏi:**",
    "Dựa vào việc quan sát chuyển động của kim giây quay đều trong đồng hồ để:",
    "1. So sánh tốc độ của các điểm khác nhau trên kim;",
    "2. So sánh độ dịch chuyển góc trong cùng khoảng thời gian của các điểm khác nhau trên kim.",
    "",
    "**2. Tốc độ góc**",
    "Tốc độ góc trong chuyển động tròn đều bằng độ dịch chuyển góc chia cho thời gian dịch chuyển.",
    "$\\omega = \\frac{\\theta}{t}$ (31.3)",
    "Đơn vị thường dùng của tốc độ góc là rad/s.",
    "Từ công thức (31.1) và (31.2), suy ra:",
    "$v = \\omega.r$ (31.4)",
    "",
    "**EM CÓ BIẾT?**",
    "Ngoài tốc độ, tốc độ góc, trong chuyển động tròn đều người ta còn quan tâm đến các đại lượng như chu kì và tần số.",
    "*Chu kì (kí hiệu là T)* trong chuyển động tròn đều là thời gian để vật quay hết một vòng tròn.",
    "*Tần số (kí hiệu là f)* là số vòng vật đi được trong một giây. Đơn vị tần số là héc (Hz).",
    "Từ các công thức trên ta có công thức tính T và f:",
    "$T = \\frac{1}{f} = \\frac{2.\\pi}{\\omega}$",
    "",
    "**? Câu hỏi:**",
    "1. Hãy tính tốc độ góc của kim giờ và kim phút của đồng hồ.",
    "2. Roto trong một tổ máy của nhà máy thuỷ điện Hoà Bình quay 125 vòng mỗi phút. Hãy tính tốc độ góc của roto này theo đơn vị rad/s.",
    "",
    "## III. VẬN TỐC TRONG CHUYỂN ĐỘNG TRÒN ĐỀU",
    "Ta đã biết trong chuyển động thẳng vận tốc tức thời $\\vec{v}_t$ tại một thời điểm cho bởi:",
    "$\\vec{v}_t = \\frac{\\Delta\\vec{d}}{\\Delta t}$",
    "Khi $\\Delta t$ rất nhỏ, vectơ độ dịch chuyển $\\Delta\\vec{d}$ sẽ tiến tới trùng với tiếp tuyến với đường tròn. Do đó, tại mỗi thời điểm vectơ vận tốc tức thời sẽ có phương trùng với tiếp tuyến của đường tròn (Hình 31.2).",
    "",
    "**? Câu hỏi:**",
    "1. Biết chiều dài kim phút và kim giây của một chiếc đồng hồ lần lượt là 4 cm và 5 cm. Hãy tính:",
    "a) Tỉ số chu kì quay của hai kim.",
    "b) Tỉ số tốc độ của đầu kim phút và đầu kim giây.",
    "2. Xét một điểm nằm trên đường xích đạo trong chuyển động tự quay của Trái Đất. Biết bán kính Trái Đất tại xích đạo là 6 400 km. Hãy tính:",
    "a) Chu kì chuyển động của điểm đó.",
    "b) Tốc độ và tốc độ góc của điểm đó.",
    "",
    "121",
    "CHƯƠNG VI – CHUYỂN ĐỘNG TRÒN ĐỀU",
    "",
    "Trong chuyển động tròn đều, độ lớn của vận tốc tức thời không đổi nhưng hướng luôn thay đổi.",
    "[Hình 31.2. Vectơ vận tốc trong chuyển động tròn. Tại điểm M, vectơ vận tốc $\\vec{v}_M$ tiếp tuyến với đường tròn. Tại điểm N, vectơ vận tốc $\\vec{v}_N$ tiếp tuyến với đường tròn]",
    "",
    "**? Câu hỏi:**",
    "1. Phân biệt tốc độ và vận tốc tức thời trong chuyển động tròn đều.",
    "2. Nêu mối quan hệ giữa tốc độ $v$, chu kì T và bán kính r của một vật chuyển động tròn đều.",
    "3. Một xe đồ chơi chạy với tốc độ không đổi 0,2 m/s trên một đường ray tròn tâm O, đường kính AB theo chiều kim đồng hồ. (Hình 31.3). Xác định sự thay đổi của vận tốc khi xe đi từ A đến B.",
    "[Hình 31.3. Đường ray xe lửa đồ chơi hình tròn có đường kính AB]",
    "",
    "**EM ĐÃ HỌC**",
    "- Chuyển động của một vật theo quỹ đạo tròn với tốc độ không đổi gọi là chuyển động tròn đều.",
    "- Một rađian là góc ở tâm chắn cung có độ dài bằng bán kính đường tròn.",
    "- Tốc độ, tốc độ góc và bán kính quỹ đạo liên hệ với nhau theo công thức: $v = \\omega.r$.",
    "- Trong chuyển động tròn đều, độ lớn vận tốc không đổi nhưng hướng luôn thay đổi.",
    "",
    "**EM CÓ THỂ**",
    "1. Biểu diễn được độ dịch chuyển góc theo rađian.",
    "2. Vận dụng khái niệm tốc độ góc để giải được một số bài tập liên quan.",
    "",
    "122"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B32', 'Bài 32 LỰC HƯỚNG TẢM VÀ GIA TỐC HƯỚNG TÂM', 124, 2, $JSON$
{
  "content": [
    "# Bài 32 LỰC HƯỚNG TẢM VÀ GIA TỐC HƯỚNG TÂM",
    "",
    "**Khởi động:**",
    "*Tại sao Trái Đất chuyển động quanh Mặt Trời? Tại sao trên những đoạn đường vòng thường phải hạn chế tốc độ của xe và mặt đường thường phải hơi nghiêng về phía tâm?*",
    "[Hình ảnh minh họa quỹ đạo Trái Đất quanh Mặt Trời. Có vận tốc v hướng tiếp tuyến và Lực hấp dẫn của Mặt Trời lên Trái Đất hướng vào tâm]",
    "",
    "## I. LỰC HƯỚNG TÂM",
    "Dùng một sợi dây nhẹ không dãn buộc vào một cái tẩy. Quay dây sao cho cái tẩy chuyển động tròn trong mặt phẳng nằm ngang có tâm là đầu dây mà tay giữ (Hình 32.1).",
    "[Hình 32.1. Bạn nam dùng sợi dây quay cái tẩy chuyển động tròn, có lực căng dây kéo vào tâm]",
    "",
    "**? Câu hỏi:**",
    "1. Lực nào sau đây làm cái tẩy chuyển động tròn?",
    "– Trọng lực tác dụng lên cái tẩy.",
    "– Lực cản của không khí.",
    "– Lực căng dây hướng vào tâm quỹ đạo của cái tẩy.",
    "2. Nếu cái tẩy đang chuyển động mà ta buông tay ra thì:",
    "– Cái tẩy tiếp tục chuyển động tròn.",
    "– Cái tẩy sẽ rơi xuống đất theo phương thẳng đứng.",
    "– Cái tẩy văng ra theo phương tiếp tuyến với quỹ đạo theo hướng vận tốc tại điểm đó.",
    "3. Lực nào duy trì chuyển động tròn của Trái Đất xung quanh Mặt Trời?",
    "",
    "*Lực (hay hợp lực) tác dụng lên vật chuyển động tròn đều hướng vào tâm quỹ đạo gọi là lực hướng tâm.*",
    "",
    "**? Câu hỏi:**",
    "Tìm thêm ví dụ về lực hướng tâm.",
    "",
    "## II. GIA TỐC HƯỚNG TÂM",
    "Trong chuyển động tròn đều, lực hướng tâm gây gia tốc hướng vào tâm nên gia tốc này được gọi là gia tốc hướng tâm, kí hiệu là $a_{ht}$:",
    "$a_{ht} = \\frac{v^2}{r} = \\omega^2.r$ (32.1)",
    "",
    "123",
    "CHƯƠNG VI – CHUYỂN ĐỘNG TRÒN ĐỀU",
    "",
    "**EM CÓ BIẾT?**",
    "Để tính độ lớn của gia tốc hướng tâm ta sử dụng công thức gia tốc:",
    "$\\vec{a} = \\frac{\\Delta\\vec{v}}{\\Delta t}$",
    "Khi vật chuyển động tròn đều từ A đến B trong thời gian $\\Delta t$ thì độ dịch chuyển của vật là vectơ $\\vec{AB}$ (Hình 32.2a), có độ lớn là: $d = v.\\Delta t$.",
    "Gọi $\\vec{v}_A$ và $\\vec{v}_B$ là các vectơ vận tốc tức thời tại A và B. Vì chuyển động là tròn đều nên các vectơ này có độ lớn không đổi, chỉ thay đổi về hướng. Sự thay đổi về hướng được biểu diễn bằng vectơ $\\Delta\\vec{v} = \\vec{v}_B - \\vec{v}_A$ (Hình 32.2b).",
    "Tam giác AOB ở Hình 32.2a và tam giác EAC ở Hình 32.2b là hai tam giác cân đồng dạng nên:",
    "$\\frac{\\Delta v}{v} = \\frac{AB}{r} = \\frac{\\Delta v}{v} = \\frac{v.\\Delta t}{r}$",
    "Suy ra: $a_{ht} = \\frac{\\Delta v}{\\Delta t} = \\frac{v^2}{r}$. Vì $v = \\omega.r$ nên: $a_{ht} = \\frac{v^2}{r} = \\omega^2.r$",
    "[Hình 32.2.",
    "a) Chuyển động của vật trên cung tròn từ A đến B, bán kính r, tâm O. Vận tốc tiếp tuyến $\\vec{v}_A, \\vec{v}_B$.",
    "b) Tam giác vectơ vận tốc. $\\vec{v}_B$ và $-\\vec{v}_A$ tạo ra độ biến thiên $\\Delta\\vec{v}$ hướng vào tâm]",
    "",
    "**? Câu hỏi:**",
    "1. Tính gia tốc hướng tâm của một vệ tinh nhân tạo chuyển động tròn đều quanh Trái Đất với bán kính quỹ đạo là 7 000 km và tốc độ 7,57 km/s.",
    "2. Tính gia tốc hướng tâm của Mặt Trăng trong chuyển động quay quanh Trái Đất (coi Mặt Trăng chuyển động tròn đều quanh Trái Đất). Biết khoảng cách từ Mặt Trăng đến tâm Trái Đất là $3,84.10^8$ m và chu kì quay là 27,2 ngày.",
    "3. Kim phút của một chiếc đồng hồ dài 8 cm. Tính gia tốc hướng tâm của đầu kim.",
    "",
    "## III. CÔNG THỨC ĐỘ LỚN LỰC HƯỚNG TÂM",
    "Theo định luật 2 Newton và công thức tính độ lớn của gia tốc hướng tâm ở trên ta có công thức tính độ lớn lực hướng tâm:",
    "$F_{ht} = m.a_{ht} = \\frac{m.v^2}{r} = m.\\omega^2.r$ (32.2)",
    "*Ví dụ về lực hướng tâm:* Một vật nhỏ buộc vào đầu một sợi dây, nếu quay đều và nhanh, sợi dây gần như quay trong mặt phẳng nằm ngang (Hình 32.3). Nếu quay đều và chậm, sợi dây quét thành một mặt nón (Hình 32.4).",
    "",
    "124",
    "CHƯƠNG VI – CHUYỂN ĐỘNG TRÒN ĐỀU",
    "",
    "**EM ĐÃ HỌC**",
    "- Gia tốc trong chuyển động tròn đều luôn hướng vào tâm quỹ đạo và có độ lớn là:",
    "$a_{ht} = \\frac{v^2}{r} = \\omega^2.r$",
    "- Lực (hay hợp lực của các lực) tác dụng vào một vật chuyển động tròn đều và gây ra cho vật gia tốc hướng tâm gọi là lực hướng tâm.",
    "Biểu thức của lực hướng tâm:",
    "$F_{ht} = m.a_{ht} = \\frac{m.v^2}{r} = m.\\omega^2.r$.",
    "",
    "**EM CÓ THỂ**",
    "1. Giải thích lí do vì sao trong thực tế người ta chỉ làm cầu vồng lên chứ không làm cầu võng xuống?",
    "2. Giải thích vì sao trong môn xiếc mô tô bay, diễn viên xiếc có thể đi mô tô trong thành của một cái lồng quay tròn mà không bị rơi (Hình 32.7).",
    "[Hình 32.7. Xiếc mô tô bay]",
    "",
    "**EM CÓ BIẾT?**",
    "**Chuyển động li tâm**",
    "Một vật đặt trên mặt chiếc bàn quay. Nếu tăng tốc độ góc $\\omega$ của bàn quay đến một giá trị nào đó thì lực ma sát nghỉ cực đại nhỏ hơn lực hướng tâm cần thiết ($F_{ht} = m.\\omega^2.r$) để giữ cho vật chuyển động tròn. Khi ấy vật trượt trên bàn ra xa tâm quay, rồi văng ra khỏi bàn theo phương tiếp tuyến với quỹ đạo. Chuyển động như vậy của vật được gọi là chuyển động li tâm (Hình 32.8).",
    "Giải thích tại sao thùng giặt quần áo của máy giặt có nhiều lỗ thủng ở thành xung quanh.",
    "[Hình 32.8. Lực li tâm làm vật văng ra khi lực ma sát nghỉ cực đại không đủ giữ: $F_{\\text{msn(max)}} < m.\\omega^2.r$]",
    "",
    "126"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH7' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI10')), 'B33', 'Bài 33 BIẾN DẠNG CỦA VẬT RẮN', 128, 1, $JSON$
{
  "content": [
    "# Bài 33 BIẾN DẠNG CỦA VẬT RẮN",
    "",
    "**Khởi động:**",
    "*Bungee là một trò chơi mạo hiểm được nhiều người yêu thích. Em có biết trò chơi này được thực hiện dựa trên hiện tượng vật lí nào không?*",
    "[Hình ảnh người chơi Bungee nhảy từ vách núi xuống hồ nước bằng dây chun đàn hồi. Nhảy bungee ở Interlaken, Thuỵ Sĩ]",
    "",
    "## I. BIẾN DẠNG ĐÀN HỒI. BIẾN DẠNG KÉO VÀ BIẾN DẠNG NÉN",
    "Khi không có ngoại lực tác dụng, vật rắn có kích thước và hình dạng xác định. Khi có ngoại lực tác dụng, vật rắn thay đổi hình dạng và kích thước, ta nói vật rắn bị biến dạng.",
    "",
    "**Hoạt động:**",
    "Hãy làm các thí nghiệm về biến dạng sau đây:",
    "– Ép quả bóng cao su vào bức tường (Hình 33.1a).",
    "– Nén lò xo dọc theo trục của nó (Hình 33.1b).",
    "– Kéo hai đầu lò xo dọc theo trục của nó (Hình 33.1c).",
    "– Kéo cho vòng dây cao su dãn ra (Hình 33.1d).",
    "1. Trong mỗi thí nghiệm trên, em hãy cho biết:",
    "– Lực nào làm vật biến dạng?",
    "– Biến dạng nào là biến dạng kéo? Biến dạng nào là biến dạng nén?",
    "– Mức độ biến dạng phụ thuộc vào yếu tố nào?",
    "2. Trong thí nghiệm với lò xo và vòng dây cao su, nếu lực kéo quá lớn thì khi thôi tác dụng lực, chúng có trở về hình dạng, kích thước ban đầu được không?",
    "[Hình 33.1. Các kiểu biến dạng.",
    "a) Ép quả bóng cao su vào tường.",
    "b) Nén lò xo.",
    "c) Kéo lò xo.",
    "d) Kéo vòng dây cao su]",
    "",
    "Như vậy, khi có tác dụng của ngoại lực, vật rắn sẽ bị biến dạng.",
    "Mức độ biến dạng phụ thuộc vào độ lớn của ngoại lực.",
    "Khi không còn tác dụng của ngoại lực, nếu vật rắn lấy lại được hình dạng và kích thước ban đầu thì biến dạng của vật là *biến dạng đàn hồi*.",
    "",
    "128",
    "CHƯƠNG VII – BIẾN DẠNG CỦA VẬT RẮN, ÁP SUẤT CHẤT LỎNG",
    "",
    "Giới hạn mà trong đó vật rắn còn giữ được tính đàn hồi được gọi là giới hạn đàn hồi của vật rắn.",
    "Khi vật chịu tác dụng của cặp lực nén ngược chiều nhau, vuông góc với bề mặt của vật và hướng vào phía trong vật, ta có biến dạng nén (Hình 33.2b).",
    "Khi vật chịu tác dụng của cặp lực kéo ngược chiều nhau, vuông góc với bề mặt của vật và hướng ra phía ngoài vật, ta có biến dạng kéo (Hình 33.2c).",
    "[Hình 33.2. Một số hình dạng của vật rắn.",
    "a) Khi chưa bị biến dạng.",
    "b) Khi bị biến dạng nén.",
    "c) Khi bị biến dạng kéo]",
    "",
    "## II. LỰC ĐÀN HỒI. ĐỊNH LUẬT HOOKE",
    "**1. Lực đàn hồi của lò xo**",
    "Khi ta nén hoặc kéo hai đầu lò xo, tay ta cũng chịu tác dụng các lực từ phía lò xo. Các lực này ngược chiều với lực tay tác dụng vào lò xo và được gọi là lực đàn hồi của lò xo. Lực đàn hồi của lò xo chống lại nguyên nhân làm nó biến dạng và có xu hướng đưa nó về hình dạng và kích thước ban đầu.",
    "",
    "**Hoạt động:**",
    "Với các dụng cụ sau đây: giá đỡ thí nghiệm; các lò xo; hộp quả cân; thước đo.",
    "– Thiết kế và thực hiện phương án thí nghiệm tìm mối quan hệ giữa độ lớn của lực đàn hồi và độ biến dạng của lò xo.",
    "– Hãy thể hiện kết quả trên đồ thị về sự phụ thuộc của lực đàn hồi vào độ biến dạng của lò xo.",
    "– Thảo luận và nhận xét kết quả thu được.",
    "",
    "**? Câu hỏi:**",
    "1. Em hãy cho biết loại biến dạng trong mỗi trường hợp sau:",
    "a) Cột chịu lực trong toà nhà.",
    "b) Cánh cung khi kéo dây cung.",
    "2. Tìm thêm ví dụ về biến dạng nén và biến dạng kéo trong đời sống.",
    "",
    "**2. Định luật Hooke**",
    "Hình 33.3 là đồ thị về sự phụ thuộc độ lớn của lực đàn hồi vào độ biến dạng của lò xo:",
    "Đoạn OA trên đồ thị cho biết sự phụ thuộc độ lớn của lực đàn hồi $F_{đh}$ vào độ biến dạng $\\Delta\\ell$ là tuyến tính, ta có thể viết sự phụ thuộc này bằng biểu thức toán học:",
    "$F_{đh} = k|\\Delta\\ell|$ (33.1)",
    "Biểu thức trên là biểu thức của định luật Hooke: *“Trong giới hạn đàn hồi, độ lớn lực đàn hồi của lò xo tỉ lệ thuận với độ biến dạng của lò xo”.*",
    "[Hình 33.3. Đồ thị biểu diễn sự phụ thuộc lực đàn hồi vào độ dãn của lò xo. Trục tung F, trục hoành $\\Delta\\ell$. Đoạn OA là đường thẳng đi qua gốc toạ độ O]",
    "Trong biểu thức trên, k là một hằng số với một lò xo xác định, được gọi là hệ số đàn hồi hay độ cứng của lò xo, phụ thuộc vào kích thước, hình dạng và vật liệu của lò xo. Trong hệ SI, k có đơn vị là N/m.",
    "",
    "129",
    "CHƯƠNG VII – BIẾN DẠNG CỦA VẬT RẮN, ÁP SUẤT CHẤT LỎNG",
    "",
    "Trong đời sống, người ta có thể ứng dụng định luật Hooke để chế tạo lực kế, cân lò xo (Hình 33.4). Trong trường hợp đó, người ta đã sử dụng lò xo trong giới hạn đàn hồi của nó.",
    "[Hình 33.4. Cân lò xo loại to và loại nhỏ]",
    "",
    "**? Câu hỏi:**",
    "1. Một lò xo có chiều dài tự nhiên 15 cm. Lò xo được giữ cố định tại một đầu, còn đầu kia chịu một lực kéo bằng 4,5 N. Khi ấy lò xo dài 18 cm. Độ cứng của lò xo bằng bao nhiêu?",
    "2. Một lò xo có độ cứng là 100 N/m. Nếu chịu một lực kéo bằng 1 N thì lò xo sẽ bị dãn ra một đoạn bằng bao nhiêu?",
    "3. Một lò xo có chiều dài tự nhiên $l_0$ = 20 cm và độ cứng k = 20 N/m. Có thể dùng lò xo này để tạo ra một lực đẩy bằng 1 N được không? Nếu có, chiều dài của lò xo khi đó bằng bao nhiêu?",
    "",
    "**EM ĐÃ HỌC**",
    "- Biến dạng nén: Kích thước vật rắn dọc theo phương tác dụng của lực nén giảm so với kích thước tự nhiên.",
    "- Biến dạng kéo: Kích thước của vật rắn dọc theo phương tác dụng lực kéo tăng so với kích thước tự nhiên.",
    "- Định luật Hooke: Trong giới hạn đàn hồi, độ lớn lực đàn hồi của lò xo tỉ lệ thuận với độ biến dạng của lò xo: $F_{đh} = k|\\Delta\\ell|$.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được sự làm việc của lực kế, các loại cân dùng lò xo.",
    "- Thực hiện được thí nghiệm với các vật liệu thông thường như dây cao su, lò xo bút bi,... để rút ra được định luật Hooke.",
    "",
    "130",
    "CHƯƠNG VII – BIẾN DẠNG CỦA VẬT RẮN, ÁP SUẤT CHẤT LỎNG",
    "",
    "Phần đồ thị ngoài đoạn thẳng OA ứng với lực đặt vào vượt quá giới hạn đàn hồi của lò xo. Khi đó lực đàn hồi không còn tỉ lệ thuận với độ biến dạng nữa. Nếu treo vật nặng có khối lượng quá lớn, tính đàn hồi của lò xo sẽ bị phá huỷ.",
    "*Bài tập ví dụ:* Một lò xo bố trí theo phương thẳng đứng và có gắn vật nặng khối lượng 200 g. Khi vật treo ở dưới (Hình 33.4a) thì lò xo dài 17 cm, khi vật đặt ở trên (Hình 33.4b) thì lò xo dài 13 cm. Lấy g = 10 m/s$^2$ và bỏ qua trọng lượng của móc treo, giá đỡ vật nặng. Tính độ cứng của lò xo.",
    "*Giải*",
    "Trong hai trường hợp, vật nặng chịu tác dụng của lực đàn hồi và trọng lực. Xét vật nặng ở vị trí cân bằng.",
    "Khi vật treo ở dưới lò xo: $F_{đh1} = P \\Rightarrow k|0,17 - \\ell_0| = m.g$ (1)",
    "Khi đặt vật ở trên lò xo: $F_{đh2} = P \\Rightarrow k|0,13 - \\ell_0| = m.g$ (2)",
    "Từ (1) và (2) $\\Rightarrow \\ell_0 = 0,15$ (m). Thay vào (1) hoặc (2), tính được k = 100 (N/m).",
    "",
    "**! Chú ý:**",
    "Trong công thức (33.1), nếu khi biến dạng (dãn hoặc nén) chiều dài lò xo bằng $\\ell$ và chiều dài khi chưa biến dạng bằng $\\ell_0$ thì độ biến dạng là:",
    "$\\Delta\\ell = \\ell - \\ell_0$, ta có thể viết lại:",
    "$F = k|\\ell - \\ell_0|$",
    "[Hình 33.4. a) Vật treo dưới lò xo. b) Vật đặt trên lò xo]",
    "*(Lưu ý: sách đánh số hình này là Hình 33.4, nhưng hình Cân lò xo ở trang trước cũng là Hình 33.4)*",
    "",
    "**Hoạt động:**",
    "1. Từ kết quả thu được trong hoạt động ở mục 1, hãy tính độ cứng của lò xo đã dùng làm thí nghiệm. Tại sao khối lượng lò xo cần rất nhỏ so với khối lượng của các vật nặng treo vào nó?",
    "2. Trên Hình 33.5 là đồ thị sự phụ thuộc của độ lớn lực đàn hồi F vào độ biến dạng $\\Delta\\ell$ của 3 lò xo khác nhau A, B và C.",
    "a) Lò xo nào có độ cứng lớn nhất?",
    "b) Lò xo nào có độ cứng nhỏ nhất?",
    "c) Lò xo nào không tuân theo định luật Hooke?",
    "[Hình 33.5. Đồ thị F - $\\Delta\\ell$ của 3 lò xo A, B, C. A là đường cong. B và C là đoạn thẳng đi qua gốc toạ độ, B dốc hơn C]",
    "",
    "**EM ĐÃ HỌC**",
    "- Biến dạng đàn hồi. Biến dạng kéo, biến dạng nén.",
    "- Đặc điểm biến dạng và độ cứng của lò xo.",
    "- Liên hệ giữa lực đàn hồi và độ biến dạng của lò xo, định luật Hooke: $F = k|\\Delta\\ell|$.",
    "",
    "**EM CÓ THỂ**",
    "Giải thích được nguyên tắc hoạt động của bộ phận giảm xóc trong ô tô, xe máy.",
    "",
    "130"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

