{
  "content": [
    "# Bài 34 KHỐI LƯỢNG RIÊNG. ÁP SUẤT CHẤT LỎNG",
    "",
    "**Khởi động:**",
    "*Khối lượng riêng của một chất lỏng và áp suất của chất lỏng có mối quan hệ như thế nào?*",
    "",
    "## I. KHỐI LƯỢNG RIÊNG",
    "Khối lượng riêng của một chất là khối lượng của một đơn vị thể tích chất đó:",
    "$\\text{Khối lượng riêng} = \\frac{\\text{Khối lượng}}{\\text{Thể tích}}$",
    "$\\rho = \\frac{m}{V}$ (34.1)",
    "Đơn vị của khối lượng riêng trong hệ SI là kg/m$^3$ (kg.m$^{-3}$). Người ta cũng dùng đơn vị khối lượng riêng là g/cm$^3$ (g.cm$^{-3}$).",
    "$1 \\text{ g/cm}^3 = 1000 \\text{ kg/m}^3$",
    "",
    "**Bảng 34.1.** Khối lượng riêng của một số chất ở điều kiện bình thường về nhiệt độ và áp suất",
    "| Chất rắn | $\\rho$ (kg/m$^3$) | Chất lỏng | $\\rho$ (kg/m$^3$) | Chất khí | $\\rho$ (kg/m$^3$) |",
    "|---|---|---|---|---|---|",
    "| Chì | 11 300 | Thuỷ ngân | 13 500 | Carbonic | 1,98 |",
    "| Đồng | 8 900 | Nước | 999 | Oxygen | 1,43 |",
    "| Thép | 7 800 | Xăng | 700 | Hydrogen | 0,09 |",
    "",
    "**? Câu hỏi:**",
    "1. Tại sao khối lượng riêng của một chất lại phụ thuộc vào nhiệt độ?",
    "2. Một hợp kim đồng và bạc có khối lượng riêng là 10,3 g/cm$^3$. Tính khối lượng của bạc và đồng có trong 100 g hợp kim. Biết khối lượng riêng của đồng là 8,9 g/cm$^3$, của bạc là 10,4 g/cm$^3$.",
    "",
    "**Bảng 34.2.** Khối lượng riêng của nước ở các nhiệt độ khác nhau",
    "| Nhiệt độ | $\\rho$ (kg/m$^3$) |",
    "|---|---|",
    "| $20^\\circ$C | 999 |",
    "| $40^\\circ$C | 992 |",
    "| $60^\\circ$C | 983 |",
    "| $80^\\circ$C | 972 |",
    "",
    "## II. ÁP LỰC VÀ ÁP SUẤT",
    "**1. Áp lực**",
    "**a) Khái niệm áp lực**",
    "Một cuốn sách nằm yên trên mặt bàn nằm ngang chịu tác dụng của hai lực cân bằng là lực hút của Trái Đất và lực đẩy của mặt bàn (Hình 34.1a).",
    "Do mặt bàn tác dụng lên cuốn sách lực $\\vec{F}$ có phương thẳng đứng, chiều hướng lên trên và có độ lớn bằng trọng lượng P của cuốn sách, nên theo định luật 3 Newton: cuốn sách tác dụng lên mặt bàn lực $\\vec{F}_N$ có phương thẳng đứng, chiều hướng xuống dưới và có độ lớn bằng F. Lực $\\vec{F}_N$ ép lên mặt bàn theo phương vuông góc với mặt bàn, được gọi là áp lực (Hình 34.1b).",
    "",
    "[Hình 34.1.",
    "a) Cuốn sách chịu lực kéo P của Trái đất và phản lực F của bàn.",
    "b) Cuốn sách tác dụng áp lực $F_N$ lên mặt bàn]",
    "",
    "$^{(1)}$ Kí hiệu $\\rho$ đọc là \"rô\".",
    "",
    "131",
    "CHƯƠNG VII – BIẾN DẠNG CỦA VẬT RẮN, ÁP SUẤT CHẤT LỎNG",
    "",
    "**b) Áp lực phụ thuộc những yếu tố nào?**",
    "**? Câu hỏi:**",
    "Hãy dựa vào thí nghiệm vẽ ở Hình 34.2, cho biết độ lớn của áp lực phụ thuộc vào những yếu tố nào và phụ thuộc như thế nào.",
    "[Hình 34.2. Thí nghiệm về áp lực.",
    "(1) Khối chữ nhật dựng đứng, lún sâu vào cát.",
    "(2) Khối chữ nhật nằm ngang, lún ít hơn (1).",
    "(3) Khối chữ nhật nằm ngang, có thêm một khối khác đè lên, lún sâu hơn (2)]",
    "",
    "**? Câu hỏi:**",
    "1. Trong Hình 34.3, lực nào sau đây là lực đàn hồi, lực ma sát, áp lực?",
    "a) Lực của chân em bé tác dụng lên sàn nhà.",
    "b) Lực của tay em bé kéo hộp đồ chơi.",
    "c) Lực của hộp đồ chơi tác dụng lên sàn nhà.",
    "[Hình 34.3. Bé gái đang kéo xe đồ chơi trên sàn nhà]",
    "",
    "**2. Áp suất**",
    "Do tác dụng của áp lực lên mặt bị ép càng mạnh khi cường độ của áp lực càng lớn và diện tích mặt bị ép càng nhỏ, nên để đặc trưng cho tác dụng của áp lực người ta dùng khái niệm áp suất, có độ lớn bằng áp lực chia cho diện tích bị ép.",
    "$\\text{Áp suất} = \\frac{\\text{Áp lực}}{\\text{Diện tích bị ép}}$",
    "$p = \\frac{F_N}{S}$ (34.2)",
    "Đơn vị của áp suất là N/m$^2$, có tên gọi là paxcan (Pa):",
    "$1 \\text{ Pa} = 1 \\text{ N/m}^2$",
    "",
    "**? Câu hỏi:**",
    "1. Tại sao xe tăng nặng hơn ô tô nhiều lần lại có thể chạy bình thường trên đất bùn (Hình 34.5a), còn ô tô bị lún bánh và sa lầy trên chính quãng đường này (Hình 34.5b)?",
    "[Hình 34.5. a) Xe tăng đi trên bùn. b) Ô tô lún trên bùn]",
    "2. Trong hai chiếc xẻng vẽ ở Hình 34.6, xẻng nào dùng để xén đất tốt hơn, xẻng nào dùng để xúc đất tốt hơn? Tại sao?",
    "[Hình 34.6. a) Xẻng vuông mũi thẳng. b) Xẻng nhọn mũi cong]",
    "3. Một người nặng 50 kg đứng trên mặt đất nằm ngang. Biết diện tích tiếp xúc của mỗi bàn chân với đất là 0,015 m$^2$. Tính áp suất người đó tác dụng lên mặt đất khi:",
    "a) Đứng cả hai chân.",
    "b) Đứng một chân.",
    "",
    "**? Câu hỏi:**",
    "2. Chứng minh rằng áp lực của cuốn sách tác dụng lên mặt bàn nằm nghiêng một góc $\\alpha$ (Hình 34.4) có độ lớn là:",
    "$F_N = P.\\cos\\alpha$",
    "[Hình 34.4. Cuốn sách trên mặt phẳng nghiêng góc $\\alpha$]",
    "",
    "**Bảng 34.3.** Độ lớn của một số áp suất",
    "| Áp suất tại một số vị trí | p (Pa) |",
    "|---|---|",
    "| Áp suất ở tâm Trái Đất | $4.10^{11}$ |",
    "| Áp suất của nước ở đáy biển sâu nhất | $1,1.10^8$ |",
    "| Áp suất của không khí trong lốp ô tô | $4.10^5$ |",
    "| Áp suất khí quyển ở độ cao của mặt nước biển | $1.10^5$ |",
    "",
    "132",
    "CHƯƠNG VII – BIẾN DẠNG CỦA VẬT RẮN, ÁP SUẤT CHẤT LỎNG",
    "",
    "## III. ÁP SUẤT CỦA CHẤT LỎNG",
    "**1. Sự tồn tại áp suất của chất lỏng**",
    "Khi đặt vật rắn lên mặt bàn thì vật rắn tác dụng lên mặt bàn áp suất theo phương vuông góc với mặt bàn. Khi nhấn chìm một vật vào trong nước thì nước có gây áp suất lên vật không? Nếu có thì áp suất này có giống áp suất của vật rắn không?",
    "Ai lặn xuống nước cũng dễ cảm thấy áp suất của nước tác dụng lên cơ thể mình, càng lặn sâu thì áp suất càng mạnh. Tuy nhiên, áp suất này có phải chỉ tác dụng theo một phương như áp suất của vật rắn không?",
    "",
    "**Hoạt động:**",
    "Hãy dựa vào thí nghiệm với một bình cầu có các lỗ nhỏ ở thành bình trong các Hình 34.7a và 34.7b để nói về sự tồn tại áp suất của chất lỏng và đặc điểm của áp suất này so với áp suất của vật rắn.",
    "[Hình 34.7.",
    "a) Bóp bóp cao su, nước phụt ra từ các lỗ nhỏ trên quả cầu theo mọi hướng.",
    "b) Nhúng quả cầu có màng cao su bọc lỗ nhỏ vào nước, các màng cao su lõm vào]",
    "",
    "**2. Công thức tính áp suất của chất lỏng**",
    "Có thể xác định được công thức tính áp suất của chất lỏng dựa trên bài toán sau đây:",
    "",
    "**? Câu hỏi:**",
    "Một khối chất lỏng đứng yên có khối lượng riêng $\\rho$, hình trụ diện tích đáy S, chiều cao h (Hình 34.8). Hãy dùng công thức tính áp suất ở trên để chứng minh rằng áp suất của khối chất lỏng trên tác dụng lên đáy bình có độ lớn là $p = \\rho.g.h$.",
    "Trong đó:",
    "p là áp suất của chất lỏng tác dụng lên đáy bình;",
    "$\\rho$ là khối lượng riêng của chất lỏng;",
    "g là gia tốc trọng trường;",
    "h là chiều cao của cột chất lỏng, cũng là độ sâu của chất lỏng so với mặt thoáng.",
    "[Hình 34.8. Một khối chất lỏng hình trụ trong bình]",
    "",
    "Trên mặt thoáng của chất lỏng, còn có áp suất khí quyển $p_a$. Áp suất này được chất lỏng truyền nguyên vẹn xuống đáy bình. Do đó, đáy bình chịu áp suất $p = p_a + \\rho.g.h$.",
    "Chất lỏng truyền áp suất theo mọi hướng nên áp suất mà ta tính được ở trên cũng là áp suất của chất lỏng tác dụng lên các điểm ở thành bình có khoảng cách tới mặt thoáng chất lỏng là h.",
    "",
    "133",
    "CHƯƠNG VII – BIẾN DẠNG CỦA VẬT RẮN, ÁP SUẤT CHẤT LỎNG",
    "",
    "**? Câu hỏi:**",
    "Một khối hình lập phương có cạnh 0,30 m, khối lập phương chìm $\\frac{2}{3}$ trong nước. Biết khối lượng riêng của nước là 1 000 kg/m$^3$. Tính áp suất của nước tác dụng lên mặt dưới của khối lập phương và xác định phương, chiều, cường độ của lực gây ra bởi áp suất này.",
    "",
    "**Hoạt động:**",
    "Hãy tìm cách dựa vào các dụng cụ thí nghiệm vẽ ở Hình 34.9 để nghiệm lại công thức tính áp suất của chất lỏng: $p = \\rho.g.h$.",
    "[Hình 34.9. Thí nghiệm nghiệm lại công thức tính áp suất. Dụng cụ gồm ống thuỷ tinh hở hai đầu, một đĩa nhựa tròn, một sợi dây buộc vào đĩa nhựa, một bình chứa nước]",
    "",
    "**? Câu hỏi:**",
    "1. Tính độ chênh lệch áp suất của nước giữa 2 điểm thuộc 2 mặt phẳng nằm ngang cách nhau 20 cm.",
    "2. Hãy dùng phương trình cơ bản của chất lưu đứng yên để chứng minh rằng áp suất ở các điểm nằm trên cùng mặt phẳng nằm ngang trong chất lỏng thì bằng nhau.",
    "3. Hãy dùng phương trình cơ bản của chất lưu đứng yên để chứng minh định luật Archimedes đã học ở lớp 8 cho trường hợp vật hình hộp chữ nhật có chiều cao h, làm bằng vật liệu có khối lượng riêng $\\rho$.",
    "",
    "**3. Phương trình cơ bản của chất lưu đứng yên**",
    "Có thể dễ dàng tính được độ chênh lệch về áp suất của chất lưu giữa 2 điểm M và N có độ sâu $h_1$ và $h_2$ so với mặt thoáng của chất lưu đứng yên (Hình 34.10).",
    "Vì $p_N = p_a + \\rho.g.h_1$ và $p_M = p_a + \\rho.g.h_2$",
    "nên $p_N - p_M = \\rho.g.(h_1 - h_2)$",
    "hay $\\Delta p = \\rho.g.\\Delta h$ (34.3)",
    "Phương trình trên được gọi là phương trình cơ bản của chất lưu đứng yên.",
    "[Hình 34.10. Hai điểm M và N trong lòng chất lỏng ở độ sâu $h_1$ và $h_2$. Chênh lệch độ sâu là $\\Delta h$]",
    "*(Lưu ý: sách ghi $p_N = p_a + \\rho.g.h_1$ nhưng trên hình N nằm dưới M, vậy $h_1$ phải lớn hơn $h_2$, tức là $h_N = h_1$ và $h_M = h_2$.)*",
    "",
    "**Hoạt động TRẢI NGHIỆM**",
    "Hãy dùng các dụng cụ sau đây:",
    "– Một lực kế.",
    "– Một quả nặng hình trụ có móc treo.",
    "– Một bình chia độ đựng nước.",
    "Thiết kế phương án thí nghiệm minh hoạ cho phương trình cơ bản của chất lưu đứng yên.",
    "",
    "134",
    "CHƯƠNG VII – BIẾN DẠNG CỦA VẬT RẮN, ÁP SUẤT CHẤT LỎNG",
    "",
    "**EM CÓ BIẾT?**",
    "Phương trình cơ bản của thuỷ tĩnh học cho thấy sự chênh lệch của áp suất chất lỏng không phụ thuộc vào thể tích chất lỏng (tức lượng chất lỏng) mà chỉ phụ thuộc vào sự chênh lệch về độ sâu. Sự chênh lệch về áp suất với cùng một độ lớn trong một ống nước rất nhỏ, cũng giống như trong một hồ nước rộng, trong một đại dương.",
    "Chỉ cần đổ khoảng 1 lít nước vào đầy một ống thuỷ tinh cao khoảng 10 m là đủ để gây ra áp suất làm vỡ toang thùng gỗ đựng đầy nước ở dưới (Hình 34.11).",
    "[Hình 34.11. Thí nghiệm làm vỡ thùng gỗ tô-nô của Pascal. Một thùng gỗ kín chứa đầy nước, một ống thuỷ tinh nhỏ và cao cắm vào thùng. Nước được đổ đầy ống thuỷ tinh, thùng gỗ bị vỡ do áp suất lớn]",
    "",
    "**EM ĐÃ HỌC**",
    "- Công thức tính khối lượng riêng: $\\rho = \\frac{m}{V}$. Đơn vị khối lượng riêng: kg/m$^3$; g/cm$^3$",
    "(1 g/cm$^3$ = 1 000 kg/m$^3$).",
    "- Công thức tính áp suất: $p = \\frac{F_N}{S}$, trong đó $F_N$ là áp lực vuông góc với mặt bị ép, S là diện tích mặt bị ép. Đơn vị của áp suất là Pa: 1 Pa = 1 N/m$^2$.",
    "- Công thức tính áp suất của chất lỏng: $p = p_a + \\rho.g.h$, trong đó: $\\rho$ là khối lượng riêng của chất lỏng, g là gia tốc trọng trường, h là độ sâu của chất lỏng.",
    "- Phương trình cơ bản của chất lưu đứng yên: $\\Delta p = \\rho.g.\\Delta h$.",
    "",
    "**EM CÓ THỂ**",
    "Giải thích được vì sao người thợ lặn muốn lặn sâu dưới biển phải được trang bị thiết bị lặn chuyên dụng.",
    "",
